:root {
  --bg: #f7f8fa;
  --panel: #ffffff;
  --panel-strong: #eef3f8;
  --text: #17202a;
  --muted: #637083;
  --line: #d9e0e8;
  --accent: #007a5a;
  --accent-strong: #005f46;
  --danger: #b42318;
  --warning: #8a5a00;
  --good: #067647;
  --shadow: 0 8px 20px rgba(18, 30, 45, 0.08);
  --font-sans: "Google Sans", Arial, Helvetica, sans-serif;
  --app-content-inset-x: 24px;
}

/* Self-hosted Google Sans only (woff2). Sources: fonts/google-sans-src/*.ttf
   No local() ? installed Google Sans Text can shadow / miss glyphs vs our faces.
   Preload Regular from app/layout.tsx; Medium/Bold load on demand. */
@font-face {
  font-family: "Google Sans";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/fonts/google-sans/GoogleSans-Regular.woff2") format("woff2");
}

@font-face {
  font-family: "Google Sans";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/fonts/google-sans/GoogleSans-Medium.woff2") format("woff2");
}

@font-face {
  font-family: "Google Sans";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/fonts/google-sans/GoogleSans-Medium.woff2") format("woff2");
}

@font-face {
  font-family: "Google Sans";
  font-style: normal;
  font-weight: 650;
  font-display: swap;
  src: url("/fonts/google-sans/GoogleSans-Bold.woff2") format("woff2");
}

@font-face {
  font-family: "Google Sans";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/fonts/google-sans/GoogleSans-Bold.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
select {
  font: inherit;
}

button {
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  cursor: pointer;
  min-height: 36px;
  padding: 0 12px;
}

button:hover {
  border-color: #9aa8b7;
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

button.primary:hover {
  background: var(--accent-strong);
}

button.danger {
  color: var(--danger);
  border-color: #f0b8b2;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

a {
  color: var(--accent-strong);
}

.auth-loading {
  align-items: center;
  color: var(--muted);
  display: flex;
  min-height: 100vh;
  justify-content: center;
}

.auth-boot {
  align-items: center;
  background:
    radial-gradient(circle at top left, rgba(0, 122, 90, 0.12), transparent 28rem),
    var(--bg);
  display: flex;
  justify-content: center;
  min-height: 100vh;
  padding: 24px;
}

.auth-boot__card {
  align-items: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  max-width: 22rem;
  padding: 1.6rem 1.5rem 1.45rem;
  text-align: center;
  width: 100%;
}

.auth-boot__spinner,
.state-panel__spinner {
  animation: auth-boot-spin 0.85s linear infinite;
  border: 2px solid color-mix(in srgb, var(--accent) 18%, #e5e7eb);
  border-radius: 999px;
  border-top-color: var(--accent);
  display: block;
  flex: 0 0 auto;
  height: 1.55rem;
  width: 1.55rem;
}

.auth-boot__brand {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.auth-boot__message {
  color: var(--text);
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1.4;
  margin: 0;
}

@keyframes auth-boot-spin {
  to {
    transform: rotate(360deg);
  }
}

.auth-page {
  align-items: center;
  background:
    radial-gradient(ellipse 80% 60% at 12% 18%, color-mix(in srgb, var(--accent) 22%, transparent), transparent 55%),
    radial-gradient(ellipse 70% 50% at 88% 82%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 50%),
    var(--bg);
  display: flex;
  min-height: 100vh;
  justify-content: center;
  padding: 28px 20px;
}

.auth-stage {
  align-items: stretch;
  animation: auth-stage-in 420ms ease-out both;
  display: grid;
  gap: 0;
  max-width: 920px;
  width: 100%;
}

.auth-brand {
  animation: auth-brand-in 520ms ease-out both;
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--accent) 88%, #003d2e) 0%, var(--accent-strong) 55%, #014d38 100%);
  border-radius: 20px 0 0 20px;
  color: #f4fbf8;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 36px 32px 32px;
}

.auth-brand__logo {
  display: block;
  height: 44px;
  margin: 0 0 16px;
  width: 44px;
  border-radius: 10px;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.2);
}

.auth-brand__title {
  font-size: clamp(1.85rem, 2.4vw, 2.35rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.15;
  margin: 0 0 12px;
}

.auth-brand__workflow {
  color: color-mix(in srgb, #fff 82%, transparent);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1.45;
  margin: 0 0 18px;
}

.auth-brand__visual {
  margin: 0 0 18px;
  overflow: hidden;
  border-radius: 14px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.22);
  border: 1px solid color-mix(in srgb, #fff 16%, transparent);
  background: color-mix(in srgb, #000 18%, transparent);
}

.auth-brand__art {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: center;
}

.auth-brand__copy {
  color: color-mix(in srgb, #fff 72%, transparent);
  font-size: 0.95rem;
  line-height: 1.55;
  margin: 0;
  max-width: 32ch;
}

.auth-card {
  animation: auth-card-in 480ms ease-out 60ms both;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 0 20px 20px 0;
  box-shadow: var(--shadow);
  padding: 36px 32px;
  width: 100%;
}

.auth-stage .auth-card {
  border-left: none;
}

.auth-card h1 {
  font-size: 1.55rem;
  letter-spacing: -0.02em;
  margin: 0 0 8px;
}

.auth-copy,
.auth-switch {
  color: var(--muted);
  line-height: 1.5;
}

.auth-copy--compact {
  font-size: 0.92rem;
  margin: 0;
}

.auth-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 22px;
}

.auth-form label {
  color: var(--muted);
  display: flex;
  flex-direction: column;
  font-size: 13px;
  font-weight: 700;
  gap: 6px;
}

.auth-form input {
  border: 1px solid var(--line);
  border-radius: 8px;
  min-height: 42px;
  padding: 8px 12px;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}

.auth-form input:focus {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  outline: none;
}

.auth-error {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  margin: 2px 0 0;
  padding: 0.75rem 0.85rem;
  border-radius: 10px;
  border: 1px solid #fecaca;
  border-left: 3px solid #dc2626;
  background: #fffafa;
  color: #7f1d1d;
  animation: auth-error-in 180ms ease-out;
}

.auth-error__icon {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  margin-top: 0.05rem;
  border-radius: 999px;
  background: #fee2e2;
  color: #b91c1c;
}

.auth-error__icon svg {
  display: block;
}

.auth-error__body {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.auth-error__title {
  font-size: 0.9rem;
  font-weight: 700;
  line-height: 1.3;
  color: #991b1b;
}

.auth-error__message {
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.45;
  color: #9f1239;
}

@keyframes auth-error-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.auth-switch {
  margin: 18px 0 0;
}

@keyframes auth-stage-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes auth-brand-in {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes auth-card-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.auth-brand--ops {
  background:
    linear-gradient(160deg, #1a2e28 0%, #243b34 45%, #1f332c 100%);
}

@media (min-width: 800px) {
  .auth-stage {
    grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  }
}

@media (max-width: 799px) {
  .auth-stage {
    gap: 0;
    max-width: 440px;
  }

  .auth-brand {
    border-radius: 20px 20px 0 0;
    padding: 28px 24px 24px;
  }

  .auth-brand__title {
    font-size: 1.65rem;
  }

  .auth-brand__copy {
    max-width: none;
  }

  .auth-card {
    border-left: 1px solid var(--line);
    border-radius: 0 0 20px 20px;
    padding: 28px 24px;
  }

  .auth-stage .auth-card {
    border-left: 1px solid var(--line);
  }
}

/* Standalone auth cards (register/invite) keep centered single-panel shape */
.auth-page > .auth-card {
  border-radius: 16px;
  max-width: 480px;
}

.app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  min-height: 100vh;
}

.app-sidebar {
  background: #ffffff;
  border-right: 1px solid var(--line);
  height: 100vh;
  overflow-y: auto;
  padding: 18px 14px;
  position: sticky;
  top: 0;
}

.app-brand {
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  display: flex;
  flex-direction: row;
  gap: 10px;
  margin-bottom: 18px;
  padding: 12px;
  text-decoration: none;
}

.app-brand__mark {
  flex: 0 0 auto;
  line-height: 0;
}

.app-brand__mark img {
  border-radius: 7px;
  display: block;
  height: 28px;
  width: 28px;
}

.app-brand__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.app-brand__text span {
  color: var(--muted);
  font-size: 13px;
}

.app-brand__text strong {
  font-size: 16px;
  line-height: 1.2;
}

.app-brand span {
  color: var(--muted);
  font-size: 12px;
}

.app-brand strong {
  font-size: 18px;
}

.app-nav-section {
  border-top: 1px solid var(--line);
  padding: 14px 0;
}

.app-nav-section h3 {
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0;
  margin: 0 0 8px;
  text-transform: uppercase;
}

.app-nav-items {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.app-nav-item {
  align-items: center;
  border: 1px solid transparent;
  border-radius: 8px;
  color: var(--text);
  display: grid;
  gap: 8px;
  grid-template-columns: 1fr auto;
  padding: 9px 10px;
  text-decoration: none;
}

.app-nav-item:hover,
.app-nav-item.active {
  background: #eef3f8;
  border-color: var(--line);
}

.app-nav-item.active {
  box-shadow: inset 3px 0 0 var(--accent);
}

.app-nav-item.active strong {
  color: var(--accent-strong);
}

.app-nav-item strong,
.app-nav-item small {
  display: block;
}

.app-nav-item small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
  margin-top: 2px;
}

.app-main {
  min-width: 0;
}

.app-topbar {
  align-items: center;
  background: #ffffff;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 16px;
  justify-content: space-between;
  padding: 18px var(--app-content-inset-x);
}

.app-topbar-context {
  min-width: 260px;
}

.app-breadcrumbs {
  align-items: center;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 12px;
  gap: 6px;
}

.app-breadcrumbs span {
  align-items: center;
  display: inline-flex;
  gap: 6px;
}

.app-breadcrumbs span + span::before {
  color: #9aa8b7;
  content: "/";
}

.app-breadcrumbs a {
  color: var(--muted);
  text-decoration: none;
}

.app-breadcrumbs a:hover {
  color: var(--accent-strong);
}

.app-topbar h1 {
  font-size: 24px;
  margin: 4px 0;
}

.app-topbar p,
.app-topbar-meta p {
  color: var(--muted);
  margin: 0;
}

.app-topbar-meta {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.app-topbar-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.app-topbar-command-bar {
  align-items: center;
  display: flex;
  flex-shrink: 0;
  gap: 10px;
  justify-content: flex-end;
  max-width: min(100%, 820px);
}

.app-topbar-page-actions {
  align-items: center;
  display: inline-flex;
  flex-wrap: nowrap;
  gap: 6px;
}

.app-topbar-page-action__icon {
  display: block;
  flex: 0 0 auto;
  height: 0.9rem;
  width: 0.9rem;
}

.app-topbar-command-cluster {
  align-items: center;
  display: inline-flex;
  flex-wrap: nowrap;
  gap: 6px;
  position: relative;
  z-index: 60;
}

.app-topbar-btn,
.app-topbar-menu summary,
.app-topbar-page-actions button,
.app-topbar-page-actions a {
  align-items: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: 12.5px;
  font-weight: 500;
  gap: 5px;
  justify-content: center;
  line-height: 1.2;
  min-height: 32px;
  padding: 0 10px;
  text-decoration: none;
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease;
  white-space: nowrap;
}

.app-topbar-btn:focus-visible,
.app-topbar-menu summary:focus-visible,
.app-topbar-page-actions button:focus-visible,
.app-topbar-page-actions a:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 55%, white);
  outline-offset: 2px;
}

.app-topbar-page-actions button:disabled,
.app-topbar-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.app-topbar-btn:hover,
.app-topbar-menu summary:hover,
.app-topbar-page-actions a:hover,
.app-topbar-page-actions button:not(:disabled):hover {
  background: #f4f8f6;
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
}

.app-topbar-btn.is-primary,
.app-topbar-page-actions button.is-primary,
.app-topbar-page-actions button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.app-topbar-btn.is-primary:hover,
.app-topbar-page-actions button.is-primary:hover,
.app-topbar-page-actions button.primary:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
  color: #fff;
}

.app-topbar-btn.is-icon {
  min-width: 32px;
  padding: 0;
  width: 32px;
}

.app-topbar-btn.is-labeled,
.app-topbar-menu summary.is-labeled,
.app-topbar-account-menu > summary {
  gap: 0.42rem;
  padding-inline: 0.52rem 0.68rem;
}

.app-topbar-btn__icon-wrap {
  align-items: center;
  background: color-mix(in srgb, var(--line) 12%, white);
  border-radius: 999px;
  display: inline-flex;
  flex-shrink: 0;
  height: 1.5rem;
  justify-content: center;
  width: 1.5rem;
}

.app-topbar-btn.is-primary .app-topbar-btn__icon-wrap {
  background: rgba(255, 255, 255, 0.18);
  border: 0;
}

.app-topbar-btn__glyph {
  block-size: 0.82rem;
  color: color-mix(in srgb, var(--text) 88%, var(--muted) 12%);
  display: inline-flex;
  inline-size: 0.82rem;
}

.app-topbar-btn.is-primary .app-topbar-btn__glyph {
  color: #fff;
}

.app-topbar-btn__label {
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.2;
}

.app-topbar-split-btn {
  display: inline-flex;
  position: relative;
}

.app-topbar-split-btn__main.app-topbar-btn.is-primary {
  border-bottom-right-radius: 0;
  border-right: 1px solid rgba(255, 255, 255, 0.22);
  border-top-right-radius: 0;
}

.app-topbar-split-btn__toggle {
  align-items: center;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-left: 0;
  border-radius: 0 6px 6px 0;
  color: #fff;
  cursor: pointer;
  display: inline-flex;
  justify-content: center;
  list-style: none;
  min-height: 32px;
  min-width: 28px;
  padding: 0 6px;
  transition:
    background-color 140ms ease,
    border-color 140ms ease;
}

.app-topbar-split-btn__toggle::-webkit-details-marker {
  display: none;
}

.app-topbar-split-btn__toggle .app-topbar-menu-caret {
  color: rgba(255, 255, 255, 0.92);
}

.app-topbar-split-btn:hover .app-topbar-split-btn__main.app-topbar-btn.is-primary:not(:disabled),
.app-topbar-split-btn:hover .app-topbar-split-btn__toggle,
.app-topbar-split-btn__menu[open] .app-topbar-split-btn__toggle {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.app-topbar-split-btn.is-menu-disabled .app-topbar-split-btn__toggle {
  cursor: not-allowed;
  opacity: 0.55;
}

.app-topbar-promote-menu-panel {
  min-width: 180px;
}

.app-topbar-account-trigger-label {
  max-width: 8.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.app-topbar-refresh-icon {
  display: inline-flex;
  height: 14px;
  width: 14px;
}

.app-topbar-refresh-icon svg {
  display: block;
  height: 100%;
  width: 100%;
}

.app-topbar-btn.is-busy .app-topbar-refresh-icon {
  animation: app-topbar-spin 0.9s linear infinite;
}

@keyframes app-topbar-spin {
  to {
    transform: rotate(360deg);
  }
}

.app-topbar-menu {
  position: relative;
}

.app-topbar-menu summary {
  list-style: none;
}

.app-topbar-menu summary::-webkit-details-marker {
  display: none;
}

.app-topbar-account-menu > summary {
  gap: 0.42rem;
  max-width: 12.5rem;
  min-width: unset;
  padding: 0 0.58rem 0 0.42rem;
}

.app-topbar-account-avatar {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 14%, white);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  color: var(--accent-strong);
  display: inline-flex;
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 700;
  height: 1.5rem;
  justify-content: center;
  letter-spacing: 0;
  line-height: 1;
  width: 1.5rem;
}

.app-topbar-account-menu .app-topbar-account-avatar.app-topbar-btn__icon-wrap {
  background: color-mix(in srgb, var(--accent) 14%, white);
}

.app-topbar-menu-caret {
  color: var(--muted);
  display: inline-flex;
  height: 11px;
  margin-left: 1px;
  transition: transform 140ms ease;
  width: 11px;
}

.app-topbar-menu-caret svg {
  display: block;
  height: 100%;
  width: 100%;
}

.app-topbar-menu[open] summary {
  background: #f4f8f6;
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
}

.app-topbar-menu[open] .app-topbar-menu-caret {
  color: var(--accent-strong);
  transform: rotate(180deg);
}

.app-topbar-menu-panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 10px;
  box-shadow: var(--shadow);
  display: grid;
