}

.async-skeleton.is-table .async-skeleton__item.is-table-row {
  align-items: center;
  border-radius: 12px;
  grid-template-columns: minmax(72px, 0.55fr) minmax(140px, 1.4fr) minmax(72px, 0.7fr) minmax(56px, 0.45fr);
