  }

  .async-skeleton.is-table .async-skeleton__item.is-table-row {
    grid-template-columns: 1fr 1.2fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-back-to-top,
  .async-button__spinner,
  .app-notice,
  .async-skeleton__block,
