  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
  color: var(--text);
  display: grid;
  gap: 12px;
  grid-template-columns: 1fr auto;
  padding: 14px;
  text-decoration: none;
}

.studio-card:hover {
  border-color: #9aa8b7;
}

.studio-card strong,
.studio-card small {
  display: block;
}

.studio-card small {
  color: var(--muted);
  line-height: 1.4;
  margin-top: 4px;
}

.studio-step-list {
  display: grid;
  gap: 10px;
}

.studio-step-list div {
  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px;
}

.studio-step-list span {
  color: var(--muted);
}

.ops-prompt-textarea {
  width: 100%;
  min-height: 280px;
  margin-top: 0.75rem;
  padding: 0.75rem 0.9rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9rem;
  line-height: 1.45;
  resize: vertical;
}

.ops-muted {
  color: var(--muted);
  font-size: 0.92rem;
  margin: 0.35rem 0;
}

.ops-form-grid {
  display: grid;
  gap: 0.85rem;
  margin-top: 0.75rem;
  max-width: 40rem;
}

.ops-form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.ops-form-field label {
  font-size: 0.88rem;
  font-weight: 600;
}

.ops-form-field input,
.ops-form-field select {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-size: 0.95rem;
}

.ops-form-field-inline {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ops-form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.ops-page--settings {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem var(--app-content-inset-x) 1.35rem;
  min-height: 0;
  box-sizing: border-box;
}

.ops-settings-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem;
  margin: 0 0 0.85rem;
  padding: 0.22rem;
  border: 1px solid color-mix(in srgb, var(--line) 92%, var(--accent));
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fa 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  width: fit-content;
  max-width: 100%;
}

.ops-settings-tab {
  display: inline-flex;
  align-items: center;
  padding: 0.42rem 0.9rem;
  border-radius: 9px;
  color: var(--muted);
  text-decoration: none;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition:
    color 0.12s ease,
    background 0.12s ease,
    box-shadow 0.12s ease;
}

.ops-settings-tab:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--panel-strong) 70%, transparent);
}

.ops-settings-tab.is-active {
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  box-shadow:
    0 1px 2px rgba(0, 95, 70, 0.08),
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent);
}

.ops-connection-status {
  display: inline-flex;
  align-items: center;
  max-width: min(28rem, 100%);
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 650;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ops-connection-status.is-ok {
  color: #166534;
  background: #dcfce7;
  border: 1px solid #86efac;
}

.ops-connection-status.is-fail {
  color: #991b1b;
  background: #fee2e2;
  border: 1px solid #fca5a5;
}

.ops-inline-banner {
  width: fit-content;
  max-width: 100%;
}

.ops-field-alert {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0 0 0.85rem;
  padding: 0.7rem 0.85rem 0.75rem;
  border-radius: 10px;
  font-size: 0.86rem;
  line-height: 1.4;
  max-width: min(42rem, 100%);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.ops-field-alert__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.45rem;
}

.ops-field-alert strong {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.ops-field-alert__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.08rem 0.42rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
  background: color-mix(in srgb, currentColor 8%, #fff);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.3;
}

.ops-field-alert__badge.is-muted {
  opacity: 0.85;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.ops-field-alert__message {
  color: inherit;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ops-field-alert-hint {
  color: inherit;
  opacity: 0.78;
  font-size: 0.78rem;
  line-height: 1.35;
}

.ops-field-alert.is-error {
  color: #991b1b;
  background: linear-gradient(180deg, #fff5f5 0%, #fef2f2 100%);
  border: 1px solid #fecaca;
  box-shadow:
    inset 3px 0 0 #ef4444,
    0 1px 2px rgba(153, 27, 27, 0.06);
}

.ops-field-alert.is-success {
  color: #166534;
  background: linear-gradient(180deg, #f3fdf6 0%, #f0fdf4 100%);
  border: 1px solid #bbf7d0;
  box-shadow:
    inset 3px 0 0 var(--good),
    0 1px 2px rgba(22, 101, 52, 0.06);
}

.ops-ai-page .ops-panel-body,
.ops-ai-page .ops-panel > div,
.ops-tts-page .ops-panel-body,
.ops-tts-page .ops-panel > div {
  max-width: none;
}

.ops-ai-status,
.ops-tts-status {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin: 0.15rem 0 0.75rem;
}

.ops-ai-chip,
.ops-tts-chip {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 0.28rem 0.7rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: #f8fafc;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 650;
  line-height: 1.3;
}

.ops-ai-chip.is-active,
.ops-tts-chip.is-active {
  color: #166534;
  background: #ecfdf5;
  border-color: #86efac;
}

.ops-ai-chip.is-ok,
.ops-tts-chip.is-ok {
  color: #1e3a8a;
  background: #eff6ff;
  border-color: #93c5fd;
}

.ops-ai-chip.is-muted,
.ops-tts-chip.is-muted {
  color: var(--muted);
}

.ops-ai-chip.is-warn,
.ops-tts-chip.is-warn {
  color: #9a3412;
  background: #fff7ed;
  border-color: #fdba74;
}

.ops-ai-lede,
.ops-tts-lede {
  margin: 0 0 0.85rem;
  max-width: 46rem;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.45;
}

.ops-tts-list-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: 0.65rem 0.85rem;
}

/* List view: tabs left + Active/New cluster right on one row */
.ops-tts-list-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-start;
  gap: 0.65rem 0.85rem;
  width: 100%;
  margin: 0 0 0.75rem;
}

.ops-tts-list-header .ops-settings-tabs {
  margin: 0;
  flex: 0 0 auto;
}

.ops-tts-list-header .ops-tts-list-toolbar {
  flex: 0 0 auto;
  margin: 0 0 0 auto;
  justify-content: flex-end;
}

.ops-tts-list-toolbar__cluster {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem 0.7rem;
  max-width: 100%;
  padding: 0.32rem 0.38rem 0.32rem 0.75rem;
  border: 1px solid color-mix(in srgb, var(--line) 85%, var(--accent));
  border-radius: 999px;
  background: linear-gradient(180deg, #ffffff 0%, #f7faf9 100%);
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.045),
    0 8px 18px rgba(0, 95, 70, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.ops-tts-list-toolbar__active {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-width: 0;
  max-width: 14rem;
  color: var(--text);
  font-size: 0.82rem;
  line-height: 1.2;
}

.ops-tts-list-toolbar__dot {
  flex: 0 0 auto;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--good);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--good) 18%, transparent);
}

.ops-tts-list-toolbar__active-label {
  flex: 0 0 auto;
  color: var(--muted);
  font-weight: 600;
}

.ops-tts-list-toolbar__active strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
  color: var(--accent-strong);
}

.ops-tts-list-toolbar__divider {
  width: 1px;
  height: 1.05rem;
  background: color-mix(in srgb, var(--line) 75%, transparent);
}

.ops-tts-list-toolbar__count {
  display: inline-flex;
  align-items: baseline;
  gap: 0.28rem;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
}

.ops-tts-list-toolbar__count strong {
  color: var(--text);
  font-size: 0.92rem;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
}

.ops-tts-list-toolbar__new {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  width: auto;
  min-height: 2.05rem;
  padding: 0.32rem 0.8rem 0.32rem 0.55rem !important;
  border-radius: 999px !important;
  border: 1px solid var(--accent-strong) !important;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--accent) 88%, #fff) 0%,
    var(--accent-strong) 100%
  ) !important;
  color: #fff !important;
  font-size: 0.84rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.01em;
  box-shadow:
    0 1px 2px rgba(0, 95, 70, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

.ops-tts-list-toolbar__new:hover:not(:disabled) {
  background: linear-gradient(180deg, var(--accent) 0%, #004836 100%) !important;
  border-color: #004836 !important;
}

.ops-tts-list-toolbar__new:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent) 45%, #fff);
  outline-offset: 2px;
}

.ops-tts-list-toolbar__new:disabled {
  opacity: 0.55;
  box-shadow: none;
}

.ops-tts-list-toolbar__plus {
  display: block;
  width: 1.05rem;
  height: 1.05rem;
}

.ops-tts-list-meta {
  color: var(--muted);
  font-size: 0.82rem;
}

.ops-tts-list-meta strong {
  color: var(--text);
  font-weight: 700;
}

.ops-tts-editor-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 0.55rem 0.7rem;
}

.ops-tts-editor-actions__cluster {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.28rem;
  border: 1px solid color-mix(in srgb, var(--line) 88%, #86efac);
  border-radius: 14px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.ops-tts-editor-actions__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  width: auto;
  min-height: 2.15rem;
  height: 2.15rem;
  padding: 0 0.7rem 0 0.55rem !important;
  margin: 0 !important;
  border-radius: 10px !important;
  border: 1px solid var(--line) !important;
  background: #fff !important;
  color: var(--text) !important;
  box-shadow: none !important;
  font: inherit;
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  white-space: nowrap;
  line-height: 1;
}

.ops-tts-editor-actions__btn:hover:not(:disabled) {
  background: #f8fafc !important;
  border-color: #cbd5e1 !important;
}

.ops-tts-editor-actions__btn.is-primary {
  border-color: #15803d !important;
  background: linear-gradient(180deg, #22c55e 0%, #166534 100%) !important;
  color: #fff !important;
  box-shadow:
    0 1px 2px rgba(22, 101, 52, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.22) !important;
}

.ops-tts-editor-actions__btn.is-primary:hover:not(:disabled) {
  background: linear-gradient(180deg, #16a34a 0%, #14532d 100%) !important;
  border-color: #14532d !important;
}

.ops-tts-editor-actions__btn:focus-visible {
  outline: 2px solid #86efac;
  outline-offset: 2px;
}

.ops-tts-editor-actions__btn:disabled {
  opacity: 0.55;
}

.ops-tts-editor-actions__btn.is-busy .ops-tts-editor-actions__icon {
  animation: app-topbar-spin 0.9s linear infinite;
}

.ops-tts-editor-actions__label {
  display: inline-block;
}

.ops-tts-editor-actions__icon {
  display: block;
  flex: 0 0 auto;
  width: 1.05rem;
  height: 1.05rem;
}

.ops-tts-test-banner {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin: 0.75rem 0 1rem;
  padding: 0.8rem 0.85rem 0.8rem 0.95rem;
  border-radius: 12px;
  width: 100%;
  max-width: none;
  box-sizing: border-box;
  font-size: 0.88rem;
  line-height: 1.45;
  border: 1px solid transparent;
  border-left-width: 3px;
}

.ops-tts-test-banner__chip {
  display: inline-flex;
  align-items: center;
  max-width: 16rem;
  padding: 0.12rem 0.45rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: inherit;
  opacity: 0.88;
  background: rgba(255, 255, 255, 0.75);
  border: 1px solid rgba(15, 23, 42, 0.08);
}

.ops-tts-test-banner.is-error {
  color: #7f1d1d;
  background: #fffafa;
  border-color: #fecaca;
  border-left-color: #dc2626;
}

.ops-tts-test-banner.is-ok {
  color: #14532d;
  background: #fbfefc;
  border-color: #bbf7d0;
  border-left-color: #16a34a;
}

.ops-tts-test-banner.is-busy {
  color: #1e3a5f;
  background: #f8fafc;
  border-color: #cbd5e1;
  border-left-color: #64748b;
}

.ops-tts-test-banner.is-busy .ops-tts-test-banner__icon {
  color: #475569;
  background: #e2e8f0;
}

.ops-tts-test-banner.is-busy .ops-tts-test-banner__icon svg {
  animation: app-topbar-spin 0.9s linear infinite;
}

.ops-tts-test-banner__icon {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 1.7rem;
  height: 1.7rem;
  margin-top: 0.05rem;
  border-radius: 999px;
}

.ops-tts-test-banner.is-error .ops-tts-test-banner__icon {
  color: #dc2626;
  background: #fee2e2;
}

.ops-tts-test-banner.is-ok .ops-tts-test-banner__icon {
  color: #15803d;
  background: #dcfce7;
}

.ops-tts-test-banner__icon svg {
  width: 1rem;
  height: 1rem;
}

.ops-tts-test-banner__body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}

.ops-tts-test-banner__title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.4rem 0.55rem;
}

.ops-tts-test-banner__title-row strong {
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
}

.ops-tts-test-banner__meta {
  display: inline-flex;
  align-items: center;
  padding: 0.08rem 0.45rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  line-height: 1.3;
  color: inherit;
  opacity: 0.82;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(15, 23, 42, 0.08);
}

.ops-tts-test-banner__message {
  color: inherit;
  opacity: 0.92;
}

.ops-tts-test-banner__hint {
  opacity: 0.78;
  font-size: 0.8rem;
}

.ops-tts-test-banner__dismiss {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 1.55rem;
  height: 1.55rem;
  margin: -0.05rem -0.1rem 0 0;
  padding: 0;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: inherit;
  opacity: 0.55;
  cursor: pointer;
}

.ops-tts-test-banner__dismiss:hover {
  opacity: 1;
  background: rgba(15, 23, 42, 0.05);
}

.ops-tts-test-banner__dismiss:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 1px;
}

.ops-tts-test-banner__dismiss svg {
  width: 0.95rem;
  height: 0.95rem;
}

.ops-tts-steps {
  margin: 0 0 0.85rem;
  padding: 0.65rem 0.85rem 0.65rem 1.6rem;
  max-width: 46rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #f8fafc;
  color: var(--text);
  font-size: 0.88rem;
  line-height: 1.45;
}

.ops-tts-preview-audio {
  flex: 1;
  min-width: 12rem;
  height: 2.35rem;
}

.ops-tts-section--preview {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--line));
  background: linear-gradient(180deg, color-mix(in srgb, var(--accent) 4%, #fff) 0%, #fff 55%);
}

.ops-tts-preview-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.ops-tts-preview-body {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.ops-tts-preview-field__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.35rem;
}

.ops-tts-preview-field__top label {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 650;
  color: var(--text);
}

.ops-tts-preview-count {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.ops-tts-preview-field textarea {
  width: 100%;
  resize: vertical;
  min-height: 3.25rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fff;
  color: var(--text);
  font: inherit;
  font-size: 0.92rem;
  line-height: 1.45;
}

.ops-tts-preview-field textarea:focus {
  outline: 2px solid color-mix(in srgb, var(--accent) 35%, transparent);
  outline-offset: 1px;
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
}

.ops-tts-preview-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
}

.ops-tts-preview-bar .primary {
  flex: 0 0 auto;
  min-width: 7.5rem;
}

.ops-tts-preview-idle {
  margin: 0;
  flex: 1;
  min-width: 10rem;
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.4;
}

.ops-tts-preview-feedback {
  align-items: center;
  background: color-mix(in srgb, var(--danger) 5%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--danger) 24%, var(--line));
  border-radius: 9px;
  color: var(--danger);
  display: grid;
  gap: 0.55rem;
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 0.55rem 0.62rem;
}

.ops-tts-preview-feedback__icon {
  align-items: center;
  display: inline-flex;
  height: 1.25rem;
  justify-content: center;
  width: 1.25rem;
