  background: #fff;
  width: fit-content;
  max-width: 100%;
}

.ops-tts-provider-name {
  max-width: none;
  width: 100%;
}

.ops-tts-provider-name input {
  width: 100%;
}

.ops-tts-provider-gate {
  align-items: center;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 6%, var(--panel)), var(--panel));
  border: 1px dashed color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 10px;
  display: flex;
  gap: 0.7rem;
  padding: 0.72rem 0.78rem;
}

.ops-tts-provider-gate__icon {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--line));
  border-radius: 9px;
  color: var(--accent);
  display: inline-flex;
  flex: 0 0 auto;
  height: 2.1rem;
  justify-content: center;
  width: 2.1rem;
}

.ops-tts-provider-gate__icon svg {
  height: 1.2rem;
  width: 1.2rem;
}

.ops-tts-provider-gate strong {
  font-size: 0.78rem;
}

.ops-tts-provider-gate p {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.4;
  margin: 0.18rem 0 0;
}

.ops-tts-kind-tab {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 0.88rem;
  font-weight: 650;
  padding: 0.45rem 0.85rem;
  border-radius: 8px;
}

.ops-tts-kind-tab:hover {
  color: var(--text);
  background: rgba(0, 0, 0, 0.03);
}

.ops-tts-kind-tab.is-active {
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 14%, #fff);
}

/* TTS editor: stacked sections (aligned with Translation AI chrome) */
.ops-tts-editor {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.ops-tts-section--preview .ops-tts-section__head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem 0.85rem;
}

.ops-tts-section__head--with-action {
  align-items: flex-start;
  display: flex;
  gap: 0.65rem 1rem;
  justify-content: space-between;
}

.ops-tts-section__head--with-action > div {
  min-width: 0;
}

.ops-tts-section--preview .ops-tts-preview-field textarea {
  min-height: 4.25rem;
  border-radius: 10px;
}

.ops-tts-section--preview .ops-tts-preview-bar .ops-tts-action-btn.is-primary {
  min-width: 0;
}

.ops-tts-status--compact {
  gap: 0.3rem;
  margin: 0 0 0.5rem;
}

.ops-tts-status--compact .ops-tts-chip,
.ops-tts-status--compact .ops-ai-chip {
  padding: 0.18rem 0.55rem;
  font-size: 0.72rem;
  border-radius: 7px;
}

.ops-tts-catalog-refresh {
  align-items: center;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--accent);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: 0.72rem;
  font-weight: 650;
  gap: 0.38rem;
  min-height: 34px;
  padding: 0.18rem 0.55rem;
}

.ops-tts-catalog-refresh svg {
  height: 0.95rem;
  width: 0.95rem;
}

.ops-tts-section__head--with-action .ops-tts-catalog-refresh {
  justify-content: center;
  min-width: 9.4rem;
}

.ops-tts-catalog-refresh.is-preparing svg {
  animation: ops-tts-catalog-pulse 0.65s ease-in-out infinite alternate;
}

.ops-tts-catalog-refresh.is-loading svg {
  animation: ops-tts-engine-spin 0.85s linear infinite;
}

@keyframes ops-tts-catalog-pulse {
  from {
    opacity: 0.45;
    transform: scale(0.88);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.ops-tts-catalog-refresh:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
}

.ops-tts-catalog-refresh:disabled {
  cursor: wait;
  opacity: 0.6;
}

.ops-tts-catalog-notice {
  align-items: flex-start;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.55rem;
  line-height: 1.35;
  margin: 0 0 0.65rem;
  padding: 0.45rem 0.6rem;
  font-size: 0.76rem;
}

.ops-tts-catalog-notice strong {
  color: var(--text);
  font-weight: 700;
}

.ops-tts-catalog-notice span {
  color: var(--muted);
  min-width: 0;
}

.ops-tts-catalog-notice.is-warn {
  background: color-mix(in srgb, #d97706 7%, var(--panel));
  border-color: color-mix(in srgb, #d97706 30%, var(--line));
}

.ops-tts-catalog-notice.is-muted {
  background: color-mix(in srgb, var(--muted) 4%, var(--panel));
}

.ops-tts-catalog-manual-input {
  margin-top: 0.38rem;
}

.ops-tts-catalog-detail {
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
  border-left: 2px solid color-mix(in srgb, var(--accent) 45%, var(--line));
  border-radius: 0 6px 6px 0;
  display: grid;
  gap: 0.18rem;
  margin-top: 0.45rem;
  padding: 0.38rem 0.55rem;
}

.ops-tts-catalog-detail strong {
  font-size: 0.77rem;
}

.ops-tts-catalog-detail span,
.ops-tts-catalog-detail small {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.35;
}

.ops-tts-engine-catalog {
  border-top: 1px solid var(--line);
  display: grid;
  gap: 0.75rem;
  margin-top: 0.9rem;
  padding-top: 0.9rem;
}

.ops-tts-engine-catalog__head {
  align-items: flex-start;
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  padding: 0 0.1rem;
}

.ops-tts-engine-catalog__head p {
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.45;
  margin: 0.2rem 0 0;
  max-width: 48rem;
}

.ops-tts-engine-catalog__meta,
.ops-tts-engine-card__meta {
  align-items: center;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.68rem;
  gap: 0.25rem 0.42rem;
}

.ops-tts-engine-catalog__meta {
  gap: 0.3rem;
  margin-top: 0.32rem;
}

.ops-tts-engine-catalog__meta > span {
  background: color-mix(in srgb, var(--panel) 86%, var(--line));
  border: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  border-radius: 999px;
  padding: 0.13rem 0.42rem;
}

.ops-tts-engine-catalog__meta strong {
  color: var(--text);
  font-size: 0.69rem;
}

.ops-tts-engine-tabs {
  align-items: center;
  background: color-mix(in srgb, var(--panel) 84%, var(--line));
  border: 1px solid var(--line);
  border-radius: 10px;
  display: flex;
  gap: 0.18rem;
  min-width: 0;
  overflow-x: auto;
  padding: 0.22rem;
}

.ops-tts-engine-tabs button {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  font: inherit;
  font-size: 0.69rem;
  font-weight: 680;
  gap: 0.38rem;
  min-height: 31px;
  padding: 0.28rem 0.52rem;
  white-space: nowrap;
}

.ops-tts-engine-tabs button:hover {
  color: var(--text);
}

.ops-tts-engine-tabs button.is-active {
  background: var(--panel);
  box-shadow: 0 2px 7px color-mix(in srgb, var(--text) 9%, transparent);
  color: var(--text);
}

.ops-tts-engine-tabs__indicator {
  background: color-mix(in srgb, var(--muted) 55%, transparent);
  border-radius: 999px;
  height: 0.38rem;
  width: 0.38rem;
}

.ops-tts-engine-tabs__indicator.is-ready,
.ops-tts-engine-tabs__indicator.is-installed {
  background: var(--good);
}

.ops-tts-engine-tabs__indicator.is-installable {
  background: var(--warning);
}

.ops-tts-engine-tabs__indicator.is-setup {
  background: var(--accent);
}

.ops-tts-engine-tabs button strong {
  align-items: center;
  background: color-mix(in srgb, var(--line) 62%, transparent);
  border-radius: 999px;
  display: inline-flex;
  font-size: 0.61rem;
  justify-content: center;
  min-width: 1.05rem;
  padding: 0.08rem 0.28rem;
}

.ops-tts-engine-tabs button.is-active strong {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent);
}

.ops-tts-engine-tabpanel {
  min-width: 0;
}

.ops-tts-engine-tabpanel__empty {
  border: 1px dashed var(--line);
  border-radius: 9px;
  color: var(--muted);
  font-size: 0.72rem;
  grid-column: 1 / -1;
  margin: 0;
  padding: 1.25rem;
  text-align: center;
}

.ops-tts-engine-catalog__meta > i,
.ops-tts-engine-card__meta > i {
  background: color-mix(in srgb, var(--muted) 45%, transparent);
  border-radius: 999px;
  height: 0.2rem;
  width: 0.2rem;
}

.ops-tts-engine-catalog__grid {
  align-items: start;
  display: grid;
  gap: 0.45rem;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ops-tts-engine-card {
  background: linear-gradient(135deg, color-mix(in srgb, var(--panel) 96%, white), var(--panel));
  border: 1px solid var(--line);
  border-radius: 9px;
  display: grid;
  gap: 0.45rem;
  min-width: 0;
  padding: 0.52rem 0.58rem;
  transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
}

.ops-tts-engine-card:hover {
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  box-shadow: 0 6px 16px color-mix(in srgb, var(--text) 7%, transparent);
  transform: translateY(-1px);
}

.ops-tts-engine-card.is-ready {
  background: linear-gradient(135deg, color-mix(in srgb, var(--good) 5%, var(--panel)), var(--panel) 62%);
  border-color: color-mix(in srgb, var(--good) 42%, var(--line));
}

.ops-tts-engine-card.is-installable {
  background: linear-gradient(135deg, color-mix(in srgb, var(--warning) 5%, var(--panel)), var(--panel) 62%);
  border-color: color-mix(in srgb, var(--warning) 42%, var(--line));
}

.ops-tts-engine-card.is-installed {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 3%, var(--panel)), var(--panel) 62%);
}

.ops-tts-engine-card__row {
  align-items: center;
  display: flex;
  gap: 0.48rem;
  min-height: 34px;
}

.ops-tts-engine-card__identity {
  display: grid;
  flex: 1 1 auto;
  gap: 0.13rem;
  min-width: 0;
}

.ops-tts-engine-card__identity-top {
  align-items: center;
  display: flex;
  gap: 0.45rem;
  min-width: 0;
}

.ops-tts-engine-card__identity-top strong {
  flex: 1 1 auto;
  font-size: 0.76rem;
  line-height: 1.2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-tts-engine-card__size {
  background: color-mix(in srgb, var(--panel) 74%, transparent);
  border: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
  border-radius: 999px;
  color: var(--muted);
  flex: 0 0 auto;
  font-size: 0.61rem;
  line-height: 1;
  padding: 0.16rem 0.34rem;
}

.ops-tts-engine-card__meta {
  flex-wrap: nowrap;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}

.ops-tts-engine-card__meta > span {
  flex: 0 0 auto;
}

.ops-tts-engine-card__meta > span.is-ready,
.ops-tts-engine-card__meta > span.is-installed {
  color: var(--good);
}

.ops-tts-engine-card__meta > span.is-installable {
  color: color-mix(in srgb, var(--warning) 78%, var(--text));
}

.ops-tts-engine-card__indicator {
  background: color-mix(in srgb, var(--muted) 55%, transparent);
  border-radius: 999px;
  flex: 0 0 auto;
  height: 0.46rem;
  width: 0.46rem;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--muted) 9%, transparent);
}

.ops-tts-engine-card__indicator.is-ready,
.ops-tts-engine-card__indicator.is-installed {
  background: var(--good);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--good) 12%, transparent);
}

.ops-tts-engine-card__indicator.is-installable {
  background: var(--warning);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--warning) 13%, transparent);
}

.ops-tts-engine-card__controls {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 0.35rem;
}

.ops-tts-engine-card__action {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
  font: inherit;
  font-size: 0.68rem;
  font-weight: 700;
  min-height: 27px;
  padding: 0.24rem 0.5rem;
}

.ops-tts-engine-card__action.is-icon {
  align-items: center;
  display: inline-flex;
  height: 29px;
  justify-content: center;
  min-height: 29px;
  padding: 0;
  width: 29px;
}

.ops-tts-engine-card__action.is-icon svg {
  height: 1rem;
  width: 1rem;
}

.ops-tts-engine-card__action.is-active {
  background: color-mix(in srgb, var(--accent) 9%, var(--panel));
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  color: var(--accent);
}

.ops-tts-engine-card__action.is-primary {
  background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 82%, black));
  border-color: var(--accent);
  box-shadow: 0 3px 8px color-mix(in srgb, var(--accent) 18%, transparent);
  color: white;
}

.ops-tts-engine-card__action:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  color: var(--accent);
}

.ops-tts-engine-card__action.is-primary:hover:not(:disabled) {
  color: white;
  filter: brightness(0.96);
}

.ops-tts-engine-card__action:disabled {
  cursor: wait;
  opacity: 0.65;
}

.ops-tts-engine-card__action .is-spinning {
  animation: ops-tts-engine-spin 0.85s linear infinite;
}

@keyframes ops-tts-engine-spin {
  to {
    transform: rotate(360deg);
  }
}

.ops-tts-engine-card__details-toggle {
  align-items: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 7px;
  color: var(--muted);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  height: 29px;
  justify-content: center;
  padding: 0;
  width: 29px;
}

.ops-tts-engine-card__details-toggle:hover {
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  border-color: color-mix(in srgb, var(--accent) 18%, var(--line));
  color: var(--accent);
}

.ops-tts-engine-card__details-toggle.is-active {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent);
}

.ops-tts-engine-card__details-toggle svg {
  height: 1rem;
  width: 1rem;
}

.ops-tts-engine-card__detail {
  background: color-mix(in srgb, var(--accent) 4%, var(--panel));
  border-left: 2px solid color-mix(in srgb, var(--accent) 36%, var(--line));
  border-radius: 0 6px 6px 0;
  color: var(--muted);
  font-size: 0.68rem;
  line-height: 1.35;
  margin: 0;
  overflow-wrap: anywhere;
  padding: 0.34rem 0.45rem;
}

.ops-tts-engine-card__progress {
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--accent) 24%, var(--line));
  border-radius: 8px;
  display: grid;
  gap: 0.35rem;
  padding: 0.48rem 0.55rem;
}

.ops-tts-engine-card__progress.is-error {
  background: color-mix(in srgb, var(--danger) 5%, var(--panel));
  border-color: color-mix(in srgb, var(--danger) 32%, var(--line));
}

.ops-tts-engine-card__progress-heading {
  align-items: center;
  display: flex;
  font-size: 0.72rem;
  gap: 0.5rem;
  justify-content: space-between;
}

.ops-tts-engine-card__progress progress {
  accent-color: var(--accent);
  height: 0.45rem;
  width: 100%;
}

.ops-tts-engine-card__progress p {
  color: var(--muted);
  font-size: 0.7rem;
  line-height: 1.4;
  margin: 0;
  overflow-wrap: anywhere;
}

.ops-tts-engine-card__progress.is-error p {
  color: var(--danger);
}

@media (max-width: 1200px) {
  .ops-tts-engine-catalog__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .ops-tts-engine-catalog__grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .ops-tts-engine-catalog__head {
    align-items: stretch;
    flex-direction: column;
