  .ops-tts-engine-catalog__head .ops-tts-catalog-refresh {
    justify-content: center;
  }

  .ops-tts-section__head--with-action {
    align-items: stretch;
    flex-direction: column;
  }

  .ops-tts-section__head--with-action .ops-tts-catalog-refresh {
    justify-content: center;
  }

  .ops-tts-engine-card__row {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .ops-tts-engine-card__controls {
    margin-left: 0.95rem;
  }
}

.ops-tts-kind-tabs--segmented {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.2rem;
  padding: 0.2rem;
}

.ops-tts-kind-tabs--segmented .ops-tts-kind-tab {
  text-align: center;
  padding: 0.5rem 0.35rem;
  font-size: 0.82rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

