  grid-template-columns: 1fr auto auto;
  gap: 0.35rem;
  align-items: stretch;
}

.ops-tts-install-command-bar input {
  padding: 0.45rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.84rem;
  min-width: 0;
}

.ops-tts-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  min-height: 2.15rem;
  height: 2.15rem;
  margin: 0;
  padding: 0 0.7rem 0 0.55rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  cursor: pointer;
  box-shadow: none;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  white-space: nowrap;
  line-height: 1;
}

.ops-tts-action-btn:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.ops-tts-action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ops-tts-action-btn.is-primary {
  border-color: color-mix(in srgb, var(--accent, #166534) 55%, var(--line));
  background: var(--accent, #166534);
