}

.ops-tts-editor.is-dense .ops-tts-section__head h3 {
  font-size: 0.84rem;
}

.ops-tts-editor.is-dense .ops-tts-section__head p {
  font-size: 0.76rem;
}

.ops-tts-editor.is-dense .ops-tts-grid {
