}

.ops-tts-editor.is-dense .ops-form-field label {
  font-size: 0.78rem;
  margin-bottom: 0.25rem;
}

.ops-tts-editor.is-dense .ops-form-field input,
.ops-tts-editor.is-dense .ops-form-field select,
.ops-tts-editor.is-dense .ops-form-field textarea {
  padding: 0.42rem 0.6rem;
  font-size: 0.84rem;
