/* Universal HTTP connector ------------------------------------------------ */
.ops-tts-http-connector {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  margin-top: 0.7rem;
  padding: 0.72rem;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--line));
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 3%, var(--panel));
}

.ops-tts-http-connector__intro,
.ops-tts-http-curl__actions {
  align-items: flex-start;
  display: flex;
  gap: 0.65rem;
  justify-content: space-between;
}

.ops-tts-http-connector__intro strong {
  color: var(--text);
  font-size: 0.82rem;
}

.ops-tts-http-connector__intro p,
.ops-tts-http-curl p {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.4;
  margin: 0.2rem 0 0;
}

.ops-tts-http-connector__version {
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.66rem;
  padding: 0.15rem 0.42rem;
}

.ops-tts-http-connector__steps {
  display: grid;
  gap: 0.42rem;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.ops-tts-http-step {
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  gap: 0.42rem;
  min-width: 0;
  padding: 0.42rem 0.5rem;
}

.ops-tts-http-step__number {
  align-items: center;
  background: color-mix(in srgb, var(--muted) 9%, var(--panel));
  border-radius: 50%;
  color: var(--muted);
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 0.67rem;
  font-weight: 750;
  height: 1.35rem;
  justify-content: center;
  width: 1.35rem;
}

.ops-tts-http-step__copy {
  display: grid;
  gap: 0.08rem;
  min-width: 0;
}

.ops-tts-http-step__copy strong {
  font-size: 0.7rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-tts-http-step__copy small {
  color: var(--muted);
  font-size: 0.65rem;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-tts-http-step.is-ok {
  background: color-mix(in srgb, #15803d 7%, var(--panel));
  border-color: color-mix(in srgb, #15803d 27%, var(--line));
}

.ops-tts-http-step.is-ok .ops-tts-http-step__number {
  background: #15803d;
  color: #fff;
}

.ops-tts-http-step.is-warn {
  background: color-mix(in srgb, #d97706 7%, var(--panel));
  border-color: color-mix(in srgb, #d97706 27%, var(--line));
}

.ops-tts-http-step.is-warn .ops-tts-http-step__number {
  background: #d97706;
  color: #fff;
}

.ops-tts-http-step.is-error {
  background: color-mix(in srgb, #b91c1c 7%, var(--panel));
  border-color: color-mix(in srgb, #b91c1c 27%, var(--line));
}

.ops-tts-http-step.is-error .ops-tts-http-step__number {
  background: #b91c1c;
  color: #fff;
}

.ops-tts-http-mode-tabs {
  align-self: flex-start;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  gap: 0.2rem;
  max-width: 100%;
  overflow-x: auto;
  padding: 0.18rem;
}

.ops-tts-http-mode-tabs button {
  background: transparent;
  border: 0;
  border-radius: 6px;
  color: var(--muted);
  cursor: pointer;
  font-size: 0.72rem;
  font-weight: 650;
  min-height: 30px;
  padding: 0.32rem 0.62rem;
  white-space: nowrap;
}

.ops-tts-http-mode-tabs button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
  color: var(--text);
}

.ops-tts-http-mode-tabs button.is-active {
  background: color-mix(in srgb, var(--accent) 14%, var(--panel));
  color: var(--text);
}

.ops-tts-http-mode-tabs button:disabled {
  cursor: wait;
  opacity: 0.55;
}

.ops-tts-http-connector__mode-hint {
  margin: -0.15rem 0 0;
}

.ops-tts-http-openapi {
  margin-top: 0.05rem;
}

.ops-tts-http-mapping,
.ops-tts-http-curl {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
}

.ops-tts-http-mapping > summary,
.ops-tts-http-curl > summary,
.ops-tts-http-endpoint__optional > summary {
  align-items: center;
  cursor: pointer;
  display: flex;
  gap: 0.45rem;
  list-style: none;
  min-height: 2.1rem;
  padding: 0.42rem 0.6rem;
}

.ops-tts-http-mapping > summary::-webkit-details-marker,
.ops-tts-http-curl > summary::-webkit-details-marker,
.ops-tts-http-endpoint__optional > summary::-webkit-details-marker {
  display: none;
}

.ops-tts-http-mapping > summary::before,
.ops-tts-http-curl > summary::before,
.ops-tts-http-endpoint__optional > summary::before {
  border-bottom: 1.5px solid currentColor;
  border-right: 1.5px solid currentColor;
  content: "";
  height: 0.38rem;
  transform: rotate(-45deg);
  transition: transform 0.15s ease;
  width: 0.38rem;
}

.ops-tts-http-mapping[open] > summary::before,
.ops-tts-http-curl[open] > summary::before,
.ops-tts-http-endpoint__optional[open] > summary::before {
  transform: rotate(45deg);
}

.ops-tts-http-mapping > summary span,
.ops-tts-http-curl > summary,
.ops-tts-http-endpoint__optional > summary {
  color: var(--text);
  font-size: 0.74rem;
  font-weight: 700;
}

.ops-tts-http-mapping > summary small {
  color: var(--muted);
  font-size: 0.67rem;
  font-weight: 450;
  margin-left: auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-tts-http-mapping__body {
  border-top: 1px solid var(--line);
  padding: 0.62rem;
}

.ops-tts-google-credential {
  display: grid;
  gap: 0.75rem;
}

.ops-tts-google-upload,
.ops-tts-google-info {
  align-items: center;
  background: color-mix(in srgb, var(--ops-surface, #fff) 92%, #2563eb 8%);
  border: 1px solid color-mix(in srgb, var(--ops-border, #d8dee8) 78%, #2563eb 22%);
  border-radius: 0.75rem;
  display: flex;
  gap: 0.8rem;
  justify-content: space-between;
  padding: 0.75rem 0.85rem;
}

.ops-tts-google-upload__status {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
}

.ops-tts-google-upload__status strong,
.ops-tts-google-info strong {
  color: var(--ops-text, #172033);
  font-size: 0.76rem;
}

.ops-tts-google-upload__status[data-ready="true"] strong {
  color: #167247;
}

.ops-tts-google-upload__status small,
.ops-tts-google-info p {
  color: var(--ops-muted, #667085);
  font-size: 0.67rem;
  line-height: 1.45;
  margin: 0;
  overflow-wrap: anywhere;
}

.ops-tts-google-upload__actions {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 0.45rem;
}

.ops-tts-google-upload__actions label {
  cursor: pointer;
}

.ops-tts-google-upload__input {
  height: 1px;
  opacity: 0;
  overflow: hidden;
  position: absolute;
  width: 1px;
}

@media (max-width: 720px) {
  .ops-tts-google-upload,
  .ops-tts-google-info {
    align-items: stretch;
    flex-direction: column;
  }

  .ops-tts-google-upload__actions {
    flex-wrap: wrap;
  }
}

.ops-tts-http-connector__intro-actions {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 0.45rem;
}

.ops-tts-http-mapping textarea {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  resize: vertical;
}

.ops-tts-http-endpoint {
  border: 1px solid var(--line);
  border-radius: 7px;
  margin: 0 0 0.5rem;
  min-width: 0;
  padding: 0.55rem;
}

.ops-tts-http-endpoint:last-child {
  margin-bottom: 0;
}

.ops-tts-http-endpoint legend {
  color: var(--text);
  font-size: 0.71rem;
  font-weight: 700;
  padding: 0 0.22rem;
}

.ops-tts-http-endpoint__optional {
  margin-top: 0.35rem;
}

.ops-tts-http-endpoint__optional > summary {
  color: var(--muted);
  font-size: 0.67rem;
  min-height: 1.7rem;
  padding: 0.2rem 0.1rem;
}

.ops-tts-http-endpoint__optional > div {
  padding-top: 0.35rem;
}

.ops-tts-http-polling {
  background: color-mix(in srgb, var(--accent) 4%, var(--panel));
  border: 1px dashed color-mix(in srgb, var(--accent) 25%, var(--line));
  border-radius: 7px;
  padding: 0.55rem;
}

.ops-tts-http-polling > strong {
  display: block;
  font-size: 0.73rem;
  margin-bottom: 0.45rem;
}

.ops-tts-http-curl {
  padding: 0.1rem 0.6rem 0.6rem;
}

.ops-tts-http-curl > summary {
  margin: 0 -0.6rem;
}

.ops-tts-http-curl textarea {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.72rem;
  margin-top: 0.45rem;
  min-height: 4rem;
  padding: 0.5rem 0.62rem;
  resize: vertical;
  width: 100%;
}

.ops-tts-http-curl__actions {
  align-items: center;
  justify-content: flex-start;
  margin-top: 0.45rem;
}

.ops-tts-http-curl__feedback {
  font-size: 0.7rem;
  line-height: 1.35;
}

.ops-tts-http-curl__feedback.is-ok {
  color: #15803d;
}

.ops-tts-http-curl__feedback.is-error,
.ops-tts-http-key-hint {
  color: #b45309;
}

@media (max-width: 720px) {
  .ops-tts-http-connector__steps {
    grid-template-columns: 1fr;
  }

  .ops-tts-http-mapping > summary small {
    display: none;
  }
}

.ops-tts-install-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
}

.ops-tts-install-row input {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.88rem;
}

.ops-tts-install-row button {
  white-space: nowrap;
}

.ops-tts-install-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.65rem;
}

.ops-tts-install-log {
  margin: 0.45rem 0 0;
  padding: 0.55rem 0.65rem;
  max-height: 12rem;
  overflow: auto;
  border-radius: 8px;
  background: #0b1220;
  color: #e2e8f0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.75rem;
  line-height: 1.4;
  white-space: pre-wrap;
}

@media (max-width: 720px) {
  .ops-ai-grid,
  .ops-tts-grid {
    grid-template-columns: 1fr;
  }

  .ops-ai-span-2,
  .ops-tts-span-2 {
    grid-column: auto;
  }

  .ops-tts-install-row {
    grid-template-columns: 1fr;
  }
}

.ops-form-grid {
  display: grid;
  gap: 0.85rem;
  margin-top: 0.75rem;
  max-width: 40rem;
}

.ops-form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.ops-form-field label {
  font-size: 0.88rem;
  font-weight: 600;
}

.ops-form-field input,
.ops-form-field select {
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-size: 0.95rem;
}

.ops-form-field-inline {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ops-form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1rem;
}

.ops-page--settings {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem var(--app-content-inset-x) 1.35rem;
  min-height: 0;
  box-sizing: border-box;
}

.ops-settings-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.2rem;
  margin: 0 0 0.85rem;
  padding: 0.22rem;
  border: 1px solid color-mix(in srgb, var(--line) 92%, var(--accent));
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff 0%, #f6f8fa 100%);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  width: fit-content;
  max-width: 100%;
}

.ops-settings-tab {
  display: inline-flex;
  align-items: center;
  padding: 0.42rem 0.9rem;
  border-radius: 9px;
  color: var(--muted);
  text-decoration: none;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition:
    color 0.12s ease,
    background 0.12s ease,
    box-shadow 0.12s ease;
}

.ops-settings-tab:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--panel-strong) 70%, transparent);
}

.ops-settings-tab.is-active {
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  box-shadow:
    0 1px 2px rgba(0, 95, 70, 0.08),
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent);
}

.ops-connection-status {
  display: inline-flex;
  align-items: center;
  max-width: min(28rem, 100%);
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 650;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ops-connection-status.is-ok {
  color: #166534;
  background: #dcfce7;
  border: 1px solid #86efac;
}

.ops-connection-status.is-fail {
  color: #991b1b;
  background: #fee2e2;
  border: 1px solid #fca5a5;
}

.ops-inline-banner {
  width: fit-content;
  max-width: 100%;
}

.ops-field-alert {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  margin: 0 0 0.85rem;
  padding: 0.7rem 0.85rem 0.75rem;
  border-radius: 10px;
  font-size: 0.86rem;
  line-height: 1.4;
  max-width: min(42rem, 100%);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}

.ops-field-alert__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.45rem;
}

.ops-field-alert strong {
  font-weight: 700;
  letter-spacing: -0.01em;
}

.ops-field-alert__badge {
  display: inline-flex;
  align-items: center;
  padding: 0.08rem 0.42rem;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
  background: color-mix(in srgb, currentColor 8%, #fff);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.3;
}

.ops-field-alert__badge.is-muted {
  opacity: 0.85;
  font-weight: 650;
  text-transform: none;
  letter-spacing: 0;
}

.ops-field-alert__message {
  color: inherit;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ops-field-alert-hint {
  color: inherit;
  opacity: 0.78;
  font-size: 0.78rem;
  line-height: 1.35;
}

.ops-field-alert.is-error {
  color: #991b1b;
  background: linear-gradient(180deg, #fff5f5 0%, #fef2f2 100%);
  border: 1px solid #fecaca;
  box-shadow:
    inset 3px 0 0 #ef4444,
    0 1px 2px rgba(153, 27, 27, 0.06);
}

.ops-field-alert.is-success {
  color: #166534;
  background: linear-gradient(180deg, #f3fdf6 0%, #f0fdf4 100%);
  border: 1px solid #bbf7d0;
  box-shadow:
    inset 3px 0 0 var(--good),
    0 1px 2px rgba(22, 101, 52, 0.06);
}

.ops-prompt-textarea {
  width: 100%;
  min-height: 280px;
  margin-top: 0.75rem;
  padding: 0.75rem 0.9rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.9rem;
  line-height: 1.45;
  resize: vertical;
}

.ops-muted {
  color: var(--muted);
  font-size: 0.92rem;
  margin: 0.35rem 0;
}

.ops-page {
  min-height: 100vh;
  padding-bottom: 36px;
}

/* Ops Home ? triage command center */
.ops-home-page {
