}

.ops-home-queue-mix__seg {
  min-width: 0.2rem;
}

.ops-home-queue-mix__seg.tone-muted {
  background: #94a3b8;
}

.ops-home-queue-mix__seg.tone-good {
  background: #34d399;
}

.ops-home-queue-mix__seg.tone-warn {
  background: #fbbf24;
}

.ops-home-queue-mix__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.75rem;
  font-size: 0.8rem;
  color: #4b5563;
}

.ops-home-queue-mix__legend span {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
}

.ops-home-queue-mix__legend i {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 999px;
  background: #94a3b8;
}

.ops-home-queue-mix__legend i.tone-good {
  background: #34d399;
}

.ops-home-queue-mix__legend i.tone-warn {
  background: #fbbf24;
}

.ops-home-queue-mix__legend strong {
  color: #111827;
  font-variant-numeric: tabular-nums;
}

.ops-home-week {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(2.4rem, 1fr));
  gap: 0.45rem;
  align-items: end;
  min-height: 8.5rem;
  padding: 0.35rem 0.15rem 0;
}

.ops-home-daybar {
  display: grid;
  grid-template-rows: 1fr auto auto;
  gap: 0.2rem;
  min-width: 0;
  height: 8.2rem;
  justify-items: center;
}

.ops-home-daybar__col {
  display: flex;
  flex-direction: column-reverse;
  width: 100%;
  max-width: 1.85rem;
  min-height: 0.5rem;
  margin-top: auto;
  border-radius: 6px 6px 3px 3px;
  overflow: hidden;
  background: color-mix(in srgb, #94a3b8 10%, #fff);
}

.ops-home-daybar__seg {
  display: block;
  min-height: 0;
  width: 100%;
}

.ops-home-daybar__seg.is-ok {
  background: #34d399;
}

.ops-home-daybar__seg.is-fail {
  background: #f87171;
}

.ops-home-daybar__seg.is-other {
  background: #93c5fd;
}

.ops-home-daybar__seg.is-empty {
  background: color-mix(in srgb, #94a3b8 18%, #fff);
}

.ops-home-daybar em {
  font-style: normal;
  font-size: 0.72rem;
  font-weight: 550;
  color: #6b7280;
  text-align: center;
  line-height: 1.15;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-home-daybar strong {
  font-size: 0.78rem;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  color: #111827;
  line-height: 1;
}

.ops-home-attention {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.3rem;
}

.ops-home-attention a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.5rem 0.6rem;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, #94a3b8 12%, transparent);
  background: color-mix(in srgb, #94a3b8 6%, #fff);
  text-decoration: none;
  color: inherit;
}

.ops-home-attention a:hover {
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, #fff);
}

.ops-home-attention strong {
  font-size: 1.05rem;
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  color: #111827;
}

.ops-home-attention span {
  font-size: 0.82rem;
  color: #4b5563;
  text-align: right;
}

.ops-home-fetch {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin: 0;
  padding-top: 0.35rem;
  border-top: 1px solid color-mix(in srgb, var(--line) 75%, transparent);
  font-size: 0.82rem;
  color: #4b5563;
}

.ops-home-fetch strong {
  color: #111827;
  font-variant-numeric: tabular-nums;
}

.ops-home-fetch a {
  font-weight: 650;
  color: var(--accent-strong);
  text-decoration: none;
}

.ops-home-fetch a:hover {
  text-decoration: underline;
}

@media (max-width: 1100px) {
  .ops-home-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .ops-home-main {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .ops-home-page {
    padding: 0.85rem 0.85rem 1.15rem;
  }

  .ops-home-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

