  justify-content: space-between;
  min-height: 116px;
  overflow: hidden;
  padding: 1.15rem 1.35rem;
  position: relative;
}

.ops-health-command.is-critical { --ops-command-tone: #dc2626; }
.ops-health-command.is-warning { --ops-command-tone: #d97706; }
