  padding: 0.38rem 0.55rem;
  border-radius: 8px;
  background: #fff;
  border: 1px solid color-mix(in srgb, #94a3b8 12%, transparent);
  border-left: 3px solid color-mix(in srgb, #94a3b8 45%, transparent);
  font-size: 0.78rem;
  color: #4b5563;
  transition: border-color 0.12s ease, background 0.12s ease;
}

.ops-pipeline-stage:hover {
  border-color: color-mix(in srgb, var(--accent) 20%, var(--line));
  background: color-mix(in srgb, #f8fafc 70%, #fff);
}

.ops-pipeline-stage.tone-good {
  border-left-color: color-mix(in srgb, #22c55e 75%, #166534);
}

.ops-pipeline-stage.tone-warn {
  border-left-color: color-mix(in srgb, #f59e0b 80%, #92400e);
}

.ops-pipeline-stage.tone-danger,
.ops-pipeline-stage.is-blocked {
  border-left-color: color-mix(in srgb, #ef4444 80%, #991b1b);
  background: color-mix(in srgb, #fca5a5 4%, #fff);
}

.ops-pipeline-stage.tone-muted {
  border-left-color: color-mix(in srgb, #94a3b8 55%, transparent);
}

.ops-pipeline-stage__identity {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
}

.ops-pipeline-stage__title {
  color: #111827;
  font-weight: 650;
  font-size: 0.84rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-pipeline-stage__primary,
.ops-pipeline-stage__secondary {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
}

.ops-pipeline-stage__primary .ops-pipeline-num,
.ops-pipeline-stage__secondary .ops-pipeline-num {
  flex: 0 0 auto;
  font-size: 0.78rem;
  font-weight: 650;
  min-width: 1.4rem;
  padding: 0.08rem 0.35rem;
}

.ops-pipeline-stage__primary em,
.ops-pipeline-stage__secondary em {
  font-style: normal;
  color: #6b7280;
  font-size: 0.7rem;
  font-weight: 500;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.ops-pipeline-stage.tone-warn .ops-pipeline-stage__primary .ops-pipeline-num {
  background: color-mix(in srgb, #fcd34d 22%, #fff);
  border-color: color-mix(in srgb, #f59e0b 28%, transparent);
  color: #92400e;
}

.ops-pipeline-stage.tone-danger .ops-pipeline-stage__primary .ops-pipeline-num,
.ops-pipeline-stage.is-blocked .ops-pipeline-stage__primary .ops-pipeline-num {
  background: color-mix(in srgb, #fca5a5 18%, #fff);
  border-color: color-mix(in srgb, #f87171 30%, transparent);
  color: #991b1b;
}

.ops-pipeline-stage.tone-good .ops-pipeline-stage__primary .ops-pipeline-num {
  background: color-mix(in srgb, #86efac 18%, #fff);
  border-color: color-mix(in srgb, #22c55e 28%, transparent);
  color: #166534;
}

.ops-pipeline-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  justify-self: start;
  min-height: 1.25rem;
  padding: 0.08rem 0.45rem;
  border-radius: 999px;
  font-size: 0.66rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  line-height: 1.2;
  white-space: nowrap;
  border: 1px solid transparent;
  box-shadow: none;
}

.ops-pipeline-chip.tone-good {
  background: color-mix(in srgb, #86efac 16%, #fff);
  color: #166534;
  border-color: color-mix(in srgb, #86efac 34%, transparent);
}

.ops-pipeline-chip.tone-warn {
  background: color-mix(in srgb, #fcd34d 22%, #fff);
  color: #92400e;
  border-color: color-mix(in srgb, #f59e0b 38%, transparent);
}

.ops-pipeline-chip.tone-danger {
  background: color-mix(in srgb, #fca5a5 18%, #fff);
  color: #991b1b;
  border-color: color-mix(in srgb, #f87171 36%, transparent);
}

.ops-pipeline-chip.tone-muted {
  background: color-mix(in srgb, #94a3b8 12%, #fff);
  color: #475569;
  border-color: color-mix(in srgb, #94a3b8 28%, transparent);
}

.ops-pipeline-open {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  justify-self: end;
  width: 1.65rem;
  height: 1.65rem;
  border-radius: 6px;
  border: 1px solid color-mix(in srgb, #94a3b8 16%, transparent);
  background: color-mix(in srgb, #94a3b8 6%, #fff);
  color: #475569;
  text-decoration: none;
  flex: 0 0 auto;
  transition: background 0.12s ease, color 0.12s ease, border-color 0.12s ease;
}

.ops-pipeline-open:hover {
  background: color-mix(in srgb, var(--accent-strong) 10%, #fff);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  color: var(--accent-strong);
}

.ops-pipeline-open-icon {
  width: 0.9rem;
  height: 0.9rem;
  display: block;
}

.ops-pipeline-activity {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0;
}

.ops-pipeline-activity__item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.45rem 0.65rem;
  min-width: 0;
  padding: 0.48rem 0.15rem;
  background: transparent;
  border: none;
  border-radius: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  transition: background 0.12s ease;
}

.ops-pipeline-activity__item:last-child {
  border-bottom: none;
  padding-bottom: 0.15rem;
}

.ops-pipeline-activity__item:first-child {
  padding-top: 0.1rem;
}

.ops-pipeline-activity__item:hover {
  background: color-mix(in srgb, #f8fafc 88%, #fff);
}

.ops-pipeline-activity__body {
  display: grid;
  gap: 0.06rem;
  min-width: 0;
}

.ops-pipeline-activity__body strong {
  color: #111827;
  font-weight: 650;
  font-size: 0.84rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-pipeline-activity__body span {
  font-size: 0.72rem;
  color: #6b7280;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-pipeline-activity__trail {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  flex: 0 0 auto;
}

.ops-pipeline-activity__trail time {
  font-size: 0.7rem;
  color: #6b7280;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 1100px) {
  .ops-pipeline-stage {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) 1.7rem;
  }

  .ops-pipeline-stage__secondary {
    display: none;
  }
}

@media (max-width: 900px) {
  .ops-pipeline-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-pipeline-next__item {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .ops-pipeline-next__stage {
    display: none;
  }
}

@media (max-width: 640px) {
  .ops-pipeline-page {
    padding: 0.85rem 0.85rem 1.15rem;
  }

  .ops-pipeline-kpis {
    grid-template-columns: 1fr;
  }

  .ops-pipeline-stage {
    grid-template-columns: minmax(0, 1fr) 1.7rem;
  }

  .ops-pipeline-stage__primary,
  .ops-pipeline-stage__secondary {
    display: none;
  }

  .ops-pipeline-activity__item {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .ops-pipeline-activity__trail time {
    display: none;
  }
}

/* Publishing indexes ? Export / Handoffs / Drafts triage */
/* Pipeline chart-first command view */
.ops-pipeline-page {
  gap: 0.9rem;
  color: #172033;
}

.ops-pipeline-overview-grid,
.ops-pipeline-bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(18rem, 0.8fr);
  gap: 0.8rem;
  align-items: stretch;
}

.ops-pipeline-bottom-grid {
  grid-template-columns: minmax(18rem, 0.85fr) minmax(0, 1.15fr);
}

.ops-pipeline-workload-map,
.ops-pipeline-output-qa,
.ops-pipeline-attention-chart {
  min-width: 0;
}

.ops-pipeline-panel {
  padding: 0.9rem 1rem;
  border-radius: 14px;
  background: color-mix(in srgb, #fff 97%, #eff6ff);
  box-shadow: 0 8px 24px color-mix(in srgb, #64748b 7%, transparent);
}

.ops-pipeline-panel__head {
  margin-bottom: 0.7rem;
  padding-bottom: 0.55rem;
}

.ops-pipeline-panel__head > div {
  display: grid;
  gap: 0.12rem;
}

.ops-pipeline-panel__head h2 {
  font-size: 1rem;
  font-weight: 700;
}

.ops-pipeline-panel__head p {
  margin: 0;
  color: #6b7280;
  font-size: 0.78rem;
  line-height: 1.4;
}

.ops-pipeline-workload {
  display: grid;
  gap: 0.6rem;
  min-width: 0;
}

.ops-pipeline-workload__rows {
  display: grid;
  gap: 0.28rem;
}

.ops-pipeline-workload__row {
  display: grid;
  grid-template-columns: minmax(9.6rem, 0.82fr) minmax(10rem, 2fr) 2.6rem 1.7rem;
  gap: 0.55rem;
  align-items: center;
  min-width: 0;
  min-height: 2.05rem;
  padding: 0.2rem 0.15rem;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 66%, transparent);
}

.ops-pipeline-workload__row:last-child {
  border-bottom: 0;
}

.ops-pipeline-workload__identity {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.35rem;
  min-width: 0;
}

.ops-pipeline-workload__identity > a,
.ops-pipeline-attention-row > a {
  min-width: 0;
  overflow: hidden;
  color: #172033;
  font-size: 0.82rem;
  font-weight: 650;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-pipeline-workload__identity > a:hover,
.ops-pipeline-attention-row > a:hover {
  color: var(--accent-strong);
}

.ops-pipeline-track {
  display: flex;
  align-items: stretch;
  width: 100%;
  height: 0.82rem;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, #cbd5e1 24%, #f8fafc);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #94a3b8 14%, transparent);
}

.ops-pipeline-segment,
.ops-pipeline-qa-segment {
  display: block;
  flex: 0 0 var(--segment-size);
  width: var(--segment-size);
  min-width: 2px;
}

.ops-pipeline-segment.is-waiting,
.ops-pipeline-legend__dot.is-waiting { background: #94a3b8; }
.ops-pipeline-segment.is-running,
.ops-pipeline-legend__dot.is-running { background: #60a5fa; }
.ops-pipeline-segment.is-review,
.ops-pipeline-legend__dot.is-review,
.ops-pipeline-segment.is-warning,
.ops-pipeline-legend__dot.is-warning,
.ops-pipeline-qa-segment.is-warned,
.ops-pipeline-legend__dot.is-warned { background: #fbbf24; }
.ops-pipeline-segment.is-failed,
.ops-pipeline-legend__dot.is-failed,
.ops-pipeline-segment.is-critical,
.ops-pipeline-legend__dot.is-critical,
.ops-pipeline-qa-segment.is-failed { background: #f87171; }
.ops-pipeline-segment.is-ready,
.ops-pipeline-legend__dot.is-ready,
.ops-pipeline-qa-segment.is-passed,
.ops-pipeline-legend__dot.is-passed { background: #4ade80; }
.ops-pipeline-qa-segment.is-ungraded,
.ops-pipeline-legend__dot.is-ungraded { background: #cbd5e1; }

.ops-pipeline-workload__total,
.ops-pipeline-attention-row > strong {
  justify-self: end;
  color: #172033;
  font-size: 0.82rem;
  font-variant-numeric: tabular-nums;
}

.ops-pipeline-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.35rem 0.75rem;
  color: #64748b;
  font-size: 0.72rem;
}

.ops-pipeline-legend > span,
.ops-pipeline-qa-list li {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
}

.ops-pipeline-legend__dot {
  width: 0.5rem;
  height: 0.5rem;
  flex: 0 0 auto;
  border-radius: 999px;
  background: #cbd5e1;
}

.ops-pipeline-qa-chart {
  display: grid;
  align-content: start;
  gap: 0.8rem;
  min-height: 100%;
}

.ops-pipeline-qa-chart__total {
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  padding: 0.55rem 0.65rem;
  border-radius: 10px;
  background: color-mix(in srgb, #dbeafe 38%, #fff);
}

.ops-pipeline-qa-chart__total strong {
  color: #172033;
  font-size: 1.85rem;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.ops-pipeline-qa-chart__total span {
  color: #64748b;
  font-size: 0.76rem;
}

.ops-pipeline-qa-bar {
  display: flex;
  align-items: stretch;
  min-height: 1.05rem;
  overflow: hidden;
  border-radius: 999px;
  background: #f1f5f9;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, #94a3b8 18%, transparent);
}

.ops-pipeline-chart-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  color: #64748b;
  font-size: 0.72rem;
}

.ops-pipeline-qa-list {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ops-pipeline-qa-list li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  color: #475569;
  font-size: 0.8rem;
}

.ops-pipeline-qa-list strong {
  color: #172033;
  font-variant-numeric: tabular-nums;
}

.ops-pipeline-attention-bars {
  display: grid;
  gap: 0.3rem;
}

.ops-pipeline-attention-row {
  display: grid;
  grid-template-columns: minmax(8rem, 0.65fr) minmax(12rem, 2.35fr) 2.6rem 1.7rem;
  align-items: center;
  gap: 0.6rem;
  min-height: 2rem;
  padding: 0.18rem 0.15rem;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 62%, transparent);
}

.ops-pipeline-attention-row:last-child { border-bottom: 0; }
.ops-pipeline-attention-row .ops-pipeline-track { height: 0.72rem; }
.ops-pipeline-bottom-grid .ops-pipeline-panel { min-height: 15rem; }
.ops-pipeline-next__list { align-content: start; }
.ops-pipeline-next__item { min-height: 3.1rem; }
.ops-pipeline-activity__item { min-height: 2.7rem; }

@media (max-width: 1080px) {
  .ops-pipeline-overview-grid,
  .ops-pipeline-bottom-grid { grid-template-columns: 1fr; }
  .ops-pipeline-bottom-grid .ops-pipeline-panel { min-height: 0; }
}

@media (max-width: 760px) {
  .ops-pipeline-workload__row,
  .ops-pipeline-attention-row {
    grid-template-columns: minmax(7.5rem, 0.9fr) minmax(7rem, 1.4fr) 2.2rem;
  }
  .ops-pipeline-workload__row > .ops-pipeline-open,
  .ops-pipeline-attention-row > .ops-pipeline-open,
  .ops-pipeline-workload__identity .ops-pipeline-chip { display: none; }
}

@media (max-width: 520px) {
  .ops-pipeline-workload__row,
  .ops-pipeline-attention-row {
    grid-template-columns: 7rem minmax(5rem, 1fr) 1.8rem;
    gap: 0.35rem;
  }
  .ops-pipeline-legend { justify-content: flex-start; }
}

/* Pipeline Operations Board ? flat matrix workspace, intentionally distinct from Home */
.ops-pipeline-operations {
  gap: 0.9rem;
}

.ops-pipeline-studio-grid {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(18rem, 0.72fr);
  gap: 0.85rem;
  align-items: start;
  min-width: 0;
}

.ops-pipeline-control-strip {
  --status-color: #64748b;
  position: relative;
  display: grid;
  grid-template-columns: minmax(20rem, 0.95fr) minmax(0, 1.35fr);
  align-items: center;
  gap: 0.8rem;
  min-width: 0;
  padding: 0.7rem 0.75rem 0.7rem 0.85rem;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 17px;
  background:
    radial-gradient(circle at 4% 0, color-mix(in srgb, var(--status-color) 10%, transparent), transparent 25rem),
    linear-gradient(120deg, color-mix(in srgb, var(--status-color) 2.5%, #fff), #fff 52%),
    #fff;
  box-shadow: 0 12px 32px color-mix(in srgb, #64748b 9%, transparent);
  animation: ops-pipeline-control-reveal 420ms cubic-bezier(0.2, 0.75, 0.25, 1) backwards;
}

.ops-pipeline-control-strip::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 5px;
  background: var(--status-color);
  content: "";
}

.ops-pipeline-control-strip::after {
  position: absolute;
  top: -3.8rem;
  left: 15%;
  width: 9rem;
  height: 9rem;
  border: 1px solid color-mix(in srgb, var(--status-color) 8%, transparent);
  border-radius: 50%;
  content: "";
  pointer-events: none;
}

.ops-pipeline-control-strip.is-blocked { --status-color: #ef4444; }
.ops-pipeline-control-strip.is-needs_attention { --status-color: #f59e0b; }
.ops-pipeline-control-strip.is-in_progress,
.ops-pipeline-control-strip.is-healthy { --status-color: #22c55e; }

.ops-pipeline-control-strip__status {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.72rem;
  min-width: 0;
  min-height: 4.1rem;
  padding: 0.5rem 0.6rem;
  border: 1px solid color-mix(in srgb, var(--status-color) 13%, var(--line));
  border-radius: 13px;
  background: color-mix(in srgb, var(--status-color) 4.5%, #fff);
  animation: ops-pipeline-control-item-reveal 380ms cubic-bezier(0.2, 0.75, 0.25, 1) 70ms backwards;
}

.ops-pipeline-control-strip__beacon {
  display: inline-grid;
  width: 3rem;
  height: 3rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--status-color) 24%, transparent);
  border-radius: 14px;
  background: linear-gradient(145deg, color-mix(in srgb, var(--status-color) 15%, #fff), color-mix(in srgb, var(--status-color) 7%, #fff));
  color: var(--status-color);
  box-shadow: inset 0 0 0 4px color-mix(in srgb, var(--status-color) 4%, transparent), 0 5px 14px color-mix(in srgb, var(--status-color) 10%, transparent);
}

.ops-pipeline-control-strip__beacon svg { width: 1.55rem; height: 1.55rem; }

.ops-pipeline-control-strip.is-blocked .ops-pipeline-control-strip__beacon,
.ops-pipeline-control-strip.is-needs_attention .ops-pipeline-control-strip__beacon {
  animation: ops-pipeline-beacon-pulse 2.8s ease-in-out infinite;
}

.ops-pipeline-control-strip__copy {
  display: grid;
  gap: 0.38rem;
  min-width: 0;
}

.ops-pipeline-control-strip__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem 0.6rem;
}

.ops-pipeline-control-strip__copy strong {
  color: #172033;
  font-size: 0.84rem;
  font-weight: 700;
  line-height: 1.35;
}

.ops-pipeline-control-strip__time {
  display: inline-flex;
  align-items: center;
  gap: 0.28rem;
  color: #64748b;
  font-size: 0.65rem;
  white-space: nowrap;
}

.ops-pipeline-control-strip__time svg { width: 0.8rem; height: 0.8rem; color: #94a3b8; }

.ops-pipeline-control-strip__status time {
  color: #334155;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.ops-pipeline-control-strip__metrics {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.52rem;
  margin: 0;
}

.ops-pipeline-control-strip__metrics > div {
  --metric-color: #64748b;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, auto);
  align-content: center;
  column-gap: 0.62rem;
  min-width: 0;
  min-height: 4.1rem;
  padding: 0.55rem 0.62rem;
  border: 1px solid color-mix(in srgb, var(--metric-color) 15%, var(--line));
  border-radius: 13px;
  background: linear-gradient(145deg, color-mix(in srgb, var(--metric-color) 6%, #fff), #fff 72%);
  box-shadow: 0 4px 12px color-mix(in srgb, var(--metric-color) 5%, transparent);
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
  animation: ops-pipeline-control-item-reveal 400ms cubic-bezier(0.2, 0.75, 0.25, 1) backwards;
}

.ops-pipeline-control-strip__metrics > div:nth-child(1) { animation-delay: 110ms; }
.ops-pipeline-control-strip__metrics > div:nth-child(2) { animation-delay: 165ms; }
.ops-pipeline-control-strip__metrics > div:nth-child(3) { animation-delay: 220ms; }

.ops-pipeline-control-strip__metrics > div:hover {
  border-color: color-mix(in srgb, var(--metric-color) 34%, var(--line));
  box-shadow: 0 9px 20px color-mix(in srgb, var(--metric-color) 11%, transparent);
  transform: translateY(-2px);
}

.ops-pipeline-control-strip__metrics .is-attention_items { --metric-color: #f97316; }
