  background: color-mix(in srgb, #94a3b8 7%, #fff);
  border: 1px solid color-mix(in srgb, #94a3b8 10%, transparent);
}

.ops-accounts-attention strong {
  display: block;
  font-size: 0.82rem;
  color: #111827;
}

.ops-accounts-attention em {
  display: block;
  margin-top: 0.15rem;
  font-style: normal;
  font-size: 0.74rem;
  color: #6b7280;
}

.ops-accounts-attention a {
  flex: 0 0 auto;
  font-size: 0.72rem;
  font-weight: 400;
  color: var(--accent-strong);
  text-decoration: none;
}

.ops-accounts-attention a:hover {
  text-decoration: underline;
}

.ops-accounts-top-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ops-accounts-top-actions > button.primary {
  min-height: 2rem;
  padding: 0.35rem 0.75rem;
  border-radius: 8px;
}

.ops-accounts-setup {
  display: grid;
  gap: 0.85rem;
  padding: 0.9rem;
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--line));
  border-radius: 14px;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 5%, #fff), #fff 42%);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.05);
}

.ops-accounts-setup__head,
.ops-accounts-setup-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.ops-accounts-setup__head span {
  display: block;
  margin-bottom: 0.18rem;
  color: var(--accent-strong);
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.ops-accounts-setup__head h2 {
  margin: 0;
  font-size: 1.15rem;
  color: #111827;
}

.ops-accounts-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.4rem;
}

.ops-accounts-steps span {
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: #6b7280;
  font-size: 0.75rem;
  font-weight: 600;
}

.ops-accounts-steps span.is-current {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--accent) 7%, #fff);
}

.ops-accounts-steps span.is-done {
  border-color: color-mix(in srgb, #22c55e 32%, var(--line));
  color: #166534;
  background: color-mix(in srgb, #86efac 13%, #fff);
}

.ops-accounts-tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.4rem;
}

.ops-accounts-tabs button {
  min-height: 2.25rem;
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  color: #6b7280;
  font-size: 0.75rem;
  font-weight: 650;
  text-align: left;
}

.ops-accounts-tabs button.is-current {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  color: var(--accent-strong);
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  box-shadow: inset 0 -2px 0 color-mix(in srgb, var(--accent) 75%, transparent);
}

.ops-accounts-tabs button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ops-accounts-oauth {
  display: grid;
  gap: 0.7rem;
  min-width: 0;
  padding: 0.8rem;
  border: 1px solid color-mix(in srgb, #1877f2 25%, var(--line));
  border-radius: 11px;
  background: color-mix(in srgb, #dbeafe 18%, #fff);
}

.ops-accounts-oauth.is-missing {
  border-color: color-mix(in srgb, #f59e0b 25%, var(--line));
  background: color-mix(in srgb, #fef3c7 17%, #fff);
}

.ops-accounts-oauth__head,
.ops-accounts-oauth__actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.ops-accounts-oauth__head > div {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.ops-accounts-oauth__head span {
  color: #1d4ed8;
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.ops-accounts-oauth__head b {
  color: #111827;
  font-size: 0.92rem;
}

.ops-accounts-oauth__head small,
.ops-accounts-oauth__actions small,
.ops-accounts-oauth-guide > small {
  color: #64748b;
  font-size: 0.7rem;
  line-height: 1.4;
}

.ops-accounts-oauth__actions {
  justify-content: flex-start;
}

.ops-accounts-meta-config {
  border: 1px solid color-mix(in srgb, #3b82f6 22%, var(--line));
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.82);
  overflow: hidden;
}

.ops-accounts-meta-config > summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  min-height: 3.2rem;
  padding: 0.65rem 0.75rem;
  cursor: pointer;
  list-style: none;
}

.ops-accounts-meta-config > summary::-webkit-details-marker {
  display: none;
}

.ops-accounts-meta-config > summary > span {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.ops-accounts-meta-config > summary b {
  color: #1f2937;
  font-size: 0.78rem;
}

.ops-accounts-meta-config > summary small,
.ops-accounts-meta-config__actions small {
  color: #64748b;
  font-size: 0.68rem;
  line-height: 1.4;
}

.ops-accounts-meta-config__body {
  display: grid;
  gap: 0.7rem;
  padding: 0.75rem;
  border-top: 1px solid color-mix(in srgb, var(--line) 76%, transparent);
  background: #fff;
}

.ops-accounts-meta-scopes {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
  margin: 0;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.ops-accounts-meta-scopes legend {
  padding: 0 0.25rem;
  color: #475569;
  font-size: 0.7rem;
  font-weight: 700;
}

.ops-accounts-meta-scopes label {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.45rem;
  border-radius: 999px;
  background: #f1f5f9;
  color: #334155;
  font-size: 0.68rem;
}

.ops-accounts-meta-config__actions {
  display: flex;
  align-items: center;
  gap: 0.65rem;
}

.ops-accounts-oauth-guide {
  display: grid;
  gap: 0.65rem;
}

.ops-accounts-oauth-guide ol {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  counter-reset: oauth-guide;
  list-style: none;
}

.ops-accounts-oauth-guide li {
  display: grid;
  grid-template-columns: 1.35rem minmax(0, 1fr);
  gap: 0.1rem 0.45rem;
  align-content: start;
  padding: 0.55rem;
  border: 1px solid color-mix(in srgb, var(--line) 82%, transparent);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
  counter-increment: oauth-guide;
}

.ops-accounts-oauth-guide li::before {
  display: grid;
  place-items: center;
  width: 1.25rem;
  height: 1.25rem;
  grid-row: 1 / span 2;
  border-radius: 50%;
  background: #dbeafe;
  color: #1d4ed8;
  content: counter(oauth-guide);
  font-size: 0.68rem;
  font-weight: 800;
}

.ops-accounts-oauth-guide li b {
  color: #1f2937;
  font-size: 0.73rem;
}

.ops-accounts-oauth-guide li span {
  min-width: 0;
  color: #64748b;
  font-size: 0.68rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.ops-accounts-oauth-missing {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
}

.ops-accounts-oauth-missing > span {
  color: #92400e;
  font-size: 0.7rem;
  font-weight: 700;
}

.ops-accounts-oauth-missing code,
.ops-accounts-oauth-guide code {
  padding: 0.1rem 0.35rem;
  border-radius: 5px;
  background: color-mix(in srgb, #f59e0b 10%, #fff);
  color: #7c2d12;
  font-size: 0.66rem;
  overflow-wrap: anywhere;
}

.ops-accounts-page-picker {
  display: grid;
  gap: 0.45rem;
}

.ops-accounts-page-picker > strong {
  color: #1f2937;
  font-size: 0.78rem;
}

.ops-accounts-page-picker > div {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: 0.45rem;
}

.ops-accounts-page-picker button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
  min-width: 0;
  padding: 0.55rem 0.65rem;
  text-align: left;
}

.ops-accounts-page-picker button.is-blocked {
  border-color: color-mix(in srgb, #f59e0b 35%, var(--line));
  background: color-mix(in srgb, #fef3c7 18%, #fff);
}

.ops-accounts-page-picker button span,
.ops-accounts-page-picker button b,
.ops-accounts-page-picker button small {
  display: block;
  min-width: 0;
}

.ops-accounts-page-picker button b {
  overflow: hidden;
  color: #1f2937;
  font-size: 0.74rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-accounts-page-picker button small,
.ops-accounts-page-picker button em {
  color: #64748b;
  font-size: 0.66rem;
  font-style: normal;
}

.ops-accounts-oauth__manual {
  margin: 0;
  padding-top: 0.5rem;
  border-top: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
  color: #64748b;
  font-size: 0.69rem;
}

.ops-accounts-setup-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
  align-items: start;
}

.ops-accounts-setup-card {
  display: grid;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.85rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.92);
}

.ops-accounts-setup-card__head {
  align-items: baseline;
  padding-bottom: 0.55rem;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
}

.ops-accounts-setup-card__head b {
  color: #111827;
  font-size: 0.92rem;
}

.ops-accounts-setup-card__head small {
  color: #6b7280;
  font-size: 0.72rem;
  text-align: right;
}

.ops-accounts-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.6rem;
}

.ops-accounts-form-grid label {
  display: grid;
  gap: 0.3rem;
  min-width: 0;
  color: #374151;
  font-size: 0.76rem;
  font-weight: 650;
}

.ops-accounts-form-grid label.is-wide {
  grid-column: 1 / -1;
}

.ops-accounts-form-grid input,
.ops-accounts-form-grid select,
.ops-accounts-form-grid textarea {
  min-width: 0;
  width: 100%;
  min-height: 2.2rem;
  border-radius: 8px;
}

.ops-accounts-form-grid textarea {
  min-height: 4.5rem;
  resize: vertical;
}

.ops-accounts-form-grid input[readonly],
.ops-accounts-form-grid input:disabled,
.ops-accounts-form-grid select:disabled,
.ops-accounts-form-grid textarea:disabled {
  color: #64748b;
  background: #f8fafc;
}

.ops-accounts-advanced {
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fbfdff;
}

.ops-accounts-advanced summary {
  color: #334155;
  font-size: 0.76rem;
  font-weight: 700;
  cursor: pointer;
}

.ops-accounts-advanced[open] summary {
  margin-bottom: 0.65rem;
}

.ops-accounts-safety-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem;
  border: 1px solid color-mix(in srgb, #ef4444 24%, var(--line));
  border-radius: 10px;
  background: color-mix(in srgb, #fee2e2 28%, #fff);
}

.ops-accounts-safety-banner.state-ready,
.ops-accounts-safety-banner.state-warm_up {
  border-color: color-mix(in srgb, #22c55e 28%, var(--line));
  background: color-mix(in srgb, #dcfce7 34%, #fff);
}

.ops-accounts-safety-banner.state-cooldown,
.ops-accounts-safety-banner.state-cadence_wait {
  border-color: color-mix(in srgb, #f59e0b 32%, var(--line));
  background: color-mix(in srgb, #fef3c7 35%, #fff);
}

.ops-accounts-safety-banner > div {
  display: grid;
  gap: 0.08rem;
}

.ops-accounts-safety-banner span,
.ops-accounts-safety-banner small {
  color: #64748b;
  font-size: 0.7rem;
}

.ops-accounts-safety-banner strong {
  color: #111827;
  font-size: 1rem;
}

.ops-accounts-safety-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.5rem;
}

.ops-accounts-safety-metrics div {
  display: grid;
  gap: 0.15rem;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.ops-accounts-safety-metrics span,
.ops-accounts-safety-details dt {
  color: #64748b;
  font-size: 0.68rem;
}

.ops-accounts-safety-metrics b,
.ops-accounts-safety-details dd {
  margin: 0;
  color: #1f2937;
  font-size: 0.76rem;
  overflow-wrap: anywhere;
}

.ops-accounts-safety-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.35rem 0.8rem;
  margin: 0;
}

.ops-accounts-safety-details div {
  display: grid;
  grid-template-columns: minmax(8rem, 0.65fr) minmax(0, 1fr);
  gap: 0.4rem;
  padding: 0.35rem 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
}

.ops-accounts-safety-messages {
  display: grid;
  gap: 0.3rem;
  margin: 0;
  padding: 0.6rem 0.75rem 0.6rem 1.75rem;
  border-radius: 8px;
  font-size: 0.72rem;
}

.ops-accounts-safety-messages.is-blocked {
  color: #991b1b;
  background: #fef2f2;
}

.ops-accounts-safety-messages.is-warning {
  color: #92400e;
  background: #fffbeb;
}

.ops-accounts-form-grid small {
  color: #6b7280;
  font-size: 0.68rem;
  font-weight: 400;
}

.ops-accounts-consent {
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.55rem 0.65rem;
  border: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
  border-radius: 9px;
  background: color-mix(in srgb, #94a3b8 6%, #fff);
  cursor: pointer;
}

.ops-accounts-consent input {
  margin-top: 0.18rem;
}

.ops-accounts-consent b,
.ops-accounts-consent small,
.ops-accounts-checks b,
.ops-accounts-checks small {
  display: block;
}

.ops-accounts-consent b {
  color: #1f2937;
  font-size: 0.76rem;
}

.ops-accounts-consent small {
  margin-top: 0.12rem;
  color: #6b7280;
  font-size: 0.69rem;
  line-height: 1.35;
}

.ops-accounts-setup-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.ops-accounts-checks {
  display: grid;
  gap: 0.5rem;
  padding: 0.65rem;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, #ef4444 22%, var(--line));
  background: color-mix(in srgb, #fecaca 10%, #fff);
}

.ops-accounts-checks.is-ready {
  border-color: color-mix(in srgb, #22c55e 26%, var(--line));
  background: color-mix(in srgb, #bbf7d0 12%, #fff);
}

.ops-accounts-checks > strong {
  color: #1f2937;
  font-size: 0.8rem;
}

.ops-accounts-checks section,
.ops-accounts-checks details {
  display: grid;
  gap: 0.35rem;
}

.ops-accounts-checks section > em,
.ops-accounts-checks summary {
  color: #475569;
  font-size: 0.69rem;
  font-style: normal;
  font-weight: 700;
  cursor: pointer;
}

.ops-accounts-checks ul {
  display: grid;
  gap: 0.3rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ops-accounts-checks li {
  display: flex;
  gap: 0.5rem;
  align-items: flex-start;
  padding: 0.35rem 0.45rem;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.72);
}

.ops-accounts-checks li > span {
  display: grid;
  place-items: center;
  width: 1.15rem;
  height: 1.15rem;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #fee2e2;
  color: #b42318;
  font-size: 0.7rem;
  font-weight: 800;
}

.ops-accounts-checks li.is-pass > span {
  background: #dcfce7;
  color: #166534;
}

.ops-accounts-checks li.is-warn > span {
  color: #92400e;
  background: #fef3c7;
}

.ops-accounts-checks b {
  color: #374151;
  font-size: 0.7rem;
  font-weight: 650;
}

.ops-accounts-checks small {
  margin-top: 0.08rem;
  color: #6b7280;
  font-size: 0.67rem;
  line-height: 1.3;
}

.ops-accounts-publication {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #fff;
}

.ops-accounts-publication a {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--accent-strong);
  font-size: 0.76rem;
}

.ops-accounts-live-gate {
  display: grid;
  gap: 0.55rem;
  padding: 0.65rem;
  border: 1px solid color-mix(in srgb, #f59e0b 28%, var(--line));
  border-radius: 10px;
  background: color-mix(in srgb, #fde68a 11%, #fff);
}

@media (max-width: 900px) {
  .ops-accounts-main.has-attention {
    grid-template-columns: 1fr;
  }

  .ops-accounts-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-accounts-setup-grid {
    grid-template-columns: 1fr;
  }

  .ops-accounts-oauth-guide ol {
    grid-template-columns: 1fr;
  }

  .ops-accounts-safety-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-accounts-safety-details {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .ops-accounts-page {
    padding: 0.85rem 0.85rem 1.15rem;
  }

  .ops-accounts-steps,
  .ops-accounts-tabs,
  .ops-accounts-form-grid {
    grid-template-columns: 1fr;
  }

  .ops-accounts-oauth__head,
  .ops-accounts-oauth__actions {
    align-items: flex-start;
    flex-direction: column;
  }

  .ops-accounts-form-grid label.is-wide {
    grid-column: auto;
  }

  .ops-accounts-sheet {
    display: none;
  }

  .ops-accounts-cards {
    display: grid;
    gap: 0.55rem;
  }

  .ops-accounts-cards li {
    display: grid;
    gap: 0.6rem;
    padding: 0.7rem;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: #fff;
  }

  .ops-accounts-cards li.is-hot {
    border-color: color-mix(in srgb, #f59e0b 35%, var(--line));
    background: color-mix(in srgb, #fef3c7 16%, #fff);
  }

  .ops-accounts-card__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.6rem;
  }

  .ops-accounts-card__head strong {
    color: #111827;
    font-size: 0.86rem;
  }

  .ops-accounts-cards dl {
    display: grid;
    gap: 0.3rem;
    margin: 0;
  }

  .ops-accounts-cards dl div {
    display: grid;
    grid-template-columns: 5.5rem minmax(0, 1fr);
    gap: 0.45rem;
  }

  .ops-accounts-cards dt,
  .ops-accounts-cards dd {
    margin: 0;
    color: #64748b;
    font-size: 0.72rem;
    overflow-wrap: anywhere;
  }

  .ops-accounts-cards dd {
    color: #334155;
  }

  .ops-accounts-safety-metrics {
    grid-template-columns: 1fr 1fr;
  }

  .ops-accounts-safety-banner {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* Ops Reconciliation ? uncertain publish attempts */
.ops-recon-page {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 1rem var(--app-content-inset-x) 1.35rem;
  min-height: 0;
}

.ops-recon-freshness {
  display: flex;
