  color: var(--accent-strong);
  text-decoration: none;
  white-space: nowrap;
}

.ops-risk-attention a:hover {
  text-decoration: underline;
}

@media (max-width: 1100px) {
  .ops-risk-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .ops-risk-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "title action"
      "target badges"
      "evidence evidence"
      "detected detected";
    gap: 0.45rem 0.75rem;
  }

  .ops-risk-row.is-head {
    display: none;
  }

  .ops-risk-row__title {
    grid-area: title;
  }

  .ops-risk-row__target {
    grid-area: target;
  }

  .ops-risk-row__badges {
    grid-area: badges;
    justify-self: end;
  }

  .ops-risk-row__evidence {
    grid-area: evidence;
  }

  .ops-risk-row time {
    grid-area: detected;
  }

  .ops-risk-row__link {
    grid-area: action;
  }
}

@media (max-width: 900px) {
  .ops-risk-main.has-attention {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .ops-risk-page {
    padding: 0.85rem 0.85rem 1.15rem;
  }

  .ops-risk-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.ops-users {
