  line-height: 1.1;
}

.ops-users-summary.is-compact .ops-users-summary-card {
  align-items: baseline;
  display: flex;
  gap: 10px;
  padding: 10px 14px;
}

.ops-users-summary.is-compact .ops-users-summary-card strong {
  font-size: 20px;
  margin-left: auto;
}

.ops-users-toolbar {
