  overflow: auto;
  padding: 18px;
  width: 100%;
}

.ops-users-modal-header h2 {
  font-size: 18px;
  margin: 0;
}

.ops-users-modal-header p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
  margin: 6px 0 0;
}

.ops-users-modal-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
  margin-top: 4px;
}

.ops-users-quiet-btn.is-danger {
  color: var(--danger);
  border-color: #f0b8b2;
}

.ops-users-quiet-btn.is-danger:hover:not(:disabled) {
  background: #fff3f1;
  border-color: #e39a92;
}

.visually-hidden {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

.ops-users-panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  display: grid;
  gap: 14px;
  padding: 16px;
}

.ops-users-panel-header h2 {
  font-size: 16px;
  font-weight: 650;
  margin: 0;
}

.ops-users-panel-header p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
  margin: 4px 0 0;
}

.ops-users-invite-form {
  display: grid;
  gap: 12px;
}

.ops-users-invite-form label,
.ops-users-field {
  color: var(--muted);
  display: grid;
  font-size: 12px;
  font-weight: 600;
  gap: 6px;
}

.ops-users-invite-form input,
.ops-users-invite-form select,
.ops-users-field select {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  min-height: 38px;
  padding: 0 10px;
}

.ops-users-invite-form input:focus,
.ops-users-invite-form select:focus,
.ops-users-field select:focus {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  outline: 2px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 1px;
}

.ops-users-invite-form .primary {
  justify-self: start;
  margin-top: 2px;
  min-height: 38px;
  padding: 0 14px;
}

.ops-users-invite-link {
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 10px;
  display: grid;
  gap: 8px;
  padding: 12px;
}

.ops-users-invite-link p {
  color: var(--muted);
  font-size: 12px;
  margin: 0;
}

.ops-users-invite-link code {
  color: var(--text);
  display: block;
  font-size: 12px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  word-break: break-all;
}

.ops-users-invite-link button,
.ops-users-quiet-btn {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  min-height: 34px;
  padding: 0 12px;
  width: fit-content;
}

.ops-users-quiet-btn:hover:not(:disabled),
.ops-users-invite-link button:hover:not(:disabled) {
  background: #f4f8f6;
  border-color: color-mix(in srgb, var(--accent) 35%, var(--line));
}

.ops-users-quiet-btn.is-accent {
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  border-color: color-mix(in srgb, var(--accent) 40%, var(--line));
  color: var(--accent-strong);
}

.ops-users-quiet-btn:disabled,
.ops-users-invite-link button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.ops-users-empty {
  background: #f7f9f8;
  border: 1px dashed var(--line);
  border-radius: 10px;
  display: grid;
  gap: 4px;
  padding: 18px 16px;
  text-align: left;
}

.ops-users-empty strong {
  font-size: 14px;
}

.ops-users-empty p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.45;
  margin: 0;
}

.ops-users-invite-list,
.ops-users-member-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  list-style: none;
  margin: 0;
  padding: 0;
}

.ops-users-invite-item {
  align-items: center;
  border-bottom: 1px solid color-mix(in srgb, var(--ops-users-soft, #e7eeea) 70%, #e2e8e5);
  display: flex;
  flex-wrap: wrap;
  gap: 12px 16px;
  justify-content: space-between;
  padding: 16px 18px;
  transition: background 0.15s ease;
}

.ops-users-invite-item:last-child {
  border-bottom: none;
}

.ops-users-invite-item:hover {
  background: color-mix(in srgb, var(--accent) 4%, #fff);
}

.ops-users-invite-meta {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ops-users-invite-meta strong {
  font-size: 14px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ops-users-invite-meta span {
  color: var(--muted);
  font-size: 12px;
}

.ops-users-invite-actions {
  align-items: center;
  display: flex;
  flex-shrink: 0;
  gap: 8px;
}

/* Legacy card-list member row retired ? directory uses .ops-users-person rows. */

.ops-users-member-identity {
  align-items: center;
  display: flex;
  gap: 12px;
  min-width: 0;
}

.ops-users-avatar {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 16%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  color: var(--accent-strong);
  display: inline-flex;
  flex-shrink: 0;
  font-size: 15px;
  font-weight: 700;
  height: 44px;
