}

.ops-users-sheet-page .ops-users-table th:nth-child(3),
.ops-users-sheet-page .ops-users-table td:nth-child(3) {
  width: 12%;
}

.ops-users-sheet-page .ops-users-table th:nth-child(4),
.ops-users-sheet-page .ops-users-table td:nth-child(4) {
  width: 16%;
}

.ops-users-sheet-page .ops-users-table th:nth-child(5),
.ops-users-sheet-page .ops-users-table td:nth-child(5) {
  width: 17%;
