  top: 0;
  z-index: 20;
}

.ops-page-header h1 {
  font-size: 24px;
  margin: 4px 0;
}

.ops-page-header p {
  color: var(--muted);
  margin: 0;
}

.ops-header-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.ops-header-actions a {
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  display: inline-flex;
  min-height: 36px;
  padding: 0 10px;
  text-decoration: none;
