  margin-bottom: 10px;
}

.ops-panel-heading__lead {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 0;
  flex: 1 1 auto;
}

.ops-panel-heading__meta {
  min-width: 0;
}

.ops-panel-heading h2 {
  margin: 0;
}

.ops-panel-heading .ops-header-actions {
  flex: 0 0 auto;
