}

.operator-home {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: 0.85rem var(--app-content-inset-x) 1.5rem;
  min-height: 0;
}

.operator-home-skeleton__hero {
  align-items: center;
  background: linear-gradient(165deg, #ffffff 0%, #f8fbfb 54%, #edf2f0 100%);
  border: 1px solid color-mix(in srgb, var(--line) 52%, transparent);
  border-radius: 16px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.96) inset,
    0 8px 18px rgba(15, 23, 42, 0.06);
  display: flex;
  gap: 0.85rem;
  padding: 0.9rem 1rem;
}

.operator-home-skeleton__glyph {
  align-items: center;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96) 0%, rgba(237, 242, 240, 0.94) 100%);
  border: 1px solid color-mix(in srgb, var(--line) 58%, transparent);
  border-radius: 14px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.95) inset;
  color: var(--accent);
  display: inline-flex;
  flex: 0 0 auto;
  height: 2.75rem;
  justify-content: center;
  width: 2.75rem;
}

.operator-home-skeleton__spinner {
  animation: async-button-spin 720ms linear infinite;
  border: 2px solid color-mix(in srgb, var(--line) 68%, #cbd5e1 32%);
  border-radius: 50%;
  border-top-color: var(--accent);
  display: block;
  height: 1rem;
  width: 1rem;
}

.operator-home-skeleton__copy {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.operator-home-skeleton__eyebrow {
  color: color-mix(in srgb, var(--muted) 82%, var(--text) 18%);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  line-height: 1.2;
  text-transform: uppercase;
}

.operator-home-skeleton__title {
  color: color-mix(in srgb, var(--text) 82%, var(--muted) 18%);
  font-size: 0.95rem;
  font-weight: 400;
  letter-spacing: -0.01em;
  line-height: 1.3;
  margin: 0;
}

.operator-home-skeleton__detail {
  color: color-mix(in srgb, var(--muted) 88%, var(--text) 12%);
  font-size: 0.8rem;
  font-weight: 400;
  line-height: 1.35;
  margin: 0;
}

.operator-home-skeleton__block {
  animation: async-skeleton-shimmer 1.25s ease-in-out infinite;
  background: linear-gradient(100deg, #edf1f5 20%, #f8fafc 40%, #edf1f5 60%);
  background-size: 240% 100%;
  border-radius: 999px;
  display: block;
}

.operator-home-skeleton__strip {
  align-items: center;
  background: color-mix(in srgb, #94a3b8 7%, #fff);
  border: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
  border-radius: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem 0.65rem;
  min-height: 2.35rem;
  padding: 0.45rem 0.7rem;
}

.operator-home-skeleton__strip .is-headline {
  flex: 1 1 12rem;
  height: 0.72rem;
  max-width: 18rem;
  min-width: 8rem;
}

.operator-home-skeleton__strip .is-pill {
  height: 1.35rem;
  margin-left: auto;
  width: 5.5rem;
}

.operator-home-skeleton__strip .is-pill.is-narrow {
  margin-left: 0;
  width: 4.2rem;
}

.operator-home-skeleton__kpis {
  display: grid;
  gap: 0.65rem;
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

.operator-home-skeleton__kpi {
  background: color-mix(in srgb, var(--panel, #fff) 92%, #f8fafc 8%);
  border: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-radius: 12px;
  display: grid;
  gap: 0.35rem;
  min-width: 0;
  padding: 0.7rem 0.75rem;
}

.operator-home-skeleton__kpi .is-label {
  height: 0.5rem;
  width: 48%;
}

.operator-home-skeleton__kpi .is-value {
  border-radius: 8px;
  height: 1.05rem;
  width: 42%;
}

.operator-home-skeleton__kpi .is-meta {
  height: 0.45rem;
  width: 72%;
}

.operator-home-skeleton__panel {
  background: color-mix(in srgb, var(--panel, #fff) 94%, #f8fafc 6%);
  border: 1px solid color-mix(in srgb, var(--line) 78%, transparent);
  border-radius: 14px;
  display: grid;
  gap: 0.7rem;
  padding: 0.85rem 0.9rem;
}

.operator-home-skeleton__panel-head {
  display: grid;
  gap: 0.28rem;
}

.operator-home-skeleton__panel-head .is-heading {
  border-radius: 8px;
  height: 0.78rem;
  width: 8.5rem;
}

.operator-home-skeleton__panel-head .is-subhead {
  height: 0.55rem;
  width: 14rem;
  max-width: 70%;
}

.operator-home-skeleton__rows {
  display: grid;
  gap: 0.55rem;
}

.operator-home-skeleton__rows .is-row {
  border-radius: 8px;
  height: 2rem;
  width: 100%;
}

.operator-home-skeleton__rows .is-row.is-short {
  width: 78%;
}

.operator-home-skeleton__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.operator-home-skeleton__chips .is-chip {
  border-radius: 999px;
  height: 1.7rem;
  width: 7.2rem;
}

.operator-home-skeleton__chips .is-chip.is-narrow {
  width: 5.4rem;
}

@media (max-width: 1100px) {
  .operator-home-skeleton__kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .operator-home-skeleton__kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .operator-home-skeleton__strip .is-pill {
    margin-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .operator-home-skeleton__spinner,
  .operator-home-skeleton__block {
    animation: none;
  }
}

