  padding: 18px var(--app-content-inset-x) 0;
}


.operator-metric-card,
.operator-panel,
.operator-action-row,
.operator-quick-card {
  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
}

.operator-metric-card {
  color: var(--text);
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 154px;
  padding: 14px;
  text-decoration: none;
}

.operator-metric-card div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.operator-metric-card span,
.operator-metric-card p,
.operator-panel-heading p,
.operator-action-row small,
.operator-quick-card small,
.operator-activity-list small {
  color: var(--muted);
}

.operator-metric-card strong {
  font-size: 30px;
}

.operator-metric-card p {
  line-height: 1.35;
  margin: 0;
}

.operator-panel {
  padding: 14px;
}


.operator-panel-heading {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  margin-bottom: 12px;
}

.operator-panel-heading h2 {
  font-size: 18px;
  margin: 0 0 4px;
}

.operator-panel-heading p {
  margin: 0;
}

.operator-action-list,
.operator-activity-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.operator-action-row {
  align-items: center;
  color: var(--text);
  display: grid;
  gap: 12px;
  grid-template-columns: auto 1fr auto;
  padding: 12px;
  text-decoration: none;
}

.operator-action-row.compact {
  grid-template-columns: auto 1fr auto;
}

.operator-action-count {
  align-items: center;
  background: #eef3f8;
  border-radius: 8px;
  display: inline-flex;
  font-size: 22px;
  font-weight: 700;
  justify-content: center;
  min-height: 48px;
  min-width: 56px;
}

.operator-next-action {
  color: var(--accent-strong) !important;
  font-weight: 700;
}

.operator-action-row strong,
.operator-action-row small,
.operator-quick-card strong,
.operator-quick-card small {
  display: block;
}

.operator-action-row small,
.operator-quick-card small {
  line-height: 1.35;
  margin-top: 3px;
}

.operator-quick-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(220px, 1fr));
}

.operator-quick-card {
  align-items: center;
  color: var(--text);
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr auto;
  padding: 12px;
  text-decoration: none;
}

.operator-quick-card.disabled {
  opacity: 0.72;
}

.operator-empty-state {
  border: 1px dashed var(--line);
  border-radius: 8px;
  padding: 18px;
  text-align: center;
}

.operator-empty-state h3 {
  margin: 0 0 6px;
}

.operator-empty-state p {
  color: var(--muted);
  margin: 0;
}

.operator-activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.operator-activity-list a {
  align-items: center;
  border-top: 1px solid var(--line);
  color: var(--text);
  display: grid;
  gap: 10px;
  grid-template-columns: 1fr auto;
  padding: 10px 0 0;
  text-decoration: none;
}

.operator-activity-list li:first-child a {
  border-top: 0;
  padding-top: 0;
}

.operator-activity-list strong,
.operator-activity-list small {
  display: block;
}

.operator-inline-link {
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--text);
  display: inline-flex;
  margin-top: 10px;
  min-height: 36px;
  padding: 0 10px;
  text-decoration: none;
}

.intake-layout {
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(620px, 1fr) 360px;
}

.intake-kicker {
  align-items: center;
  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(4, minmax(120px, 1fr));
  margin-bottom: 16px;
  padding: 10px;
}

.intake-kicker span {
  background: #f7f8fa;
  border: 1px solid var(--line);
  border-radius: 6px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
  padding: 9px 10px;
  text-align: center;
}

.intake-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.intake-section {
  border-bottom: 1px solid var(--line);
  padding-bottom: 16px;
}

.intake-section:last-of-type {
  border-bottom: 0;
  padding-bottom: 0;
}

.intake-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
}

.intake-profile-field input {
  min-height: 44px;
}

.intake-preset-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
}

.intake-preset-card {
  align-items: flex-start;
  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  height: auto;
  min-height: 92px;
  padding: 12px;
  text-align: left;
}

.intake-preset-card.active {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.intake-preset-card small,
.intake-preset-use {
  color: var(--muted);
  line-height: 1.35;
}

.intake-preset-use {
  margin: 10px 0 0;
}

.intake-filter-groups {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.intake-filter-group {
  background: #f7f8fa;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
}

.intake-filter-group h3 {
  font-size: 14px;
  margin: 0 0 10px;
}

.intake-filter-group p {
  color: var(--muted);
  line-height: 1.35;
  margin: -4px 0 10px;
}

.intake-checkbox-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(3, minmax(150px, 1fr));
  margin-top: 12px;
}

.intake-checkbox-field {
  align-items: flex-start;
  background: #ffffff;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: grid;
  gap: 8px;
  grid-template-columns: auto 1fr;
  padding: 10px;
}

.intake-checkbox-field input {
  margin-top: 3px;
}

.intake-checkbox-field strong,
.intake-checkbox-field small {
  display: block;
}

.intake-checkbox-field small {
  color: var(--muted);
  line-height: 1.35;
  margin-top: 3px;
}

.intake-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.intake-primary-action {
  min-width: 190px;
}

.intake-side {
  align-self: start;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: sticky;
  top: 18px;
}

.intake-status {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.intake-status h2 {
  margin: 0;
}

.intake-status-eyebrow {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.intake-status p {
  color: var(--muted);
  line-height: 1.45;
  margin: 0;
}

.intake-status.good {
  border-color: #a7d8bd;
}

.intake-status.warn {
  border-color: #eacb75;
}

.intake-status.danger {
  border-color: #f0b8b2;
}

.intake-status-cta {
  justify-content: center;
  margin-top: 0;
}

.intake-result-grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(2, minmax(120px, 1fr));
}

.intake-stat {
  background: #f7f8fa;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 10px;
}

.intake-stat span {
  color: var(--muted);
  font-size: 12px;
}

.intake-stat strong {
  overflow-wrap: anywhere;
}

.intake-flow {
  color: var(--muted);
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding-left: 20px;
}

.intake-recent {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.intake-recent-card {
  background: #f7f8fa;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
}

.intake-recent-card small {
  color: var(--muted);
  overflow-wrap: anywhere;
}

.inline-error.compact {
  margin: 0;
}

@media (max-width: 980px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .app-sidebar {
    height: auto;
    position: static;
  }

  .app-topbar {
    align-items: stretch;
    flex-direction: column;
    gap: 12px;
  }

  .app-topbar-command-bar {
    justify-content: flex-start;
    max-width: none;
    width: 100%;
  }

  .app-topbar-command-cluster {
    flex-wrap: wrap;
  }

  .operator-overview-grid,
  .operator-home-layout,
  .operator-home-kpis,
  .intake-layout,
  .intake-kicker {
    grid-template-columns: 1fr;
  }

  .operator-home-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .operator-home-side,
  .intake-side {
    position: static;
  }
}

@media (max-width: 640px) {
  .app-sidebar,
  .app-topbar,
  .page-shell,
  .ops-page-header,
  .ops-grid {
    padding-left: 12px;
    padding-right: 12px;
  }

  .page-shell-header,
  .studio-card {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .operator-overview-grid,
  .operator-home-layout {
    padding-left: 12px;
    padding-right: 12px;
  }

  .operator-home {
    padding-left: 0.85rem;
    padding-right: 0.85rem;
  }

  .operator-home-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .operator-home-actions__item {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .operator-home-actions__item .operator-home-chip {
    display: none;
  }

  .operator-home-next__item {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .operator-home-next__item .operator-home-num {
    display: none;
  }

  .operator-home-activity__trail time {
    display: none;
  }

  .operator-action-row,
  .operator-quick-card,
  .operator-activity-list a {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .operator-quick-grid {
    grid-template-columns: 1fr;
  }

  .intake-grid,
  .intake-checkbox-grid,
  .intake-preset-grid,
  .intake-result-grid {
    grid-template-columns: 1fr;
  }
}

.review-board {
  min-height: 100vh;
}

.board-header {
  background: #ffffff;
  border-bottom: 1px solid var(--line);
  padding: 18px var(--app-content-inset-x);
  position: sticky;
  top: 0;
  z-index: 10;
}

.board-header__top {
  align-items: center;
  display: flex;
  gap: 16px;
  justify-content: space-between;
}

.board-title {
  margin: 0;
  font-size: 24px;
}

.board-subtitle {
  color: var(--muted);
  margin: 4px 0 0;
}

.toolbar {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(6, minmax(120px, 1fr));
  margin-top: 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field label,
.field span {
  color: var(--muted);
  font-size: 12px;
}

.field input,
.field select {
  border: 1px solid var(--line);
  border-radius: 6px;
  min-height: 36px;
  padding: 0 10px;
  width: 100%;
}

.field small {
  color: var(--muted);
  line-height: 1.35;
}

.field-error {
  color: var(--danger) !important;
}

.field-warning {
  color: var(--warning) !important;
}

.intake-account-health-list {
  display: grid;
  gap: 4px;
  margin-top: 8px;
}

.intake-account-health-list small {
  color: var(--muted);
}

.block {
  display: block;
}

.board-body {
  padding: 20px var(--app-content-inset-x) 96px;
}

.summary-row {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  margin-bottom: 14px;
}

.summary-row p {
  color: var(--muted);
  margin: 0;
}

.candidate-grid {
  display: grid;
  gap: 16px;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
}

.candidate-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  min-height: 100%;
  overflow: hidden;
}

.candidate-card.selected {
  border-color: var(--accent);
}

.thumb-wrap {
  aspect-ratio: 16 / 9;
  background: var(--panel-strong);
  position: relative;
  width: 100%;
}

.thumb-wrap img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.thumb-fallback {
  align-items: center;
  color: var(--muted);
  display: flex;
  height: 100%;
  justify-content: center;
  padding: 18px;
  text-align: center;
}

.card-select {
  left: 10px;
  position: absolute;
  top: 10px;
}

.score-badge {
  align-items: center;
  background: #101828;
  border-radius: 6px;
  color: #fff;
  display: inline-flex;
  flex-direction: column;
  gap: 0;
  min-width: 68px;
  padding: 6px 8px;
  position: absolute;
  right: 10px;
  top: 10px;
}

.score-badge strong {
  font-size: 20px;
  line-height: 1;
}

.score-badge span {
  font-size: 11px;
  text-transform: uppercase;
}

.card-content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
}

.card-title {
  font-size: 16px;
  line-height: 1.3;
  margin: 0;
}

.card-meta,
.metrics-row,
.signal-row,
.reason-list {
  color: var(--muted);
  font-size: 13px;
}

.metrics-row,
.signal-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pill {
  background: #eef3f8;
  border-radius: 999px;
  color: #314154;
  display: inline-flex;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 8px;
}

.pill.good {
  background: #dcfae6;
  color: var(--good);
}

.pill.warn {
  background: #fff4d6;
  color: var(--warning);
}

.pill.danger {
  background: #fee4e2;
  color: var(--danger);
}

.advanced-panel summary {
  align-items: center;
  cursor: pointer;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  list-style-position: inside;
}

.advanced-panel summary span:first-of-type {
  display: grid;
  gap: 4px;
}

.advanced-panel summary small {
  color: var(--muted);
  font-size: 13px;
  font-weight: 400;
}

.advanced-panel > p {
  margin-top: 12px;
}

.card-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.selection-bar {
  align-items: center;
  background: #101828;
  border-radius: 8px;
  bottom: 18px;
  box-shadow: var(--shadow);
  color: #fff;
  display: flex;
  gap: 10px;
  left: 50%;
  padding: 12px;
  position: fixed;
  transform: translateX(-50%);
  z-index: 30;
}

.selection-bar button {
  background: #fff;
}

.drawer-backdrop {
  background: rgba(10, 20, 30, 0.32);
  inset: 0;
  position: fixed;
  z-index: 40;
}

.detail-drawer {
  background: #fff;
  bottom: 0;
  box-shadow: -10px 0 30px rgba(18, 30, 45, 0.18);
  overflow-y: auto;
  padding: 18px;
  position: fixed;
  right: 0;
  top: 0;
  width: min(620px, 100vw);
  z-index: 41;
}

.drawer-header {
  align-items: flex-start;
  display: flex;
  gap: 12px;
  justify-content: space-between;
}

.preview-box {
  aspect-ratio: 16 / 9;
  background: var(--panel-strong);
  border: 1px solid var(--line);
  border-radius: 8px;
  margin: 14px 0;
  overflow: hidden;
}

.preview-box iframe,
.preview-box img {
  border: 0;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.breakdown {
  display: grid;
  gap: 8px;
}

.breakdown-row {
  display: grid;
  gap: 8px;
  grid-template-columns: 160px 1fr 64px;
  align-items: center;
}

.bar {
  background: #edf2f7;
  border-radius: 999px;
  height: 8px;
  overflow: hidden;
}

.bar span {
  background: var(--accent);
  display: block;
  height: 100%;
}

.state-panel {
  align-items: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  justify-content: center;
  min-height: 320px;
  padding: 24px;
  text-align: center;
}

.state-panel.is-loading {
  gap: 0.85rem;
  min-height: 280px;
  padding: 1.5rem var(--app-content-inset-x);
}

.ops-page:has(> .state-panel.is-loading) {
  padding: 1rem var(--app-content-inset-x) 1.35rem;
}

.state-panel__boot {
  align-items: center;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  width: min(100%, 28rem);
}

.state-panel__skeleton {
  display: grid;
  gap: 0.45rem;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  width: 100%;
}

.state-panel__skeleton i {
  animation: pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #edf2f7, #f7f8fa, #edf2f7);
  border-radius: 10px;
  display: block;
  height: 3.4rem;
}

.state-panel__title {
  font-size: 1.05rem;
  font-weight: 700;
  margin: 0;
}

.state-panel p {
  color: var(--muted);
  line-height: 1.45;
  max-width: 680px;
}

.state-panel.is-loading p {
  margin: 0;
  max-width: 28rem;
}

.skeleton {
  animation: pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #edf2f7, #f7f8fa, #edf2f7);
  min-height: 360px;
}

@keyframes pulse {
  0% { opacity: 0.7; }
  50% { opacity: 1; }
  100% { opacity: 0.7; }
}

@media (max-width: 960px) {
  .toolbar {
    grid-template-columns: repeat(2, minmax(140px, 1fr));
  }
}

@media (max-width: 640px) {
  .board-header,
  .board-body {
    padding-left: 12px;
    padding-right: 12px;
  }

  .toolbar {
    grid-template-columns: 1fr;
  }

  .candidate-grid {
    grid-template-columns: 1fr;
  }
}

.transcript-editor {
  min-height: 100vh;
  padding-bottom: 96px;
}

.transcript-loading {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 12px var(--app-content-inset-x) 24px;
}

.transcript-loading__status {
  align-items: center;
  background: color-mix(in srgb, var(--panel, #fff) 88%, #edf2f0 12%);
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  border-radius: 999px;
  color: color-mix(in srgb, var(--muted) 78%, var(--text) 22%);
  display: inline-flex;
  font-size: 0.78rem;
  font-weight: 600;
  gap: 0.42rem;
  letter-spacing: 0.01em;
  line-height: 1.2;
  max-width: max-content;
  padding: 0.32rem 0.62rem 0.32rem 0.48rem;
}

.transcript-loading__spinner {
  animation: async-button-spin 720ms linear infinite;
  border: 1.5px solid color-mix(in srgb, var(--line) 72%, #cbd5e1 28%);
  border-radius: 50%;
  border-top-color: var(--accent);
  display: block;
  flex: 0 0 auto;
  height: 0.72rem;
  width: 0.72rem;
}

.transcript-loading__header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 14px;
  justify-content: space-between;
  min-width: 0;
}

.transcript-loading__pill,
.transcript-loading__step,
.transcript-loading__toolbar,
.transcript-loading__media,
.transcript-loading__beat,
.transcript-loading__line,
.transcript-loading__field {
  animation: async-skeleton-shimmer 1.25s ease-in-out infinite;
  background: linear-gradient(100deg, #edf1f5 20%, #f8fafc 40%, #edf1f5 60%);
  background-size: 240% 100%;
  display: block;
}

.transcript-loading__pill.is-back {
  border-radius: 999px;
  flex: 0 0 auto;
  height: 34px;
  width: 168px;
}

.transcript-loading__pipeline {
  align-items: center;
  background: #f4f8f7;
  border: 1px solid #d8e5e1;
  border-radius: 999px;
  display: inline-flex;
  gap: 6px;
  min-width: 0;
  padding: 4px 6px;
}

.transcript-loading__step {
  border-radius: 999px;
  height: 28px;
  width: 72px;
}

.transcript-loading__step.is-active {
  background: linear-gradient(100deg, #d7e8e1 20%, #eef7f3 40%, #d7e8e1 60%);
  background-size: 240% 100%;
  width: 84px;
}

.transcript-loading__toolbar {
  border-radius: 12px;
  flex: 1 1 220px;
  height: 42px;
  margin-left: auto;
  max-width: 420px;
  min-width: 180px;
}

.transcript-loading__bench {
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(280px, 400px) minmax(0, 1fr);
  min-width: 0;
}

.transcript-loading__side {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.transcript-loading__media {
  aspect-ratio: 9 / 16;
  border: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
  border-radius: 14px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset;
  max-height: 420px;
  width: 100%;
}

.transcript-loading__beats {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.transcript-loading__beat {
  border-radius: 10px;
  height: 44px;
}

.transcript-loading__focus {
  background: linear-gradient(165deg, #ffffff 0%, #f8fbfb 58%, #f1f5f4 100%);
  border: 1px solid color-mix(in srgb, var(--line) 58%, transparent);
  border-radius: 14px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset;
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 18px;
}

.transcript-loading__line {
  border-radius: 7px;
  height: 0.7rem;
}

.transcript-loading__line.is-narrow {
  width: 28%;
}

.transcript-loading__line.is-mid {
  width: 46%;
}

.transcript-loading__line.is-wide {
  width: 72%;
}

.transcript-loading__field {
  border-radius: 10px;
  height: 2.4rem;
  width: 100%;
}

.transcript-loading__field.is-tall {
  height: 5.5rem;
}

@media (max-width: 960px) {
  .transcript-loading__bench {
    grid-template-columns: 1fr;
  }

  .transcript-loading__media {
    aspect-ratio: 16 / 10;
    max-height: 260px;
  }
}

/* Dialogue Bench: video + beat rail | focus editor */
.transcript-bench {
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(360px, 440px) minmax(0, 1fr);
  padding: 16px var(--app-content-inset-x) 24px;
}

.transcript-bench.is-job-busy {
  opacity: 0.55;
  pointer-events: none;
  user-select: none;
}

.transcript-job-strip {
  background: color-mix(in srgb, var(--panel-strong) 40%, #fff);
  border-bottom: 1px solid var(--line);
  margin: 0;
  padding: 12px var(--app-content-inset-x) 14px;
}

.transcript-job-busy {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 12px;
  display: flex;
  gap: 12px;
  margin: 0;
  padding: 12px 14px;
}

.transcript-job-busy__icon {
  align-items: center;
  color: var(--accent-strong);
  display: inline-flex;
  flex: 0 0 auto;
  height: 1.35rem;
  justify-content: center;
  margin-top: 1px;
  width: 1.35rem;
}

.transcript-job-busy__icon svg {
  animation: transcript-job-busy-spin 0.9s linear infinite;
  height: 100%;
  width: 100%;
}

.transcript-job-busy__body {
  display: grid;
  flex: 1 1 auto;
  gap: 4px;
  min-width: 0;
}

.transcript-job-busy__title-row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.transcript-job-busy__title-row strong {
  color: var(--text);
  font-size: 0.92rem;
  font-weight: 700;
}

.transcript-job-busy__meta {
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  border-radius: 999px;
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.72rem;
  font-weight: 600;
  padding: 2px 8px;
}

.transcript-job-busy__percent {
  color: var(--accent-strong);
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
  font-weight: 750;
  min-width: 2.5rem;
}

.transcript-job-busy__hint {
  color: var(--muted);
  font-size: 0.8rem;
  line-height: 1.35;
}

.transcript-job-busy__progress {
  background: color-mix(in srgb, var(--accent) 14%, #e2e8f0);
  border-radius: 999px;
  height: 4px;
  margin-top: 6px;
  overflow: hidden;
  width: 100%;
}

.transcript-job-busy__progress-bar {
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--accent) 55%, #fff),
    var(--accent-strong),
    color-mix(in srgb, var(--accent) 55%, #fff)
  );
  border-radius: inherit;
  display: block;
  height: 100%;
}

.transcript-job-busy__progress.is-indeterminate .transcript-job-busy__progress-bar {
  animation: transcript-job-busy-indeterminate 1.2s ease-in-out infinite;
  width: 40%;
}

.transcript-job-busy__progress.is-determinate .transcript-job-busy__progress-bar {
  transition: width 0.25s ease;
  width: 0%;
}

.transcript-job-busy__cancel {
  align-items: center;
  align-self: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: #b42318;
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 0.78rem;
  font-weight: 700;
  gap: 6px;
  padding: 7px 12px;
}

.transcript-job-busy__cancel-icon {
  flex: 0 0 auto;
  height: 0.95rem;
  width: 0.95rem;
}

.transcript-job-busy__cancel:hover:not(:disabled) {
  background: color-mix(in srgb, #b42318 6%, #fff);
  border-color: color-mix(in srgb, #b42318 35%, var(--line));
}

.transcript-job-busy__cancel:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.transcript-inline-success {
  background: color-mix(in srgb, #12b76a 10%, #fff);
  border: 1px solid color-mix(in srgb, #12b76a 35%, var(--line));
  border-radius: 10px;
  color: #027a48;
  font-size: 0.88rem;
  font-weight: 650;
  margin: 10px 24px 0;
  padding: 10px 14px;
}

.transcript-inline-notice {
  align-items: flex-start;
  border-radius: 12px;
  display: flex;
  gap: 10px;
  margin: 12px var(--app-content-inset-x) 0;
  padding: 12px 14px;
}

.transcript-inline-notice__icon {
  align-items: center;
  display: inline-flex;
  flex: 0 0 auto;
  height: 1.2rem;
  justify-content: center;
  margin-top: 1px;
  width: 1.2rem;
}

.transcript-inline-notice__icon svg {
  height: 100%;
  width: 100%;
}

.transcript-inline-notice__message {
  flex: 1 1 auto;
  font-size: 0.88rem;
  font-weight: 650;
  line-height: 1.4;
  margin: 0;
}

.transcript-inline-notice.is-success {
  align-items: center;
  background: color-mix(in srgb, #12b76a 8%, #ecfdf3);
  border: 1px solid color-mix(in srgb, #12b76a 22%, var(--line));
  color: #067647;
  gap: 8px;
  padding: 7px 12px;
}

.transcript-inline-notice.is-success .transcript-inline-notice__message {
  font-size: 0.84rem;
  font-weight: 520;
  line-height: 1.3;
}

.transcript-inline-notice.is-success .transcript-inline-notice__icon {
  height: 1.05rem;
  margin-top: 0;
  width: 1.05rem;
}

.transcript-inline-notice.is-success .transcript-inline-notice__dismiss {
  align-self: center;
  height: 1.35rem;
  margin: 0 -0.05rem 0 0;
  width: 1.35rem;
}

.transcript-inline-notice.is-cancelled {
  align-items: center;
  background: color-mix(in srgb, #f79009 7%, #fffbeb);
  border: 1px solid color-mix(in srgb, #f79009 22%, var(--line));
  color: #9a6700;
  gap: 8px;
  padding: 7px 12px;
}

.transcript-inline-notice.is-cancelled .transcript-inline-notice__message {
  font-size: 0.84rem;
  font-weight: 520;
  line-height: 1.3;
}

.transcript-inline-notice.is-cancelled .transcript-inline-notice__icon {
  height: 1.05rem;
  margin-top: 0;
  width: 1.05rem;
}

.transcript-inline-notice.is-cancelled .transcript-inline-notice__dismiss {
  align-self: center;
  height: 1.35rem;
  margin: 0 -0.05rem 0 0;
  width: 1.35rem;
}

.transcript-inline-notice__dismiss {
  align-self: flex-start;
  background: transparent;
  border: none;
  border-radius: 8px;
  color: inherit;
  cursor: pointer;
  display: grid;
  flex: 0 0 auto;
  height: 1.55rem;
  margin: -0.05rem -0.1rem 0 0;
  opacity: 0.55;
  padding: 0;
  place-items: center;
  width: 1.55rem;
}

.transcript-inline-notice__dismiss:hover {
  background: rgba(15, 23, 42, 0.05);
  opacity: 1;
}

.transcript-inline-notice__dismiss:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 1px;
}

.transcript-inline-notice__dismiss svg {
  height: 0.95rem;
  width: 0.95rem;
}

.transcript-inline-notice.is-error {
  background: color-mix(in srgb, #f04438 8%, #fff);
  border: 1px solid color-mix(in srgb, #f04438 32%, var(--line));
  color: #b42318;
}

.transcript-source-review {
  align-items: center;
  background: color-mix(in srgb, #d97706 6%, #fffdf8);
  border: 1px solid color-mix(in srgb, #d97706 18%, #efe6d8);
  border-radius: 12px;
  color: #8a5a28;
  display: flex;
  gap: 10px;
  margin: 10px var(--app-content-inset-x) 0;
  padding: 10px 12px;
}

.transcript-source-review.is-compact {
  min-height: 0;
}

.transcript-source-review__icon {
  align-items: center;
  color: #b45309;
  display: inline-flex;
  flex: 0 0 auto;
  height: 1.05rem;
  justify-content: center;
  margin-top: 0;
  width: 1.05rem;
}

.transcript-source-review__icon svg {
  height: 100%;
  width: 100%;
}

.transcript-source-review__body {
  display: grid;
  flex: 1 1 auto;
  gap: 3px;
  min-width: 0;
}

.transcript-source-review__title-row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  min-width: 0;
}

.transcript-source-review__title {
  color: #92400e;
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1.25;
  margin: 0;
}

.transcript-source-review__chips {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
}

.transcript-source-review__chip {
  background: color-mix(in srgb, #d97706 10%, #fff);
  border: 1px solid color-mix(in srgb, #d97706 20%, #efe6d8);
  border-radius: 999px;
  color: #9a3412;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.02em;
  line-height: 1;
  padding: 3px 7px;
}

.transcript-source-review__copy {
  color: #a16207;
  font-size: 0.78rem;
  font-weight: 500;
  line-height: 1.35;
  margin: 0;
  max-width: 54rem;
}

.transcript-source-review__cta {
  align-items: center;
  background: #fff;
  border: 1px solid color-mix(in srgb, #d97706 28%, #e8d9c4);
  border-radius: 999px;
  color: #9a3412;
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 0.8rem;
  font-weight: 700;
  gap: 6px;
  margin-left: auto;
  min-height: 32px;
  padding: 0 12px 0 10px;
  white-space: nowrap;
}

.transcript-source-review__cta .async-button__icon,
.transcript-source-review__cta .async-button__icon svg {
  height: 0.95rem;
  width: 0.95rem;
}

.transcript-source-review__cta:hover:not(:disabled) {
  background: color-mix(in srgb, #d97706 8%, #fff);
  border-color: color-mix(in srgb, #d97706 40%, #e8d9c4);
}

.transcript-source-review__cta:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

@media (max-width: 820px) {
  .transcript-source-review {
    align-items: stretch;
    flex-wrap: wrap;
  }

  .transcript-source-review__cta {
    justify-content: center;
    margin-left: 0;
    width: 100%;
  }
}

@keyframes transcript-job-busy-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes transcript-job-busy-indeterminate {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(320%);
  }
}

.editor-command__save.is-busy .editor-command__icon,
.editor-command__translate.is-busy .editor-command__icon,
.editor-command__tts.is-busy .editor-command__icon,
.editor-command__rail button.is-busy .editor-command__icon {
  animation: transcript-job-busy-spin 0.9s linear infinite;
}

.transcript-bench__side {
  align-self: start;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
  padding: 14px;
  position: sticky;
  top: 72px;
  z-index: 1;
}

.transcript-bench__main {
  min-width: 0;
  position: relative;
  z-index: 2;
}

.transcript-bench__empty {
  color: var(--muted);
  padding: 32px 8px;
}

/* Frame video so intrinsic media size cannot blow out the Dialogue Bench grid. */
.media-box {
  align-items: center;
  aspect-ratio: 16 / 9;
  background: var(--panel-strong);
  border: 1px solid var(--line);
  border-radius: 10px;
  display: flex;
  justify-content: center;
  overflow: hidden;
  position: relative;
  width: 100%;
}

.media-box video {
  background: #0b1220;
  display: block;
  height: 100%;
  max-height: 100%;
  max-width: 100%;
  object-fit: contain;
  width: 100%;
}

.media-now {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  margin-top: 8px;
}

.media-now strong {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  width: 100%;
}

.media-now p {
  color: var(--muted);
  flex: 1;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  margin: 0;
}

.media-now button {
  font-size: 12px;
  min-height: 0;
  padding: 6px 10px;
}

.transcript-bench-media .media-box {
  aspect-ratio: 16 / 9;
  border-radius: 10px;
  min-height: 240px;
}

.transcript-bench-media .media-box video {
  background: #0b1220;
  object-fit: contain;
}

.transcript-bench-media__empty {
  color: var(--muted);
  font-size: 13px;
  padding: 24px;
  text-align: center;
}

.transcript-bench-media__tts {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 10px;
}

.transcript-bench-media__tts strong {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.transcript-bench-media__tts audio {
  width: 100%;
}

.transcript-bench-media__tts-status {
  color: var(--muted);
  font-size: 12px;
  margin: 0;
}

.transcript-beat-rail__label {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  margin: 0 0 6px;
  text-transform: uppercase;
}

.transcript-beat-rail__list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  list-style: none;
  margin: 0;
  max-height: min(42vh, 360px);
  overflow: auto;
  padding: 0;
}

.transcript-beat-rail__item {
  align-items: center;
  background: color-mix(in srgb, var(--panel-strong) 40%, #fff);
  border: 1px solid transparent;
  border-radius: 10px;
  color: var(--text);
  cursor: pointer;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 8px;
  padding: 9px 11px;
  text-align: left;
  width: 100%;
}

.transcript-beat-rail__item:hover {
  border-color: var(--line);
}

.transcript-beat-rail__item.is-selected {
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  box-shadow: inset 3px 0 0 var(--accent-strong);
}

.transcript-beat-rail__item.is-dirty .transcript-beat-rail__dirty {
  color: var(--accent-strong);
  font-size: 11px;
  font-weight: 700;
  margin-left: auto;
}

.transcript-beat-rail__tts-fit {
  font-size: 11px;
  margin-left: auto;
}

.transcript-tts-fit {
  border: 1px solid color-mix(in srgb, #f79009 32%, var(--line));
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 4px;
  padding: 10px 12px;
}

.transcript-tts-fit.is-warn {
  background: color-mix(in srgb, #f79009 10%, #fff);
  border-color: color-mix(in srgb, #f79009 36%, var(--line));
}

.transcript-tts-fit.is-danger {
  background: color-mix(in srgb, #f04438 9%, #fff);
  border-color: color-mix(in srgb, #f04438 34%, var(--line));
}

.transcript-tts-fit__title {
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 700;
  line-height: 1.35;
}

.transcript-tts-fit.is-warn .transcript-tts-fit__title {
  color: #b54708;
}

.transcript-tts-fit.is-danger .transcript-tts-fit__title {
  color: #b42318;
}

.transcript-tts-fit__hint {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
  margin: 0;
}

.segment-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.segment-warnings {
  color: #b54708;
  display: grid;
  font-size: 12px;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.transcript-beat-rail__title {
  font-size: 13px;
  font-weight: 700;
}

.transcript-beat-rail__range {
  color: var(--muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.transcript-beat-rail__preview {
  color: var(--muted);
  font-size: 12px;
  grid-column: 1 / -1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.transcript-focus-editor--dual {
  display: grid;
  gap: 14px;
}

.transcript-focus-editor {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px 20px 18px;
}

.transcript-focus-chrome {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.transcript-focus-chrome__head {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  justify-content: space-between;
}

.transcript-focus-chrome__title {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  font-size: 1.15rem;
  font-weight: 750;
  gap: 8px;
  letter-spacing: -0.02em;
  margin: 0;
}

.transcript-focus-chrome__range {
  color: var(--muted);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  margin: 0;
}

.transcript-focus-chrome__run {
  border-top: none;
  margin: 0;
  padding-top: 0;
}

.transcript-focus-secondary {
  border-top: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-top: 2px;
  padding-top: 6px;
}

.transcript-focus-secondary .transcript-focus-chrome__run,
.transcript-focus-secondary .compare-machine-details {
  border-top: none;
  margin-top: 0;
  padding-top: 0;
}

.transcript-focus-chrome__run > summary {
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  font-weight: 650;
  list-style: none;
  user-select: none;
  width: fit-content;
}

.transcript-focus-chrome__run > summary::-webkit-details-marker {
  display: none;
}

.transcript-focus-chrome__run > summary::before {
  color: #94a3b8;
  content: "? ";
  font-size: 10px;
}

.transcript-focus-chrome__run[open] > summary::before {
  content: "? ";
}

.transcript-focus-chrome__run > summary:hover {
  color: var(--accent-strong);
}

.transcript-focus-chrome__run-body {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px 0 2px;
}

.transcript-focus-editor__job-meta {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.transcript-focus-editor__job-id {
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

.transcript-focus-editor__title {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  font-size: 22px;
  font-weight: 750;
  gap: 10px;
  letter-spacing: -0.02em;
