}

.editor-command__pipeline {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  list-style: none;
  margin: 0;
  min-width: 0;
  padding: 0;
}

.editor-command__pipeline-step {
  align-items: center;
  color: #64748b;
  display: inline-flex;
  gap: 4px;
  min-width: 0;
}

.editor-command__pipeline-badge {
  align-items: center;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  display: inline-flex;
  gap: 8px;
  min-height: 32px;
  padding: 4px 12px 4px 6px;
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.editor-command__pipeline-connector {
  align-items: center;
  color: #cbd5e1;
  display: inline-flex;
  flex: 0 0 auto;
  justify-content: center;
  transition: color 180ms ease;
  width: 1rem;
}

.editor-command__pipeline-connector.is-reached {
  animation: editor-pipeline-connector-flow 1.6s ease-in-out infinite;
  color: color-mix(in srgb, var(--accent) 55%, #94a3b8 45%);
}

.editor-command__pipeline-connector-icon {
  display: block;
  height: 0.85rem;
  width: 0.85rem;
}

.editor-command__pipeline-step.is-done .editor-command__pipeline-badge {
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border-color: color-mix(in srgb, var(--accent) 28%, #e2e8f0);
  color: color-mix(in srgb, var(--accent-strong) 72%, #475569 28%);
}

.editor-command__pipeline-step.is-active .editor-command__pipeline-badge {
  animation: editor-pipeline-active-pulse 1.8s ease-in-out infinite;
  background: color-mix(in srgb, var(--accent) 14%, #fff);
  border-color: color-mix(in srgb, var(--accent) 48%, #e2e8f0);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
  color: color-mix(in srgb, var(--accent-strong) 94%, #0f172a 6%);
}

.editor-command__pipeline-step.is-pending .editor-command__pipeline-badge {
  background: #f8fafc;
  border-color: #e2e8f0;
  color: #94a3b8;
}

.editor-command__pipeline-index {
  align-items: center;
  background: #fff;
  border: 1px solid #d0d7e2;
  border-radius: 999px;
  color: #64748b;
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 10px;
  font-weight: 700;
  height: 1.35rem;
  justify-content: center;
  line-height: 1;
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
  width: 1.35rem;
}

.editor-command__pipeline-step.is-done .editor-command__pipeline-index {
  animation: editor-pipeline-done-pop 420ms ease-out both;
  background: color-mix(in srgb, var(--accent) 14%, #fff);
  border-color: color-mix(in srgb, var(--accent) 42%, #d0d7e2);
  color: var(--accent-strong);
}

.editor-command__pipeline-step.is-active .editor-command__pipeline-index {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
  color: #fff;
}

.editor-command__pipeline-step.is-pending .editor-command__pipeline-index {
  background: #fff;
  border-color: #d0d7e2;
  border-style: dashed;
  color: #94a3b8;
}

.editor-command__pipeline-label {
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.editor-command__pipeline-step.is-active .editor-command__pipeline-label {
  font-weight: 800;
}

.editor-command__pipeline-lock {
  display: block;
  flex: 0 0 auto;
  height: 0.7rem;
  width: 0.7rem;
}

@keyframes editor-pipeline-active-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
    transform: translateY(0);
  }
  50% {
    box-shadow: 0 0 0 6px color-mix(in srgb, var(--accent) 20%, transparent);
    transform: translateY(-1px);
  }
}

@keyframes editor-pipeline-connector-flow {
  0%,
  100% {
    opacity: 0.55;
    transform: translateX(0);
  }
  50% {
    opacity: 1;
    transform: translateX(2px);
  }
}

@keyframes editor-pipeline-done-pop {
  0% {
    opacity: 0.35;
    transform: scale(0.72);
  }
  70% {
    opacity: 1;
    transform: scale(1.08);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .editor-command__pipeline-badge,
  .editor-command__pipeline-index,
  .editor-command__pipeline-connector {
    animation: none !important;
    transition: none !important;
  }

  .editor-command__pipeline-step.is-active .editor-command__pipeline-badge {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
    transform: none;
  }
