.segment-flags {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.compare-machine-details {
  border-top: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  margin-top: 4px;
  padding-top: 4px;
  width: 100%;
}

.compare-machine-details > summary {
  align-items: baseline;
  color: var(--muted);
  cursor: pointer;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 8px;
  list-style: none;
  padding: 2px 0;
  user-select: none;
  width: 100%;
}

.compare-machine-details > summary::-webkit-details-marker {
  display: none;
}

.compare-machine-details > summary::before {
  color: #94a3b8;
  content: "?";
  flex: 0 0 auto;
  font-size: 10px;
  line-height: 1.4;
}

.compare-machine-details[open] > summary::before {
  content: "?";
}

.compare-machine-details > summary:hover {
  color: var(--accent-strong);
}

.compare-machine-details__title {
  font-size: 11px;
  font-weight: 650;
  line-height: 1.3;
}

.compare-machine-details__hint {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 500;
  line-height: 1.3;
}

.compare-machine-details__body {
  padding: 6px 0 2px;
  width: 100%;
}

.segment-flags--machine {
  align-items: stretch;
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.segment-flags__group {
  align-items: start;
  display: grid;
  gap: 4px 10px;
  grid-template-columns: 5.5rem minmax(0, 1fr);
}

.segment-flags__group-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 750;
  letter-spacing: 0.04em;
  line-height: 18px;
  text-transform: uppercase;
}

.segment-flags__group--attention .segment-flags__group-label {
  color: #b42318;
}

.segment-flags__group--pipeline .segment-flags__group-label {
  color: var(--accent-strong);
}

.segment-flags__chips {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  justify-content: flex-start;
  min-width: 0;
}

.segment-flags--machine .pill {
  border-radius: 6px;
  font-size: 11px;
  font-weight: 650;
  line-height: 1.2;
  padding: 2px 6px;
}

.segment-flags__chip--pipeline {
  background: #f4f7fa !important;
  border-color: color-mix(in srgb, var(--line) 75%, #c7d2de) !important;
  color: #3d4d5f !important;
  font-weight: 600;
}

@media (max-width: 640px) {
  .segment-flags__group {
    grid-template-columns: 1fr;
    gap: 3px;
  }

  .segment-flags__group-label {
    line-height: 1.2;
  }
}

.segment-flags__more {
  background: #eef3f8;
}

.segment-flags__pipeline {
  font-size: 12px;
}

.segment-flags__pipeline summary {
  color: var(--muted);
  cursor: pointer;
  font-weight: 600;
  list-style: none;
}

.segment-flags__pipeline summary::-webkit-details-marker {
  display: none;
}

.segment-flags__pipeline[open] summary {
  color: var(--accent-strong);
  margin-bottom: 6px;
}

.segment-flags__pipeline-list {
  margin-top: 4px;
}

.transcript-action-bar {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.transcript-reanalyze-status {
  color: var(--muted);
  font-size: 12px;
}

.final-review-loading {
  display: grid;
  gap: 14px;
  min-width: 0;
  padding: 16px var(--app-content-inset-x) 24px;
}

.final-review-loading__status {
  align-items: center;
  background: #f4f8f7;
  border: 1px solid #d8e5e1;
  border-radius: 999px;
  color: #3f6f5f;
  display: inline-flex;
  font-size: 0.78rem;
  font-weight: 600;
  gap: 0.42rem;
  letter-spacing: 0.01em;
  line-height: 1.2;
  max-width: max-content;
  padding: 0.32rem 0.62rem 0.32rem 0.48rem;
}

.final-review-loading__spinner {
  animation: async-button-spin 720ms linear infinite;
  border: 1.5px solid color-mix(in srgb, #d8e5e1 72%, #cbd5e1 28%);
  border-radius: 50%;
  border-top-color: #14614b;
  display: block;
  flex: 0 0 auto;
  height: 0.72rem;
  width: 0.72rem;
}

.final-review-loading__journey {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  min-width: 0;
}

.final-review-loading__step,
.final-review-loading__preview,
.final-review-loading__line,
.final-review-loading__field {
  animation: async-skeleton-shimmer 1.25s ease-in-out infinite;
  background: linear-gradient(100deg, #edf1f5 20%, #f8fafc 40%, #edf1f5 60%);
  background-size: 240% 100%;
  display: block;
}

.final-review-loading__step {
  border: 1px solid #d8e5e1;
  border-radius: 10px;
  height: 52px;
}

.final-review-loading__step.is-active {
  background: linear-gradient(100deg, #d7e8e1 20%, #eef7f3 40%, #d7e8e1 60%);
  background-size: 240% 100%;
  border-color: #bedbd1;
}

.final-review-loading__split {
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(0, 1.45fr) minmax(220px, 0.7fr);
  min-width: 0;
}

.final-review-loading__hero {
  background: #fff;
  border: 1px solid #dce5e9;
  border-radius: 14px;
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(160px, 0.75fr) minmax(0, 1.25fr);
  min-width: 0;
  padding: 12px;
}

.final-review-loading__preview {
  aspect-ratio: 9 / 16;
  border: 1px solid #d8e5e1;
  border-radius: 12px;
  max-height: 280px;
  width: 100%;
}

.final-review-loading__copy,
.final-review-loading__side {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.final-review-loading__side {
  background: #fff;
  border: 1px solid #dce5e9;
  border-radius: 14px;
  padding: 14px;
}

.final-review-loading__line {
  border-radius: 7px;
  height: 0.68rem;
}

.final-review-loading__line.is-narrow {
  width: 28%;
}

.final-review-loading__line.is-mid {
  width: 48%;
}

.final-review-loading__line.is-wide {
  width: 74%;
}

.final-review-loading__field {
  border-radius: 10px;
  height: 2.2rem;
  width: 100%;
}

.final-review-loading__field.is-tall {
  height: 4.8rem;
}

@media (max-width: 960px) {
  .final-review-loading__journey {
    grid-template-columns: 1fr;
  }

  .final-review-loading__split,
  .final-review-loading__hero {
    grid-template-columns: 1fr;
  }

  .final-review-loading__preview {
    aspect-ratio: 16 / 10;
    max-height: 220px;
  }
}

.final-review--prep {
  --fr-prep-radius: 14px;
  --fr-prep-radius-sm: 12px;
  --fr-prep-gap: 16px;
  --fr-prep-stage-gap: 18px;
  --fr-prep-shadow: 0 1px 2px rgba(15, 23, 42, 0.035), 0 6px 18px rgba(15, 23, 42, 0.04);
  --fr-prep-shadow-active: 0 1px 2px rgba(15, 23, 42, 0.04), 0 8px 20px rgba(15, 23, 42, 0.055);
  --fr-prep-border: 1px solid color-mix(in srgb, var(--line) 92%, #c5ced8);
  padding-bottom: 24px;
}

.final-review--prep .final-review-prep-briefing {
  margin: 0 0 var(--fr-prep-gap);
  padding: 16px var(--app-content-inset-x) 0;
}

.final-review-prep-briefing__shell {
  animation: final-review-prep-step-in 420ms cubic-bezier(0.22, 1, 0.36, 1) both;
  background: #fff;
  border: var(--fr-prep-border);
  border-radius: var(--fr-prep-radius);
  box-shadow: var(--fr-prep-shadow);
  display: grid;
  gap: 12px;
  padding: 14px 16px 12px;
}

.final-review-prep-briefing__lead {
  display: grid;
  gap: 8px;
  max-width: 52rem;
}

.final-review-prep-briefing__phase-badge {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 10%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  color: var(--accent-strong, var(--accent));
  display: inline-flex;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
  margin: 0;
  padding: 5px 10px;
  text-transform: uppercase;
  width: fit-content;
}

.final-review-prep-briefing__phase-badge.is-phase-render {
  background: color-mix(in srgb, #1f7a4c 8%, #fff);
  border-color: color-mix(in srgb, #1f7a4c 28%, var(--line));
  color: color-mix(in srgb, #1f7a4c 82%, var(--text));
}

.final-review-prep-briefing__goal {
  color: var(--text);
  font-size: 0.94rem;
  font-weight: 650;
  line-height: 1.45;
  margin: 0;
}

.final-review-prep-briefing__tiles {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}

.final-review-prep-briefing__tile {
  background: color-mix(in srgb, #f4f7fb 78%, #fff);
  border: 1px solid color-mix(in srgb, var(--line) 88%, #d5dde6);
  border-radius: 12px;
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 10px 12px;
}

.final-review-prep-briefing__tile-label {
  align-items: center;
  color: var(--muted);
  display: inline-flex;
  font-size: 0.7rem;
  font-weight: 700;
  gap: 6px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.final-review-prep-briefing__tile-value {
  color: var(--text);
  font-size: 0.86rem;
  font-weight: 650;
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.final-review-prep-briefing__tile.is-duration .final-review-prep-briefing__tile-value {
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.final-review-prep-briefing__status-dot {
  background: color-mix(in srgb, var(--muted) 55%, #fff);
  border-radius: 999px;
  display: inline-block;
  flex: 0 0 auto;
  height: 7px;
  width: 7px;
}

.final-review-prep-briefing__tile.is-ocr-idle .final-review-prep-briefing__status-dot,
.final-review-prep-briefing__tile.is-render-none .final-review-prep-briefing__status-dot {
  background: color-mix(in srgb, var(--muted) 50%, #fff);
}

.final-review-prep-briefing__tile.is-ocr-partial {
  background: color-mix(in srgb, #b7791f 7%, #fff);
  border-color: color-mix(in srgb, #b7791f 28%, var(--line));
}

.final-review-prep-briefing__tile.is-ocr-partial .final-review-prep-briefing__status-dot {
  background: #b7791f;
}

.final-review-prep-briefing__tile.is-ocr-running,
.final-review-prep-briefing__tile.is-render-running {
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line));
}

.final-review-prep-briefing__tile.is-ocr-running .final-review-prep-briefing__status-dot,
.final-review-prep-briefing__tile.is-render-running .final-review-prep-briefing__status-dot {
  animation: final-review-prep-status-pulse 1.2s ease-in-out infinite;
  background: var(--accent);
}

.final-review-prep-briefing__tile.is-ocr-ready {
  background: color-mix(in srgb, #1f7a4c 7%, #fff);
  border-color: color-mix(in srgb, #1f7a4c 28%, var(--line));
}

.final-review-prep-briefing__tile.is-ocr-ready .final-review-prep-briefing__status-dot {
  background: #1f7a4c;
}

.final-review-prep-briefing__hint {
  border-top: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
  color: var(--muted);
  font-size: 0.84rem;
  line-height: 1.4;
  margin: 0;
  padding-top: 10px;
}

.final-review-prep-briefing__activity {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 22%, var(--line));
  border-radius: 10px;
  color: var(--text);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.82rem;
  gap: 8px 12px;
  line-height: 1.4;
  margin: 0;
  padding: 10px 12px;
}

.final-review-prep-briefing__jobs {
  color: var(--accent-strong, var(--accent));
  font-weight: 650;
  text-decoration: none;
}

.final-review-prep-briefing__jobs:hover {
  text-decoration: underline;
}

@keyframes final-review-prep-status-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.55;
    transform: scale(0.85);
  }
}

@media (max-width: 960px) {
  .final-review-prep-briefing__tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .final-review-prep-briefing__tiles {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .final-review-prep-briefing__shell {
    animation: none;
  }

  .final-review-prep-briefing__tile.is-ocr-running .final-review-prep-briefing__status-dot,
  .final-review-prep-briefing__tile.is-render-running .final-review-prep-briefing__status-dot {
    animation: none;
  }
}

.final-review-readiness {
  display: grid;
  gap: 0;
  margin: 0;
  min-width: 0;
  padding: 0;
}

.final-review-readiness--rail {
  gap: 0;
}

.final-review-readiness--panel {
  background: #fff;
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 10px;
  overflow: hidden;
}

.final-review-readiness--flush {
  background: transparent;
  border: none;
  border-radius: 0;
  overflow: visible;
}

.final-review-readiness__head {
  align-items: center;
  background: color-mix(in srgb, #f4f7fa 72%, #fff);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 85%, transparent);
  display: flex;
  flex-wrap: nowrap;
  gap: 4px 8px;
  min-width: 0;
  padding: 6px 10px;
}

.final-review-readiness__title {
  color: var(--text);
  flex: 0 0 auto;
  font-size: 0.75rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1.35;
  margin: 0;
}

.final-review-readiness__title::after {
  color: color-mix(in srgb, var(--muted) 75%, transparent);
  content: "?";
  font-weight: 500;
  margin-left: 8px;
}

.final-review-readiness__status {
  color: var(--muted);
  flex: 1 1 auto;
  font-size: 0.74rem;
  line-height: 1.35;
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.final-review-readiness__status.is-ready {
  color: color-mix(in srgb, var(--good, #067647) 72%, var(--text));
  font-weight: 650;
}

.final-review-readiness__status.is-blocked .final-review-readiness__missing-prefix {
  color: var(--text);
  font-weight: 700;
}

.final-review-readiness.is-ready .final-review-readiness__title {
  color: color-mix(in srgb, var(--good, #067647) 55%, var(--text));
}

.final-review-readiness.is-blocked .final-review-readiness__title {
  color: var(--text);
}

.final-review-readiness__metrics {
  background: #fff;
  border: none;
  border-radius: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  overflow: hidden;
  padding: 0;
  width: 100%;
}

.final-review-readiness__metric {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: 7px 10px;
  position: relative;
}

.final-review-readiness__metric + .final-review-readiness__metric::before {
  background: color-mix(in srgb, var(--line) 82%, transparent);
  content: "";
  height: 48%;
  left: 0;
  position: absolute;
  top: 26%;
  width: 1px;
}

.final-review-readiness__metric-label {
  color: var(--muted);
  font-size: 0.6rem;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.final-review-readiness__metric-value {
  color: var(--text);
  font-size: 0.88rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.15;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.final-review-readiness__metric.is-good {
  background: color-mix(in srgb, var(--good, #067647) 6%, transparent);
}

.final-review-readiness__metric.is-good .final-review-readiness__metric-value {
  color: color-mix(in srgb, var(--good, #067647) 78%, var(--text));
}

.final-review-readiness__metric.is-warn {
  background: color-mix(in srgb, var(--warning, #8a5a00) 7%, transparent);
}

.final-review-readiness__metric.is-warn .final-review-readiness__metric-value {
  color: var(--text);
}

.final-review-readiness__metric.is-bad {
  background: color-mix(in srgb, var(--danger, #b42318) 6%, transparent);
}

.final-review-readiness__metric.is-bad .final-review-readiness__metric-value {
  color: color-mix(in srgb, var(--danger, #b42318) 72%, var(--text));
}

.final-review-readiness__metric.is-muted .final-review-readiness__metric-value {
  color: var(--muted);
}

/* Legacy pill chips (unused by rail) keep tokens for any residual markup */
.final-review-readiness__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
  width: 100%;
}

.final-review-readiness__chip {
  align-items: center;
  background: color-mix(in srgb, #f3f6f9 70%, #fff);
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 999px;
  display: inline-flex;
  gap: 5px;
  min-height: 26px;
  padding: 3px 9px;
}

.final-review-readiness__chip-label {
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.final-review-readiness__chip strong {
  color: var(--text);
  font-size: 0.78rem;
  font-weight: 650;
}

.final-review-readiness__chip.is-good {
  border-color: color-mix(in srgb, #1f7a4c 24%, var(--line));
  background: color-mix(in srgb, #1f7a4c 7%, #fff);
}

.final-review-readiness__chip.is-warn {
  border-color: color-mix(in srgb, #b7791f 26%, var(--line));
  background: color-mix(in srgb, #b7791f 8%, #fff);
}

.final-review-readiness__chip.is-bad {
  border-color: color-mix(in srgb, #b42318 24%, var(--line));
  background: color-mix(in srgb, #b42318 7%, #fff);
}

@media (max-width: 900px) {
  .final-review-readiness__metrics {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .final-review-readiness__metric:nth-child(3n + 1)::before {
    content: none;
  }
}

@media (max-width: 720px) {
  .final-review-readiness__title::after {
    display: none;
  }

  .final-review-readiness__metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .final-review-readiness__metric:nth-child(2n + 1)::before {
    content: none;
  }
}

.final-review-compare-diff {
  display: flex;
  flex-wrap: wrap;
