.fr-action-status__pause {
  align-items: center;
  align-self: center;
  aspect-ratio: 1;
  background: var(--accent);
  border: 1px solid var(--accent-strong);
  border-radius: 50%;
  box-shadow: 0 1px 2px rgba(0, 95, 70, 0.14);
  color: #fff;
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  height: 26px;
  justify-content: center;
  margin-left: 2px;
  max-height: 26px;
  max-width: 26px;
  min-height: 26px;
  min-width: 26px;
  padding: 0;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.12s ease;
  width: 26px;
}

.fr-action-status__pause svg {
  display: block;
  height: 12px;
  width: 12px;
}

.fr-action-status__pause:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
  box-shadow: 0 2px 6px rgba(0, 95, 70, 0.2);
  transform: translateY(-1px);
}

.fr-action-status__pause:active:not(:disabled) {
  transform: translateY(0);
}

.fr-action-status__pause:disabled {
  cursor: wait;
  opacity: 0.55;
}

