}

.fr-action-status__cancel {
  align-items: center;
  aspect-ratio: 1;
  background: color-mix(in srgb, #b42318 82%, #fff);
  border: 1px solid color-mix(in srgb, #b42318 72%, #7f1d1d);
  border-radius: 50%;
  box-shadow: 0 1px 2px rgba(180, 35, 24, 0.14);
  color: #fff;
