  display: inline-flex;
  flex: 0 0 auto;
  height: 26px;
  justify-content: center;
  max-height: 26px;
  max-width: 26px;
  min-height: 26px;
  min-width: 26px;
  padding: 0;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.12s ease;
  width: 26px;
}

