}

.fr-action-status__body {
  display: grid;
  flex: 1 1 auto;
  gap: 8px;
  min-width: 0;
}

.fr-action-status__message {
  color: var(--text);
  font-size: 0.92rem;
  line-height: 1.4;
  margin: 0;
}

.fr-action-status__progress {
  background: color-mix(in srgb, var(--line) 55%, transparent);
  border-radius: 999px;
  height: 3px;
  overflow: hidden;
  width: 100%;
}

.fr-action-status__progress-bar {
  background: var(--accent-strong);
  border-radius: inherit;
  display: block;
  height: 100%;
  width: 36%;
}

.fr-action-status__progress.is-indeterminate .fr-action-status__progress-bar {
  animation: fr-action-status-indeterminate 1.2s ease-in-out infinite;
}

.fr-action-status__dismiss {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: 6px;
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  height: 28px;
  justify-content: center;
  margin: -4px -4px 0 0;
  opacity: 0.72;
  padding: 0;
  width: 28px;
}

.fr-action-status__dismiss:hover {
  opacity: 1;
}

.fr-action-status__dismiss:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 1px;
}

.fr-action-status__dismiss svg {
  height: 14px;
  width: 14px;
}

.fr-action-status.is-queued {
  background: color-mix(in srgb, var(--accent) 7%, #fff);
  border-color: color-mix(in srgb, var(--accent) 22%, var(--line));
  box-shadow: inset 3px 0 0 var(--accent);
  color: color-mix(in srgb, var(--accent-strong) 70%, var(--text));
}

.fr-action-status.is-running {
  background: color-mix(in srgb, var(--accent) 9%, #fff);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line));
  box-shadow: inset 3px 0 0 var(--accent-strong);
  color: color-mix(in srgb, var(--accent-strong) 75%, var(--text));
}

.fr-action-status.is-success {
  background: color-mix(in srgb, var(--good) 10%, #fff);
  border-color: color-mix(in srgb, var(--good) 28%, var(--line));
  box-shadow: inset 3px 0 0 var(--good);
  color: color-mix(in srgb, var(--good) 55%, var(--text));
}

.fr-action-status.is-warning {
  background: color-mix(in srgb, var(--warning) 12%, #fff);
  border-color: color-mix(in srgb, var(--warning) 32%, var(--line));
  box-shadow: inset 3px 0 0 var(--warning);
  color: color-mix(in srgb, var(--warning) 45%, var(--text));
}

.fr-action-status.is-error {
  background: color-mix(in srgb, var(--danger) 10%, #fff);
  border-color: color-mix(in srgb, var(--danger) 28%, var(--line));
  box-shadow: inset 3px 0 0 var(--danger);
  color: color-mix(in srgb, var(--danger) 50%, var(--text));
}

.fr-action-status-slot {
