}

@keyframes fr-action-status-indeterminate {
  0% {
    transform: translateX(-120%);
  }
  100% {
    transform: translateX(320%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .fr-action-status.is-running .fr-action-status__icon svg,
  .fr-action-status__progress.is-indeterminate .fr-action-status__progress-bar {
