}

@media (max-width: 980px) {
  .ops-jobs-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-jobs-controls__showing {
    margin-left: 0;
    width: 100%;
  }

  .ops-jobs-table {
    min-width: 56rem;
  }
}

@media (max-width: 720px) {
  .ops-jobs-table__copy,
  .ops-jobs-delete {
    opacity: 1;
  }
}

