  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92) 0%, rgba(237, 242, 240, 0.92) 100%);
  border: 1px solid color-mix(in srgb, var(--line) 58%, transparent);
  border-radius: 14px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.95) inset,
    0 4px 10px rgba(15, 23, 42, 0.08);
  color: color-mix(in srgb, var(--muted) 72%, var(--text) 28%);
  display: flex;
  flex: 0 0 auto;
  height: 3.25rem;
  justify-content: center;
  width: 3.25rem;
}

.capture-inbox-session-ribbon-empty__card.is-filtered .capture-inbox-session-ribbon-empty__glyph {
  color: var(--accent);
}

.capture-inbox-session-ribbon-empty__copy {
  display: flex;
  flex: 1 1 14rem;
  flex-direction: column;
  gap: 0.22rem;
  min-width: 0;
}

.capture-inbox-session-ribbon-empty__eyebrow {
  color: color-mix(in srgb, var(--muted) 88%, var(--text) 12%);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  line-height: 1.2;
  text-transform: uppercase;
}

.capture-inbox-session-ribbon-empty__title {
  color: var(--text);
  font-size: 1.02rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  line-height: 1.25;
  margin: 0;
}

.capture-inbox-session-ribbon-empty__detail {
  color: color-mix(in srgb, var(--muted) 84%, var(--text) 16%);
  font-size: 0.86rem;
  line-height: 1.45;
  margin: 0;
  max-width: 42rem;
}

.capture-inbox-session-ribbon-empty__action {
  align-items: center;
  align-self: center;
  background: linear-gradient(180deg, #ffffff 0%, #f3f7f5 100%);
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line) 66%);
  border-radius: 999px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.95) inset,
    0 6px 14px rgba(15, 23, 42, 0.08);
  color: var(--accent);
  cursor: pointer;
  display: inline-flex;
  flex: 0 0 auto;
  font: inherit;
  gap: 0.48rem;
  margin-left: auto;
  min-height: 2.55rem;
  padding: 0.28rem 0.92rem 0.28rem 0.42rem;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.capture-inbox-session-ribbon-empty__action-icon {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 10%, white);
  border-radius: 999px;
  display: inline-flex;
  flex-shrink: 0;
  height: 2rem;
  justify-content: center;
  width: 2rem;
}

.capture-inbox-session-ribbon-empty__action-glyph {
  block-size: 0.95rem;
  color: var(--accent);
  inline-size: 0.95rem;
}

.capture-inbox-session-ribbon-empty__action-label {
  color: color-mix(in srgb, var(--accent) 78%, var(--text) 22%);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.005em;
  line-height: 1.2;
  white-space: nowrap;
}

.capture-inbox-session-ribbon-empty__action:hover {
  background: linear-gradient(180deg, #ffffff 0%, #eef6f2 100%);
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line) 52%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.95) inset,
    0 8px 16px rgba(15, 23, 42, 0.1);
  transform: translateY(-1px);
}

.capture-inbox-session-row {
  background: linear-gradient(165deg, #ffffff 0%, #f8fbfb 54%, #edf2f0 100%);
  border: 1px solid color-mix(in srgb, var(--line) 52%, transparent);
  border-bottom-color: color-mix(in srgb, var(--line) 76%, #64748b 24%);
  border-radius: 18px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.96) inset,
    0 -1px 0 rgba(15, 23, 42, 0.04) inset,
    0 10px 20px rgba(15, 23, 42, 0.1),
    0 3px 7px rgba(15, 23, 42, 0.06);
  display: grid;
  flex: 1 1 15rem;
  gap: 8px;
  isolation: isolate;
  min-height: 0;
  min-width: 15rem;
  padding: 0.62rem 0.72rem 0.66rem;
  position: relative;
  scroll-snap-align: start;
  text-align: left;
  transform: translateY(-2px);
  transition:
    background 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

.capture-inbox-session-row::before {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.88) 0%, rgba(255, 255, 255, 0) 100%);
  border-radius: 16px 16px 42% 42% / 16px 16px 10px 10px;
  content: "";
  height: 46%;
  inset: 1px 1px auto;
  pointer-events: none;
  position: absolute;
  z-index: 0;
}

.capture-inbox-session-top,
.capture-inbox-session-body,
.capture-inbox-session-main {
  position: relative;
  z-index: 1;
}

.capture-inbox-session-row.selected,
.capture-inbox-session-row.is-active {
  background: linear-gradient(165deg, #ffffff 0%, color-mix(in srgb, var(--accent) 5%, #f8fbfb) 54%, color-mix(in srgb, var(--accent) 8%, #edf2f0) 100%);
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line) 66%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.96) inset,
    0 0 0 1px color-mix(in srgb, var(--accent) 12%, transparent),
    0 12px 22px rgba(15, 23, 42, 0.12),
    0 4px 8px rgba(15, 23, 42, 0.07);
  transform: translateY(-3px);
}

.capture-inbox-session-top {
  align-items: start;
  display: grid;
  gap: 8px 10px;
  grid-template-columns: minmax(0, 1fr) auto;
}

.capture-inbox-session-meta {
  display: grid;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
}

.capture-inbox-session-status-group {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  max-width: 100%;
  min-width: 0;
}

.capture-inbox-session-status-group .status-badge {
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.035em;
  max-width: 100%;
  min-height: 22px;
  overflow: hidden;
  padding: 4px 8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.capture-inbox-session-current-dot {
  background: var(--accent);
  border-radius: 999px;
  box-shadow: 0 0 0 3px rgba(0, 122, 90, 0.12);
  display: inline-block;
  height: 7px;
  width: 7px;
}

.capture-inbox-session-actions {
  display: inline-flex;
  flex-shrink: 0;
  gap: 4px;
  justify-self: end;
}

.capture-inbox-session-main {
  background: transparent;
  border: 0;
  cursor: pointer;
  display: block;
  min-width: 0;
  padding: 0;
  text-align: left;
  width: 100%;
}

.capture-inbox-session-row:hover:not(.selected) {
  border-color: color-mix(in srgb, var(--accent) 22%, var(--line) 78%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.98) inset,
    0 14px 24px rgba(15, 23, 42, 0.12),
    0 5px 10px rgba(15, 23, 42, 0.08);
  transform: translateY(-4px);
}

.capture-inbox-session-profile-link:hover,
.capture-inbox-session-main:focus-visible .capture-inbox-session-title {
  color: var(--accent-strong);
}

.capture-inbox-session-action-btn:focus-visible,
.capture-inbox-session-profile-link:focus-visible,
.capture-inbox-session-main:focus-visible {
  outline: 2px solid rgba(0, 122, 90, 0.22);
  outline-offset: 2px;
}

.capture-inbox-session-title-row {
  align-items: center;
  display: flex;
  gap: 8px;
  min-width: 0;
}

.capture-inbox-session-title {
  color: var(--text);
  flex: 1 1 auto;
  font-size: 0.8125rem;
  font-weight: 700;
  line-height: 1.25;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.capture-inbox-session-title-row .capture-inbox-session-latest-badge {
  flex-shrink: 0;
}

.capture-inbox-session-time {
  color: var(--muted);
  font-size: 0.6875rem;
  line-height: 1.2;
  white-space: nowrap;
}

.capture-inbox-session-counts {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.capture-inbox-session-summary-chip {
  align-items: center;
  background: var(--panel);
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 999px;
  color: var(--muted);
  display: inline-flex;
  font-size: 0.6875rem;
  gap: 0.3rem;
  line-height: 1;
  min-height: 24px;
  padding: 0.2rem 0.5rem;
  white-space: nowrap;
}

.capture-inbox-session-summary-chip strong {
  color: var(--text);
  font-size: 0.75rem;
  font-weight: 800;
}

.capture-inbox-session-summary-chip.is-ready strong {
  color: var(--good);
}

.capture-inbox-session-summary-chip.is-current {
  background: color-mix(in srgb, var(--accent) 8%, white);
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line) 70%);
}

.capture-inbox-session-row.selected .capture-inbox-session-summary-chip.is-current strong {
  color: var(--accent-strong);
}

.capture-inbox-session-pill {
  align-items: baseline;
  background: rgba(240, 244, 248, 0.9);
  border: 1px solid rgba(209, 218, 229, 0.9);
  border-radius: 999px;
  color: var(--muted);
  display: inline-flex;
  gap: 4px;
  min-height: 22px;
  padding: 2px 8px;
  white-space: nowrap;
}

.capture-inbox-session-pill strong {
  color: var(--text);
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.capture-inbox-session-pill small {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
}

.capture-inbox-session-pill.ready {
  color: var(--good);
}

.capture-inbox-session-pill.duplicate {
  color: var(--warning);
}

.capture-inbox-session-pill.fail {
  color: var(--danger);
}

.capture-inbox-session-pill.is-current {
  background: color-mix(in srgb, var(--accent) 12%, white);
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line) 72%);
  color: var(--accent-strong);
}

.capture-inbox-session-pill.is-current strong {
  color: var(--accent-strong);
}

.capture-inbox-session-row.selected .capture-inbox-session-title {
  color: var(--accent-strong);
}

.capture-inbox-session-row.selected .capture-inbox-session-pill {
  background: rgba(232, 245, 239, 0.92);
  border-color: rgba(159, 211, 186, 0.8);
}

.capture-inbox-session-row.selected .capture-inbox-session-pill strong {
  color: var(--accent-strong);
}

.capture-inbox-media-gallery {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 12px;
}

.capture-inbox-media-gallery-heading {
  align-items: start;
  display: flex;
  gap: 10px;
  justify-content: space-between;
}

.capture-inbox-media-gallery-heading h2 {
  margin: 0;
}

.capture-inbox-media-gallery-heading span {
  color: var(--muted);
  font-size: 12px;
}

.capture-inbox-gallery-heading-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  justify-content: flex-end;
}

.capture-inbox-gallery-select-visible {
  align-items: center;
  background: color-mix(in srgb, var(--panel) 92%, #fff 8%);
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  display: inline-flex;
  font-size: 0.76rem;
  font-weight: 700;
  gap: 0.35rem;
  min-height: 2rem;
  padding: 0.28rem 0.68rem;
}

.capture-inbox-gallery-select-visible:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--accent) 34%, var(--line));
  color: var(--accent);
}

.capture-inbox-gallery-select-visible__icon {
  height: 1rem;
  width: 1rem;
}

.capture-inbox-gallery-preloading {
  display: grid;
  gap: 0.75rem;
  min-height: 510px;
}

.capture-inbox-gallery-preloading__status {
  align-items: center;
  background: color-mix(in srgb, var(--accent) 5%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--accent) 18%, var(--line));
  border-radius: 12px;
  display: flex;
  gap: 0.65rem;
  padding: 0.65rem 0.75rem;
}

.capture-inbox-gallery-preloading__status > div {
  display: grid;
  gap: 0.12rem;
}

.capture-inbox-gallery-preloading__status strong {
  font-size: 0.82rem;
}

.capture-inbox-gallery-preloading__status span:last-child {
  color: var(--muted);
  font-size: 0.72rem;
}

.capture-inbox-gallery-preloading__spinner {
  animation: capture-inbox-gallery-spin 720ms linear infinite;
  border: 2px solid color-mix(in srgb, var(--accent) 20%, transparent);
  border-radius: 50%;
  border-top-color: var(--accent);
  height: 1.25rem;
  width: 1.25rem;
}

.capture-inbox-gallery-preloading__grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.capture-inbox-gallery-preloading__tile {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  display: grid;
  gap: 0.55rem;
  overflow: hidden;
  padding: 0.65rem;
}

.capture-inbox-gallery-preloading__media,
.capture-inbox-gallery-preloading__line,
.capture-inbox-gallery-preloading__pills span {
  animation: capture-inbox-gallery-shimmer 1.25s ease-in-out infinite;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--line) 46%, var(--panel)) 20%,
    color-mix(in srgb, var(--accent) 8%, var(--panel)) 50%,
    color-mix(in srgb, var(--line) 46%, var(--panel)) 80%
  );
  background-size: 220% 100%;
}

.capture-inbox-gallery-preloading__media {
  aspect-ratio: 16 / 10;
  border-radius: 9px;
}

.capture-inbox-gallery-preloading__line {
  border-radius: 999px;
  display: block;
  height: 0.55rem;
  width: 68%;
}

.capture-inbox-gallery-preloading__line.is-wide {
  width: 92%;
}

.capture-inbox-gallery-preloading__pills {
  display: flex;
  gap: 0.35rem;
}

.capture-inbox-gallery-preloading__pills span {
  border-radius: 999px;
  height: 1.4rem;
  width: 30%;
}

@keyframes capture-inbox-gallery-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes capture-inbox-gallery-shimmer {
  0% {
    background-position: 120% 0;
  }

  100% {
    background-position: -120% 0;
  }
}

@media (max-width: 960px) {
  .capture-inbox-gallery-preloading__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .capture-inbox-gallery-preloading__grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.capture-inbox-media-tile-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  min-width: 0;
}

.capture-inbox-virtual-scroll {
  overflow: visible;
}

.capture-inbox-virtual-spacer {
  position: relative;
  width: 100%;
}

.capture-inbox-virtual-window {
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
}

.capture-inbox-virtual-row {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(var(--capture-inbox-virtual-columns, 4), minmax(0, 1fr));
  min-height: var(--capture-inbox-virtual-row-height, 510px);
  min-width: 0;
  padding-bottom: var(--capture-inbox-virtual-row-gap, 12px);
}

.capture-inbox-load-more-sentinel {
  block-size: 1px;
  flex-shrink: 0;
  margin: 0;
  opacity: 0;
  pointer-events: none;
}

/* Work Soft CTA pager (concept C) */
.work-studio-pager {
  align-items: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
  justify-content: center;
  margin-top: 18px;
  padding: 18px 16px 8px;
  text-align: center;
}

.work-studio-pager.is-auto-load {
  border-top: 1px solid var(--line);
  flex-shrink: 0;
  gap: 10px;
  margin-top: 0;
  padding: 14px 0 4px;
  text-align: left;
}

.capture-inbox-media-gallery > .work-studio-pager.is-auto-load {
  margin-top: 0;
}

.work-studio-pager__row {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  justify-content: space-between;
  width: 100%;
}

.work-studio-pager__meta {
  color: var(--muted);
  font-size: 13px;
  font-weight: 550;
  letter-spacing: 0.01em;
  margin: 0;
}

.work-studio-pager.is-auto-load .work-studio-pager__meta {
  color: var(--text);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.work-studio-pager__track {
  display: grid;
  gap: 6px;
  width: 100%;
}

.work-studio-pager__bar {
  background: #e8eef0;
  border-radius: 999px;
  height: 4px;
  overflow: hidden;
  width: 100%;
}

.work-studio-pager__bar > span {
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 88%, #0f172a 12%), var(--accent));
  border-radius: inherit;
  display: block;
  height: 100%;
  min-width: 0;
  transition: width 220ms ease;
}

.work-studio-pager.is-auto-load .work-studio-pager__bar > span {
  transition: width 220ms ease;
}

.work-studio-pager.is-auto-load[aria-busy="true"] .work-studio-pager__bar > span {
  transition: none;
}

.work-studio-pager__hint {
  color: var(--muted);
  font-size: 12px;
  font-weight: 550;
  margin: 0;
  min-height: 1.2em;
}

.work-studio-pager[aria-busy="true"] .work-studio-pager__hint {
  color: color-mix(in srgb, var(--accent) 78%, #0f172a 22%);
}

.work-studio-pager__cta {
  background: #fff;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
  color: color-mix(in srgb, var(--accent) 88%, #0f172a 12%);
  cursor: pointer;
  font-size: 14px;
  font-weight: 650;
  min-height: 42px;
  min-width: min(100%, 280px);
  padding: 0 22px;
  transition: background 140ms ease, border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}

.work-studio-pager__cta:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 8%, #fff);
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  box-shadow: 0 4px 14px color-mix(in srgb, var(--accent) 16%, transparent);
  transform: translateY(-1px);
}

.work-studio-pager__cta:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.work-studio-pager__complete {
  color: var(--muted);
  font-size: 13px;
  font-weight: 600;
  margin: 0;
}

.work-studio-pager__pages {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: flex-end;
  margin-left: auto;
}

.work-studio-pager.is-auto-load .work-studio-pager__pages {
  justify-content: flex-end;
}

.work-studio-pager__pages-label {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  margin-right: 2px;
}

.work-studio-pager__page {
  background: transparent;
  border: 0;
  border-radius: 999px;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  font-weight: 650;
  min-height: 28px;
  min-width: 2.4rem;
  padding: 0 10px;
}

.work-studio-pager__page:hover:not(:disabled) {
  background: #f4f6f8;
  color: var(--text);
}

.work-studio-pager__page.is-active {
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  color: color-mix(in srgb, var(--accent) 88%, #0f172a 12%);
}

.work-studio-pager__page:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.capture-inbox-media-tile {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 14px;
  display: grid;
  gap: 8px;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: 100%;
  overflow: hidden;
  padding: 8px;
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease;
}

.capture-inbox-media-tile:hover {
  box-shadow: 0 10px 22px rgba(18, 30, 45, 0.12);
  transform: translateY(-2px);
}

.capture-inbox-media-tile[data-tone="ready"]:hover,
.capture-inbox-media-tile[data-tone="good"]:hover {
  background: color-mix(in srgb, var(--accent) 6%, #fff);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--accent) 22%, transparent),
    0 12px 24px color-mix(in srgb, var(--accent) 16%, transparent);
}

.capture-inbox-media-tile[data-tone="warn"]:hover {
  background: color-mix(in srgb, var(--warning) 7%, #fff);
  border-color: color-mix(in srgb, var(--warning) 38%, var(--line));
  box-shadow:
