  justify-items: center;
  gap: 14px;
  text-align: center;
}

.review-board-theater-card .review-board-candidate-preview {
  width: min(320px, 68vw);
  min-height: 380px;
  border: 1px solid color-mix(in srgb, var(--accent) 20%, var(--line));
  border-radius: 22px;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.14);
}

.review-board-theater-card h2 {
  max-width: 760px;
  margin: 0;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  color: var(--text);
  font-size: clamp(1.4rem, 2.4vw, 2.35rem);
  letter-spacing: -0.045em;
  line-height: 1.04;
}

.review-board-theater-facts,
.review-board-theater-metrics {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
}

.review-board-theater-facts span,
.review-board-theater-metrics span {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 7px 10px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 750;
}

.review-board-decision-panel {
  position: sticky;
  top: 10px;
  display: grid;
  gap: 14px;
  padding: 16px;
  background: #fff;
}

.review-board-decision-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.review-board-decision-header h2,
.review-board-filmstrip-header h2 {
  margin: 0;
  letter-spacing: -0.03em;
}

.review-board-full-caption {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px;
  background: var(--panel-strong);
}

.review-board-full-caption h3,
.review-board-full-caption p {
  margin: 0;
}

.review-board-full-caption p {
  max-height: 132px;
  overflow: auto;
  margin-top: 8px;
  color: var(--muted);
  line-height: 1.5;
}

.review-board-panel-more {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-panel-more button {
  background: transparent;
}

.review-board-filmstrip,
.review-board-theater-debug {
  grid-column: 1 / -1;
}

.review-board-filmstrip-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.review-board-filmstrip-header p {
  margin: 0;
  color: var(--muted);
  font-size: 0.84rem;
}

.review-board-filmstrip-track {
  display: grid;
  grid-auto-columns: minmax(112px, 132px);
  grid-auto-flow: column;
  gap: 10px;
  overflow-x: auto;
  padding: 2px 2px 10px;
}

.review-board-filmstrip-item {
  content-visibility: auto;
  contain-intrinsic-size: 184px 132px;
  display: grid;
  gap: 6px;
  min-height: 184px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--text);
  text-align: left;
  box-shadow: none;
}

.review-board-filmstrip-item:hover,
.review-board-filmstrip-item:focus-visible,
.review-board-filmstrip-item.selected {
  outline: 0;
  border-color: color-mix(in srgb, var(--accent) 58%, var(--line));
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.12);
  transform: translateY(-1px);
}

.review-board-filmstrip-item .review-board-candidate-preview {
  min-height: 112px;
  border-radius: 14px;
}

.review-board-filmstrip-item span,
.review-board-filmstrip-item small {
  color: var(--muted);
  font-size: 0.74rem;
  font-weight: 800;
}

.review-board-filmstrip-item strong {
  font-size: 0.95rem;
}

.review-board-filter-toolbar {
  padding: 10px;
}

.review-board-header-summary {
  color: var(--muted);
  font-size: 13px;
  margin: 6px 0 0;
}

.review-board-refreshing-banner {
  color: var(--accent-strong);
  font-size: 12px;
  font-weight: 700;
  margin: 0;
  padding: 0 4px;
}

.review-board-theater-skeleton {
  display: grid;
  gap: 14px;
  justify-items: center;
  padding: 12px 0 20px;
}

.review-board-theater-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(135deg, rgba(15, 23, 42, 0.08), rgba(15, 23, 42, 0.04));
  border-radius: 22px;
  height: 380px;
  width: min(320px, 68vw);
}

.review-board-theater-skeleton-line {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: rgba(15, 23, 42, 0.08);
  border-radius: 999px;
  height: 12px;
  width: min(280px, 70vw);
}

.review-board-theater-skeleton-line-wide {
  height: 18px;
  width: min(420px, 82vw);
}

.review-board-theater-skeleton-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.review-board-theater-skeleton-chips span {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: rgba(15, 23, 42, 0.07);
  border-radius: 999px;
  display: block;
  height: 28px;
  width: 88px;
}

@keyframes review-board-skeleton-pulse {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 1; }
}

.review-board-pipeline-strip {
  padding: 6px;
}

@media (max-width: 1080px) {
  .review-board-theater-shell {
    grid-template-columns: 1fr;
  }

  .review-board-decision-panel {
    position: static;
  }
}

@media (max-width: 720px) {
  .review-board-theater-stage {
    min-height: auto;
    padding: 12px;
  }

  .review-board-theater-card .review-board-candidate-preview {
    width: min(310px, 86vw);
    min-height: 340px;
    border-radius: 22px;
  }

  .review-board-filmstrip-track {
    grid-auto-columns: minmax(96px, 112px);
  }
}

/* Phase 22F-3A: Review Board master-detail inbox */
.review-board-inbox-shell {
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(280px, 0.95fr) minmax(0, 1.35fr);
  min-height: 520px;
}

.review-board-queue-panel,
.review-board-detail-panel {
  display: grid;
  gap: 10px;
  min-height: 0;
  padding: 12px;
}

.review-board-queue-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.review-board-queue-header h2,
.review-board-detail-card h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-queue-header p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-queue-list {
  display: grid;
  gap: 6px;
  max-height: min(72vh, 760px);
  overflow: auto;
  padding-right: 2px;
}

.review-board-queue-row {
  align-items: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  cursor: pointer;
  display: grid;
  gap: 8px;
  grid-template-columns: auto auto auto auto minmax(0, 1fr);
  padding: 10px;
  text-align: left;
  width: 100%;
}

.review-board-queue-row:hover,
.review-board-queue-row:focus-visible,
.review-board-queue-row.selected {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 55%, transparent);
}

.review-board-queue-index {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  min-width: 22px;
}

.review-board-queue-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.review-board-queue-copy strong {
  color: var(--text);
  display: -webkit-box;
  font-size: 13px;
  line-height: 1.25;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

.review-board-queue-copy small {
  color: var(--muted);
  font-size: 11px;
}

.review-board-detail-card {
  display: grid;
  gap: 10px;
}

.review-board-detail-header,
.review-board-detail-facts,
.review-board-detail-metrics {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-detail-facts span,
.review-board-detail-metrics span {
  color: var(--muted);
  font-size: 12px;
}

.review-board-detail-card .review-board-candidate-preview {
  aspect-ratio: 3 / 4;
  border-radius: 16px;
  height: auto;
  margin: 0 auto;
  max-height: 360px;
  width: min(240px, 100%);
}

.review-board-detail-actions {
  position: sticky;
  bottom: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0), #fff 28%);
  padding-top: 8px;
}

.review-board-session-progress {
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 12px;
  gap: 14px;
  padding: 10px 12px;
}

.review-board-session-progress strong {
  color: var(--text);
}

.review-board-queue-skeleton,
.review-board-detail-skeleton {
  display: grid;
  gap: 8px;
}

.review-board-queue-skeleton-row,
.review-board-detail-skeleton-line,
.review-board-detail-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 10px;
}

.review-board-queue-skeleton-row {
  min-height: 54px;
}

.review-board-detail-skeleton-preview {
  aspect-ratio: 3 / 4;
  margin: 0 auto;
  max-width: 240px;
  width: 100%;
}

.review-board-detail-skeleton-line {
  min-height: 14px;
}

.review-board-detail-skeleton-line-wide {
  width: 72%;
}

@keyframes review-board-skeleton-pulse {
  0% { opacity: 0.72; }
  50% { opacity: 1; }
  100% { opacity: 0.72; }
}

@media (max-width: 980px) {
  .review-board-inbox-shell {
    grid-template-columns: 1fr;
  }

  .review-board-queue-list {
    max-height: 320px;
  }
}

.review-board-summary-strip {
  color: var(--muted);
  font-size: 13px;
  margin: 0 0 10px;
}

.review-board-batch-bar {
  backdrop-filter: blur(6px);
  background: color-mix(in srgb, var(--panel) 94%, white 6%);
  border: 1px solid var(--line);
  border-radius: 12px;
  bottom: 12px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.1);
  padding: 8px 10px;
  position: sticky;
  z-index: 6;
}

.review-board-batch-bar-main {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: space-between;
}

.review-board-batch-bar-actions {
  flex-wrap: wrap;
}

.review-board-batch-bar-actions button {
  min-height: 32px;
  padding: 6px 10px;
}

/* Phase 22F-4A: Review Board comparison bench */
.review-board-comparison-shell {
  display: grid;
  gap: 14px;
}

.review-board-bench-toolbar {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.review-board-bench-toolbar h2,
.review-board-pool-header h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-bench-toolbar p,
.review-board-pool-header p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-bench-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.review-board-bench-slot {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
  display: grid;
  gap: 10px;
  min-height: 420px;
  padding: 12px;
}

.review-board-bench-slot.active {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
}

.review-board-bench-slot.empty {
  background: color-mix(in srgb, var(--panel) 88%, white 12%);
}

.review-board-bench-slot-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.review-board-bench-slot-label {
  background: color-mix(in srgb, var(--accent) 12%, white);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--line));
  border-radius: 999px;
  font-weight: 800;
  padding: 4px 10px;
}

.review-board-bench-slot-empty {
  align-items: center;
  color: var(--muted);
  display: grid;
  font-size: 13px;
  justify-items: center;
