  padding: 16px;
  text-align: center;
}

.review-board-bench-slot-kicker,
.review-board-bench-slot-metrics {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-bench-slot-metrics {
  color: var(--muted);
  font-size: 12px;
}

.review-board-bench-slot h3 {
  color: var(--text);
  display: -webkit-box;
  font-size: 14px;
  line-height: 1.35;
  margin: 0;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
}

.review-board-bench-preview {
  margin: 0 auto;
  max-height: 280px;
  width: min(100%, 220px);
}

.review-board-bench-slot-actions {
  margin-top: auto;
}

.review-board-pool-panel {
  display: grid;
  gap: 10px;
  padding: 12px;
}

.review-board-pool-header {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.review-board-pool-slot-picker {
  display: flex;
  gap: 6px;
}

.review-board-pool-slot-picker button {
  border-radius: 999px;
  min-height: 32px;
  padding: 4px 12px;
}

.review-board-pool-slot-picker button.active {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.review-board-pool-track {
  display: grid;
  gap: 10px;
  grid-auto-columns: 160px;
  grid-auto-flow: column;
  overflow-x: auto;
  padding-bottom: 4px;
}

.review-board-pool-tile {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 14px;
  cursor: pointer;
  display: grid;
  gap: 8px;
  padding: 8px;
  text-align: left;
  width: 160px;
}

.review-board-pool-tile:hover,
.review-board-pool-tile:focus-visible {
  border-color: var(--accent);
}

.review-board-pool-tile .review-board-candidate-preview {
  height: 200px;
  width: 100%;
}

.review-board-pool-tile-copy {
  display: grid;
  gap: 4px;
}

.review-board-pool-tile-copy strong {
  display: -webkit-box;
  font-size: 12px;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

.review-board-pool-tile-copy small {
  color: var(--muted);
  font-size: 11px;
}

.review-board-filter-toggle-row {
  display: flex;
  justify-content: flex-end;
}

.review-board-bench-slot-skeleton,
.review-board-bench-slot-skeleton-inner .review-board-detail-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 12px;
  min-height: 280px;
}

@media (max-width: 1100px) {
  .review-board-bench-grid {
    grid-template-columns: 1fr;
  }
}

/* Phase 22F-4B: Review Board gallery carousel + pin bench */
.review-board-gallery-shell {
  display: grid;
  gap: 14px;
}

.review-board-gallery-toolbar {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.review-board-gallery-toolbar h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-gallery-toolbar p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-gallery-toolbar-actions button.active {
  background: color-mix(in srgb, var(--accent) 14%, white);
  border-color: var(--accent);
}

.review-board-bench-strip {
  background: color-mix(in srgb, var(--panel) 90%, white 10%);
  border: 1px solid var(--line);
  border-radius: 14px;
  display: grid;
  gap: 8px;
  padding: 10px 12px;
}

.review-board-bench-strip-slots {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.review-board-bench-strip-slot {
  position: relative;
}

.review-board-bench-strip-slot.active .review-board-bench-strip-thumb {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
}

.review-board-bench-strip-thumb {
  background: #fff;
  border: 1px dashed var(--line);
  border-radius: 12px;
  cursor: pointer;
  display: grid;
  min-height: 96px;
  overflow: hidden;
  padding: 0;
  width: 100%;
}

.review-board-bench-strip-slot.filled .review-board-bench-strip-thumb {
  border-style: solid;
}

.review-board-bench-strip-thumb .review-board-candidate-preview {
  height: 96px;
  width: 100%;
}

.review-board-bench-strip-empty-label {
  align-self: center;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  justify-self: center;
}

.review-board-bench-strip-clear {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 999px;
  height: 24px;
  line-height: 1;
  position: absolute;
  right: 6px;
  top: 6px;
  width: 24px;
}

.review-board-bench-strip-hint {
  color: var(--muted);
  font-size: 11px;
  margin: 0;
}

.review-board-bench-strip-hint kbd {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 10px;
  padding: 1px 4px;
}

.review-board-gallery-stage {
  display: grid;
  gap: 12px;
}

.review-board-gallery-nav {
  align-items: center;
  display: flex;
  gap: 12px;
  justify-content: center;
}

.review-board-gallery-nav button {
  border-radius: 999px;
  min-height: 36px;
  min-width: 36px;
}

.review-board-gallery-position {
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
  min-width: 72px;
  text-align: center;
}

.review-board-gallery-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 12px;
  margin: 0 auto;
  max-width: 720px;
  padding: 16px;
  touch-action: pan-y;
  width: 100%;
}

.review-board-gallery-kicker,
.review-board-gallery-metrics {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-gallery-metrics {
  color: var(--muted);
  font-size: 12px;
}

.review-board-gallery-card h3 {
  color: var(--text);
  font-size: 16px;
  line-height: 1.4;
  margin: 0;
}

.review-board-gallery-card .review-board-candidate-preview {
  margin: 0 auto;
  max-height: 420px;
  width: min(100%, 320px);
}

.review-board-gallery-pinned-badge {
  background: color-mix(in srgb, var(--accent) 12%, white);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--line));
  border-radius: 999px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  padding: 2px 8px;
}

.review-board-gallery-actions {
  justify-content: center;
}

.review-board-gallery-filmstrip {
  display: grid;
  gap: 8px;
  grid-auto-columns: 72px;
  grid-auto-flow: column;
  overflow-x: auto;
  padding-bottom: 4px;
}

.review-board-gallery-filmstrip-tile {
  background: #fff;
  border: 2px solid transparent;
  border-radius: 10px;
  height: 96px;
  overflow: hidden;
  padding: 0;
  width: 72px;
}

.review-board-gallery-filmstrip-tile img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.review-board-gallery-filmstrip-tile.active {
  border-color: var(--accent);
}

.review-board-gallery-card-skeleton,
.review-board-gallery-card-skeleton-inner .review-board-detail-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 12px;
  min-height: 360px;
}

@media (max-width: 1100px) {
  .review-board-bench-strip-slots {
    grid-template-columns: 1fr;
  }
}

/* Phase 22F-5A: Review Board decision console */
.review-board-decision-shell {
  display: grid;
  gap: 14px;
}

.review-board-decision-toolbar {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.review-board-decision-toolbar h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-decision-toolbar p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-decision-toolbar-actions button.active {
  background: color-mix(in srgb, var(--accent) 14%, white);
  border-color: var(--accent);
}

.review-board-decision-layout {
  align-items: stretch;
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
}

.review-board-decision-focus {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 18px;
  display: grid;
  gap: 14px;
  padding: 16px;
}

.review-board-decision-focus-header {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: space-between;
}

.review-board-decision-focus-header h2 {
  color: var(--text);
  font-size: 22px;
  margin: 2px 0 0;
}

.review-board-decision-shortcuts {
  color: var(--muted);
  font-size: 11px;
  margin: 0;
}

.review-board-decision-shortcuts kbd {
  background: color-mix(in srgb, var(--panel) 80%, white);
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 10px;
  padding: 1px 4px;
}

.review-board-decision-score-hero {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-decision-preview {
  margin: 0 auto;
  max-height: 460px;
  width: min(100%, 360px);
}

.review-board-decision-caption {
  color: var(--text);
  font-size: 16px;
  line-height: 1.45;
  margin: 0;
}

.review-board-decision-metrics {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
}

.review-board-decision-metric {
  background: color-mix(in srgb, var(--panel) 88%, white 12%);
  border: 1px solid var(--line);
  border-radius: 12px;
  display: grid;
  gap: 4px;
  padding: 10px 12px;
}

.review-board-decision-metric span {
  color: var(--muted);
  font-size: 11px;
}

.review-board-decision-metric strong {
  color: var(--text);
  font-size: 14px;
}

.review-board-decision-actions {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.review-board-decision-actions .primary {
  grid-column: 1 / -1;
}

.review-board-queue-rail {
  background: color-mix(in srgb, var(--panel) 90%, white 10%);
  border: 1px solid var(--line);
  border-radius: 16px;
  display: grid;
  gap: 10px;
  max-height: 720px;
  overflow: hidden;
  padding: 12px;
}

.review-board-queue-rail-header h2 {
  color: var(--text);
  font-size: 15px;
  margin: 0;
}

.review-board-queue-rail-header p {
  color: var(--muted);
  font-size: 11px;
  margin: 4px 0 0;
}

.review-board-queue-rail-list {
  display: grid;
  gap: 8px;
  overflow-y: auto;
  padding-right: 2px;
}

.review-board-queue-row {
  align-items: stretch;
  display: grid;
  gap: 6px;
  grid-template-columns: minmax(0, 1fr) 34px;
}

.review-board-queue-row.focused .review-board-queue-row-main {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 40%, transparent);
}

.review-board-queue-row.starred .review-board-queue-row-star {
  color: #c58a00;
}

.review-board-queue-row-main {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  cursor: pointer;
  display: grid;
  gap: 8px;
  grid-template-columns: 28px 52px minmax(0, 1fr);
  padding: 8px;
  text-align: left;
  width: 100%;
}

.review-board-queue-row-index {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  padding-top: 18px;
}

.review-board-queue-row-thumb {
  border-radius: 8px;
  height: 52px;
  overflow: hidden;
  width: 52px;
}

.review-board-queue-row-thumb img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.review-board-queue-row-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.review-board-queue-row-kicker {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.review-board-queue-row-copy strong {
  color: var(--text);
  display: -webkit-box;
  font-size: 12px;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

.review-board-queue-row-copy small {
  color: var(--muted);
  font-size: 10px;
}

.review-board-queue-row-star {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--muted);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
  min-height: 100%;
}

.review-board-queue-row-star.active {
  background: color-mix(in srgb, #f6c343 18%, white);
  border-color: #d9a400;
  color: #9a6d00;
}

.review-board-compare-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.review-board-compare-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
  display: grid;
  gap: 10px;
  padding: 12px;
}

.review-board-compare-card-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.review-board-compare-card h3 {
  color: var(--text);
  font-size: 14px;
  line-height: 1.35;
  margin: 0;
}

.review-board-compare-card-metrics {
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 12px;
  gap: 8px;
}

.review-board-decision-focus-skeleton,
.review-board-queue-rail-skeleton {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 16px;
  min-height: 420px;
}

.review-board-decision-focus-skeleton-inner .review-board-detail-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 12px;
  min-height: 360px;
}

@media (max-width: 1100px) {
  .review-board-decision-layout {
    grid-template-columns: 1fr;
  }

  .review-board-queue-rail {
    max-height: 320px;
  }

  .review-board-decision-actions {
    grid-template-columns: 1fr;
  }
}

/* Phase 22F-5B: Review Board command bar + compact decision + queue table */
.review-board-sr-only {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
