}

/* Phase 22F-7E: unified command deck */
.review-board-command-deck {
  background: var(--panel);
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 12px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
  display: grid;
  gap: 0;
  margin-bottom: 12px;
  overflow: hidden;
  position: static;
}

.review-board-command-deck-top {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 0.9rem;
  justify-content: space-between;
  padding: 0.58rem 0.85rem 0.5rem;
}

.review-board-command-deck-kicker {
  color: var(--muted);
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1.2;
  text-transform: uppercase;
}

.review-board-command-deck-meta {
  color: var(--muted);
  font-size: 0.875rem;
