}

/* Phase 22F-7M: Review Board status parity with Reup Queue hero stats ? 22F-7N comfortable scale */
.review-board-command-deck-segments.reup-queue-hero-stats.capture-inbox-status-strip {
  align-items: center;
  background: transparent;
  border-block: 1px solid color-mix(in srgb, var(--line) 50%, transparent);
  gap: 0.45rem;
  padding: 0.45rem 0.85rem;
}

.review-board-command-deck-segments .capture-inbox-status-pill.reup-queue-hero-stat {
  flex: 0 1 auto;
  gap: 0.4rem;
