  min-height: unset;
  min-width: unset;
  padding: 0.35rem 0.65rem;
}

.review-board-command-deck-segments .reup-queue-hero-stat span {
  font-size: 0.8125rem;
}

.review-board-command-deck-segments .reup-queue-hero-stat strong {
  font-size: 0.875rem;
}

.review-board-command-deck-filters {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem 0.5rem;
  padding: 0.48rem 0.85rem 0.55rem;
}

.review-board-deck-input {
  background: #fff;
  border: 1px solid color-mix(in srgb, var(--line) 90%, transparent);
  border-radius: 8px;
  color: var(--text);
  font: inherit;
  font-size: 0.875rem;
  min-height: 34px;
  padding: 0.32rem 0.6rem;
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.review-board-deck-input:focus {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line) 45%);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 14%, transparent);
  outline: none;
}

.review-board-deck-search {
  flex: 1 1 220px;
  min-width: 180px;
}

.review-board-deck-sort {
  flex: 0 1 140px;
  min-width: 120px;
}

.review-board-deck-score {
  flex: 0 1 72px;
  min-width: 64px;
  width: 72px;
}

.review-board-command-deck-filter-actions {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  margin-left: auto;
}

.review-board-deck-btn {
  align-items: center;
  background: #fff;
  border: 1px solid color-mix(in srgb, var(--line) 92%, transparent);
  border-radius: 8px;
  color: var(--text);
  cursor: pointer;
  display: inline-flex;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  gap: 4px;
  justify-content: center;
  line-height: 1.2;
  min-height: 32px;
  padding: 0.28rem 0.62rem;
  transition: background-color 120ms ease, border-color 120ms ease, color 120ms ease;
  white-space: nowrap;
}

.review-board-deck-btn:hover:not(:disabled) {
  background: #f8fafc;
  border-color: #c7d2de;
}

.review-board-deck-btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.review-board-deck-btn.is-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.review-board-deck-btn.is-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.review-board-deck-btn.is-accent {
  background: color-mix(in srgb, var(--accent) 10%, white);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line) 58%);
  color: var(--accent-strong);
}

.review-board-deck-btn.is-accent:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 16%, white);
}

.review-board-deck-btn.is-danger {
  background: transparent;
  border-color: color-mix(in srgb, var(--danger) 50%, var(--line) 50%);
  color: var(--danger);
}

.review-board-deck-btn.is-danger:hover:not(:disabled) {
  background: color-mix(in srgb, var(--danger) 8%, white);
}

.review-board-deck-btn.is-ghost {
  background: transparent;
  border-color: transparent;
  color: var(--muted);
}

.review-board-deck-btn.is-ghost:hover:not(:disabled) {
  background: color-mix(in srgb, var(--line) 18%, transparent);
  border-color: color-mix(in srgb, var(--line) 70%, transparent);
  color: var(--text);
}

.review-board-deck-btn.is-link {
  background: transparent;
  border-color: transparent;
  color: var(--muted);
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.review-board-deck-btn.is-link:hover:not(:disabled) {
  color: var(--danger);
}

.review-board-command-deck.has-selection {
  border-color: color-mix(in srgb, var(--accent) 28%, var(--line) 72%);
}

.review-board-command-deck-bulk {
