.reup-queue-tile-failure-strip__icon svg {
  display: block;
  height: 12px;
  width: 12px;
}

.reup-queue-tile-failure-strip__text {
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.01em;
  line-height: 1.25;
