  color: var(--muted);
  margin: 0;
  padding: 1rem;
  text-align: center;
}

.work-item-details-drawer__footer .review-board-inspector-queue-actions {
  width: 100%;
}

@media (max-width: 420px) {
  .review-board-inspector-metadata-grid {
    grid-template-columns: 1fr;
  }

  .review-board-inspector-section-heading small {
    display: none;
  }
}

/* Capture Inbox tile grammar for downstream production cards. */
.reup-queue-pipeline-strip.is-tile {
  margin-top: 4px;
  width: 100%;
}

.reup-queue-pipeline-stepper {
  width: 100%;
  display: grid;
  gap: 0;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}

.reup-queue-pipeline-stepper__step {
  align-items: center;
  display: grid;
  gap: 5px;
  justify-items: center;
  min-width: 0;
  position: relative;
  text-align: center;
}

.reup-queue-pipeline-stepper__hit {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: default;
  display: grid;
  gap: 5px;
  justify-items: center;
  min-width: 0;
  padding: 0;
  text-align: inherit;
  text-decoration: none;
  width: 100%;
}

.reup-queue-pipeline-stepper__hit.is-static {
  pointer-events: none;
}

a.reup-queue-pipeline-stepper__hit,
button.reup-queue-pipeline-stepper__hit {
  cursor: pointer;
}

button.reup-queue-pipeline-stepper__hit:disabled {
  cursor: wait;
  opacity: 0.72;
}

.reup-queue-pipeline-stepper__step.is-interactive .reup-queue-pipeline-stepper__node {
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease, background-color 160ms ease, color 160ms ease;
}

.reup-queue-pipeline-stepper__step.is-interactive .reup-queue-pipeline-stepper__label {
  transition: color 160ms ease, transform 160ms ease;
}

.reup-queue-pipeline-stepper__step.is-interactive:hover .reup-queue-pipeline-stepper__node,
.reup-queue-pipeline-stepper__step.is-interactive:focus-within .reup-queue-pipeline-stepper__node {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 24%, transparent), 0 2px 6px rgba(15, 23, 42, 0.12);
  transform: translateY(-1px) scale(1.06);
}

.reup-queue-pipeline-stepper__step.is-interactive:hover .reup-queue-pipeline-stepper__label,
.reup-queue-pipeline-stepper__step.is-interactive:focus-within .reup-queue-pipeline-stepper__label {
  color: var(--text);
  transform: translateY(-1px);
}

.reup-queue-pipeline-stepper__step.is-disabled {
  opacity: 0.72;
}

.reup-queue-pipeline-stepper__step:first-child {
  justify-items: start;
  text-align: left;
}

.reup-queue-pipeline-stepper__step:first-child .reup-queue-pipeline-stepper__hit {
  justify-items: start;
  text-align: left;
}

.reup-queue-pipeline-stepper__step:last-child {
  justify-items: end;
  text-align: right;
}

.reup-queue-pipeline-stepper__step:last-child .reup-queue-pipeline-stepper__hit {
  justify-items: end;
  text-align: right;
}

.reup-queue-pipeline-stepper__step:not(:last-child)::after {
  background: color-mix(in srgb, var(--line) 90%, transparent);
  content: "";
  height: 2px;
  left: calc(50% + 11px);
  position: absolute;
  right: calc(-50% + 11px);
  top: 11px;
  z-index: 0;
}

.reup-queue-pipeline-stepper__step:first-child:not(:last-child)::after {
  left: 22px;
  right: calc(-50% + 11px);
}

.reup-queue-pipeline-stepper__step:nth-last-child(2)::after {
  left: calc(50% + 11px);
  right: calc(-100% + 22px);
}

.reup-queue-pipeline-stepper__step:first-child:nth-last-child(2)::after {
  left: 22px;
  right: calc(-100% + 22px);
}

.reup-queue-pipeline-stepper__step.is-done:not(:last-child)::after,
.reup-queue-pipeline-stepper__step.is-active:not(:last-child)::after {
  background: color-mix(in srgb, var(--accent) 55%, var(--line) 45%);
}

.reup-queue-pipeline-stepper__node {
  align-items: center;
  background: var(--panel);
  border: 1.5px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 999px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
  color: color-mix(in srgb, var(--muted) 70%, var(--text) 30%);
  display: grid;
  flex: 0 0 auto;
  height: 22px;
  place-items: center;
  position: relative;
  width: 22px;
  z-index: 1;
}

.reup-queue-pipeline-stepper__index {
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
}

.reup-queue-pipeline-stepper__check {
  display: block;
  height: 11px;
  width: 11px;
}

.reup-queue-pipeline-stepper__label {
  color: color-mix(in srgb, var(--muted) 45%, var(--text) 55%);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.01em;
  line-height: 1.15;
  max-width: 100%;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
}

.reup-queue-pipeline-stepper__step.is-done .reup-queue-pipeline-stepper__node {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.reup-queue-pipeline-stepper__step.is-done .reup-queue-pipeline-stepper__label {
  color: color-mix(in srgb, var(--accent) 35%, var(--text) 65%);
}

.reup-queue-pipeline-stepper__step.is-active .reup-queue-pipeline-stepper__node {
  animation: reup-queue-pipeline-node-pulse 1.6s ease-in-out infinite;
  background: var(--panel);
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 22%, transparent);
  color: var(--accent);
}

.reup-queue-pipeline-stepper__step.is-active .reup-queue-pipeline-stepper__label {
  color: var(--text);
  font-weight: 750;
}

@keyframes reup-queue-pipeline-node-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  }
  50% {
    box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 28%, transparent);
  }
}

.reup-queue-pipeline-stepper__step.is-failed .reup-queue-pipeline-stepper__node {
  background: color-mix(in srgb, var(--danger) 12%, var(--panel) 88%);
  border-color: var(--danger);
  color: var(--danger);
}

.reup-queue-pipeline-stepper__step.is-failed .reup-queue-pipeline-stepper__label {
  color: var(--danger);
}

.reup-queue-pipeline-stepper__step.is-pending .reup-queue-pipeline-stepper__label {
  color: var(--muted);
}

/* Shared Capture Inbox grammar for operator work studios. */
.work-studio-deck {
  display: grid;
  gap: 12px;
}

.work-studio-deck__header,
.work-studio-deck__status {
  min-width: 0;
}

.work-studio-deck__meta {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
  margin-top: 3px;
}

.work-studio-deck__actions {
  align-items: center;
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.work-studio-action-rail {
  align-items: center;
  background: color-mix(in srgb, var(--panel-strong) 72%, #fff);
  border: 1px solid var(--line);
  border-radius: 999px;
  display: inline-flex;
  overflow: hidden;
}

.work-studio-action-rail > a,
.work-studio-action-rail > button {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: 0;
  color: var(--text);
  display: inline-flex;
  font-size: 12px;
  font-weight: 700;
  gap: 6px;
  min-height: 34px;
  padding: 0 12px;
  text-decoration: none;
}

.work-studio-action-rail > .is-primary {
  background: var(--accent);
  color: #fff;
}

.work-studio-filter-deck {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.05);
  display: grid;
  gap: 10px;
  padding: 12px;
}

.work-studio-filter-deck__header,
.work-studio-filter-deck__controls {
  align-items: center;
  display: flex;
  gap: 10px;
  justify-content: space-between;
  min-width: 0;
}

.work-studio-filter-deck__copy {
  display: grid;
  gap: 2px;
}

.work-studio-filter-deck__kicker,
.work-gallery-header__eyebrow {
  color: var(--accent-strong);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.work-studio-filter-deck__title {
  color: var(--text);
  font-size: 14px;
  font-weight: 750;
}

.work-studio-filter-deck__query {
  align-items: center;
  display: grid;
  gap: 8px;
  grid-template-columns: minmax(220px, 1fr) minmax(150px, auto) auto;
  min-width: 0;
}

.work-studio-filter-deck input,
.work-studio-filter-deck select {
  border: 1px solid var(--line);
  border-radius: 9px;
  min-height: 38px;
  min-width: 0;
  padding: 0 10px;
}

.work-bulk-action-bar {
  display: grid;
  gap: 8px;
  position: sticky;
  top: 12px;
  z-index: 8;
}

.work-bulk-action-bar__status {
  align-items: center;
  display: flex;
  gap: 8px;
  min-width: 0;
}

.work-bulk-action-bar__count {
  background: color-mix(in srgb, var(--accent) 12%, #fff);
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  color: var(--accent-strong);
  font-size: 11px;
  font-weight: 800;
  padding: 5px 9px;
  white-space: nowrap;
}

.work-bulk-action-bar__guidance {
  color: var(--muted);
  font-size: 11px;
  min-width: 0;
}

.work-bulk-action-bar__toolbar {
  margin-left: auto;
}

.work-bulk-action-bar__actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.work-gallery-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.work-gallery-header__copy {
  display: grid;
  gap: 2px;
}

.work-gallery-header__copy h2 {
