}

.work-gallery-empty__action {
  align-self: center;
}

.reup-queue-gallery-empty .capture-inbox-gallery-empty__card {
  flex-direction: column;
  flex-wrap: nowrap;
  justify-content: center;
  min-height: 10.5rem;
  padding: 1.25rem 1rem 1.2rem;
  text-align: center;
}

.reup-queue-gallery-empty .capture-inbox-gallery-empty__copy {
  align-items: center;
  flex: 0 1 auto;
  max-width: 36rem;
}

.reup-queue-gallery-empty .capture-inbox-gallery-empty__title {
  font-size: 0.98rem;
  font-weight: 550;
}

.reup-queue-gallery-empty .capture-inbox-gallery-empty__detail {
  max-width: 32rem;
}

.reup-queue-gallery-empty .capture-inbox-gallery-empty__action {
  margin-left: 0;
  margin-top: 0.35rem;
}

.reup-queue-empty-review-link {
  align-items: center;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: #fff;
  display: inline-flex;
  font-size: 0.82rem;
  font-weight: 650;
  gap: 0.4rem;
  justify-content: center;
  min-height: 34px;
  padding: 0.42rem 0.78rem;
