}

.review-board-gallery-empty .capture-inbox-gallery-empty__card {
  flex-direction: column;
  flex-wrap: nowrap;
  justify-content: center;
  min-height: 11rem;
  padding: 1.35rem 1rem;
  text-align: center;
}

.review-board-gallery-empty .capture-inbox-gallery-empty__copy {
  align-items: center;
  flex: 0 1 auto;
  max-width: 38rem;
}

.review-board-gallery-empty .capture-inbox-gallery-empty__detail {
  max-width: 34rem;
}

.review-board-gallery-empty .capture-inbox-gallery-empty__action {
  margin-left: 0;
  margin-top: 0.25rem;
}

.review-board-empty-capture-link {
  align-items: center;
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 8px;
  color: #fff;
  display: inline-flex;
  font-size: 0.82rem;
  font-weight: 650;
  gap: 0.4rem;
  justify-content: center;
  min-height: 34px;
  padding: 0.42rem 0.72rem;
  text-decoration: none;
}

.review-board-empty-capture-link:hover {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
  color: #fff;
}

.review-board-empty-capture-link__icon {
  flex: 0 0 auto;
  height: 1rem;
  width: 1rem;
}

.work-studio-worklist {
  display: grid;
  gap: 0.75rem;
}

.work-studio-worklist-row {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 3px 12px rgba(15, 23, 42, 0.05);
}

.work-studio-worklist-row.is-bulk-selected,
.work-studio-worklist-row.is-inspector-focused {
  border-color: color-mix(in srgb, var(--accent) 54%, var(--line));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 12%, transparent);
}

@media (max-width: 760px) {
  .work-studio-deck__header,
  .work-studio-filter-deck__header,
  .work-studio-filter-deck__controls,
  .work-gallery-header {
    align-items: stretch;
    flex-direction: column;
  }

  .work-studio-deck__actions,
  .work-gallery-header__actions {
    justify-content: flex-start;
  }

  .work-studio-filter-deck__query {
    grid-template-columns: 1fr;
  }
}

/* Phase 22F-3A: Review Board master-detail inbox */
.review-board-inbox-shell {
  display: grid;
  gap: 12px;
  grid-template-columns: minmax(280px, 0.95fr) minmax(0, 1.35fr);
  min-height: 520px;
}

.review-board-queue-panel,
.review-board-detail-panel {
  display: grid;
  gap: 10px;
  min-height: 0;
  padding: 12px;
}

.review-board-queue-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.review-board-queue-header h2,
.review-board-detail-card h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-queue-header p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-queue-list {
  display: grid;
  gap: 6px;
  max-height: min(72vh, 760px);
  overflow: auto;
  padding-right: 2px;
}

.review-board-queue-row {
  align-items: center;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 12px;
  cursor: pointer;
  display: grid;
  gap: 8px;
  grid-template-columns: auto auto auto auto minmax(0, 1fr);
  padding: 10px;
  text-align: left;
  width: 100%;
}

.review-board-queue-row:hover,
.review-board-queue-row:focus-visible,
.review-board-queue-row.selected {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 55%, transparent);
}

.review-board-queue-index {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  min-width: 22px;
}

.review-board-queue-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.review-board-queue-copy strong {
  color: var(--text);
  display: -webkit-box;
  font-size: 13px;
  line-height: 1.25;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

.review-board-queue-copy small {
  color: var(--muted);
  font-size: 11px;
}

.review-board-detail-card {
  display: grid;
  gap: 10px;
}

.review-board-detail-header,
.review-board-detail-facts,
.review-board-detail-metrics {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-board-detail-facts span,
.review-board-detail-metrics span {
  color: var(--muted);
  font-size: 12px;
}

.review-board-detail-card .review-board-candidate-preview {
  aspect-ratio: 3 / 4;
  border-radius: 16px;
  height: auto;
  margin: 0 auto;
  max-height: 360px;
  width: min(240px, 100%);
}

.review-board-detail-actions {
  position: sticky;
  bottom: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0), #fff 28%);
  padding-top: 8px;
}

.review-board-session-progress {
  align-items: center;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--muted);
  display: flex;
  flex-wrap: wrap;
  font-size: 12px;
  gap: 14px;
  padding: 10px 12px;
}

.review-board-session-progress strong {
  color: var(--text);
}

.review-board-queue-skeleton,
.review-board-detail-skeleton {
  display: grid;
  gap: 8px;
}

.review-board-queue-skeleton-row,
.review-board-detail-skeleton-line,
.review-board-detail-skeleton-preview {
  animation: review-board-skeleton-pulse 1.2s ease-in-out infinite;
  background: linear-gradient(90deg, #eef2ea, #f8faf6, #eef2ea);
  border-radius: 10px;
}

.review-board-queue-skeleton-row {
  min-height: 54px;
}

.review-board-detail-skeleton-preview {
  aspect-ratio: 3 / 4;
  margin: 0 auto;
  max-width: 240px;
  width: 100%;
}

.review-board-detail-skeleton-line {
  min-height: 14px;
}

.review-board-detail-skeleton-line-wide {
  width: 72%;
}

@keyframes review-board-skeleton-pulse {
  0% { opacity: 0.72; }
  50% { opacity: 1; }
  100% { opacity: 0.72; }
}

@media (max-width: 980px) {
  .review-board-inbox-shell {
    grid-template-columns: 1fr;
  }

  .review-board-queue-list {
    max-height: 320px;
  }
}

.review-board-summary-strip {
  color: var(--muted);
  font-size: 13px;
  margin: 0 0 10px;
}

.review-board-batch-bar {
  backdrop-filter: blur(6px);
  background: color-mix(in srgb, var(--panel) 94%, white 6%);
  border: 1px solid var(--line);
  border-radius: 12px;
  bottom: 12px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.1);
  padding: 8px 10px;
  position: sticky;
  z-index: 6;
}

.review-board-batch-bar-main {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: space-between;
}

.review-board-batch-bar-actions {
  flex-wrap: wrap;
}

.review-board-batch-bar-actions button {
  min-height: 32px;
  padding: 6px 10px;
}

/* Phase 22F-4A: Review Board comparison bench */
.review-board-comparison-shell {
  display: grid;
  gap: 14px;
}

.review-board-bench-toolbar {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}

.review-board-bench-toolbar h2,
.review-board-pool-header h2 {
  color: var(--text);
  font-size: 18px;
  margin: 0;
}

.review-board-bench-toolbar p,
.review-board-pool-header p {
  color: var(--muted);
  font-size: 12px;
  margin: 4px 0 0;
}

.review-board-bench-grid {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.review-board-bench-slot {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
  display: grid;
  gap: 10px;
  min-height: 420px;
  padding: 12px;
}

.review-board-bench-slot.active {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 45%, transparent);
}

.review-board-bench-slot.empty {
  background: color-mix(in srgb, var(--panel) 88%, white 12%);
}

.review-board-bench-slot-header {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.review-board-bench-slot-label {
  background: color-mix(in srgb, var(--accent) 12%, white);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--line));
  border-radius: 999px;
  font-weight: 800;
  padding: 4px 10px;
}

.review-board-bench-slot-empty {
  align-items: center;
  color: var(--muted);
