  border-bottom: 1px solid #e5eaf0;
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.78rem 0.85rem;
}

.ops-output-review-inspection__head h3 {
  color: #172033;
  font-size: 0.9rem;
  margin: 0.12rem 0 0;
}

.ops-output-review-inspection__count {
  background: #ecfdf3;
  border: 1px solid #abefc6;
  border-radius: 999px;
  color: #067647;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.22rem 0.5rem;
  white-space: nowrap;
}

.ops-output-review-inspection__count.has-attention {
  background: #fff7ed;
  border-color: #fed7aa;
  color: #b54708;
}

.ops-output-review-check-group {
  padding: 0.78rem 0.85rem;
}

.ops-output-review-check-group + .ops-output-review-check-group {
  border-top: 1px solid #edf0f4;
}

.ops-output-review-check-group__head {
  align-items: baseline;
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.ops-output-review-check-group__head h4 {
  color: #9a3412;
  font-size: 0.75rem;
  margin: 0;
}

.ops-output-review-check-group__head span {
  color: #94a3b8;
  font-size: 0.65rem;
}

.ops-output-review-check-group.is-verified summary {
  align-items: center;
  color: #475569;
  cursor: pointer;
  display: flex;
  font-size: 0.74rem;
  font-weight: 650;
  justify-content: space-between;
  list-style: none;
}

.ops-output-review-check-group.is-verified summary::-webkit-details-marker {
  display: none;
}

.ops-output-review-check-group.is-verified summary span:last-child {
  background: #f1f5f9;
  border-radius: 999px;
  color: #64748b;
  font-size: 0.65rem;
  min-width: 1.4rem;
  padding: 0.14rem 0.4rem;
  text-align: center;
}

.ops-output-review-checks {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ops-output-review-check-group.is-verified[open] .ops-output-review-checks {
  margin-top: 0.55rem;
}

.ops-output-review-checks li {
  align-items: flex-start;
  background: #f8fafc;
  border: 1px solid #e5eaf0;
  border-radius: 8px;
  color: #64748b;
  display: grid;
  font-size: 0.72rem;
  gap: 0.55rem;
  grid-template-columns: 0.5rem minmax(0, 1fr);
  padding: 0.48rem 0.55rem;
}

.ops-output-review-check__indicator {
  background: #22a06b;
  border-radius: 50%;
  height: 0.42rem;
  margin-top: 0.24rem;
  width: 0.42rem;
}

.ops-output-review-check__copy {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.ops-output-review-check__copy strong {
  font-size: 0.74rem;
  color: #172033;
  text-transform: capitalize;
}

.ops-output-review-checks li.is-fail { border-color: #fecdca; background: #fff8f7; }
.ops-output-review-checks li.is-warn { border-color: #fedf89; background: #fffaf0; }
.ops-output-review-checks li.is-fail .ops-output-review-check__indicator { background: #d92d20; }
.ops-output-review-checks li.is-warn .ops-output-review-check__indicator { background: #f79009; }
.ops-output-review-checks li.is-skipped { opacity: 0.68; }
.ops-output-review-checks li.is-skipped .ops-output-review-check__indicator { background: #94a3b8; }

.ops-output-review-command-bar {
  align-items: center;
  background: #fff;
  border-top: 1px solid #e5eaf0;
  display: flex;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.62rem 0.75rem;
}

.ops-output-review-command-bar__actions,
.ops-output-review-command-bar__navigation,
.ops-output-review-pager {
  align-items: center;
  display: flex;
}

.ops-output-review-command-bar__actions {
  flex-wrap: wrap;
  gap: 0.35rem;
}

.ops-output-review-command-bar__navigation {
  flex: none;
  gap: 0.65rem;
}

.ops-output-review-action,
.ops-output-review-link,
.ops-output-review-pager button {
  align-items: center;
  background: #fff;
  border: 1px solid #d5dde7;
  border-radius: 8px;
  color: #334155;
  cursor: pointer;
  display: inline-flex;
  font-size: 0.72rem;
  font-weight: 650;
  gap: 0.32rem;
  justify-content: center;
  line-height: 1.15;
  min-height: 31px;
  padding: 0.36rem 0.62rem;
  text-decoration: none;
  transition: background-color 140ms ease, border-color 140ms ease, color 140ms ease;
  white-space: nowrap;
}

.ops-output-review-action__icon,
.ops-output-review-pager__icon {
  display: block;
  flex: 0 0 auto;
  height: 0.88rem;
  width: 0.88rem;
}

.ops-output-review-action .async-button__icon {
  height: 0.88rem;
  width: 0.88rem;
}

.ops-output-review-link {
  font-weight: 700;
}

.ops-output-review-link.is-primary {
  background: #173b66;
  border-color: #173b66;
  color: #fff;
}

.ops-output-review-link.is-primary:hover {
  background: #0f2d4d;
  color: #fff;
  text-decoration: none;
}

.ops-output-review-link.is-secondary,
.ops-output-review-action.is-secondary {
  border-color: #bfd1e3;
  color: #173b66;
}

.ops-output-review-action.is-muted {
  background: #f8fafc;
  color: #475569;
}

.ops-output-review-action.is-danger {
  border-color: #f4c7c3;
  color: #b42318;
}

.ops-output-review-action.is-quiet {
  background: transparent;
  border-color: transparent;
  color: #64748b;
}

.ops-output-review-action:hover:not(:disabled),
.ops-output-review-link.is-secondary:hover,
.ops-output-review-pager button:hover:not(:disabled) {
  background: #f4f8fc;
  border-color: #9fb8d0;
  color: #173b66;
  text-decoration: none;
}

.ops-output-review-action:disabled,
.ops-output-review-pager button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.ops-output-review-pager {
  border: 1px solid #d5dde7;
  border-radius: 8px;
  overflow: hidden;
}

.ops-output-review-pager button {
  border: 0;
  border-radius: 0;
}

.ops-output-review-pager > span {
  align-items: center;
  align-self: stretch;
  border-left: 1px solid #e5eaf0;
  border-right: 1px solid #e5eaf0;
  color: #64748b;
  display: flex;
  font-size: 0.68rem;
  font-variant-numeric: tabular-nums;
  justify-content: center;
  min-width: 3.2rem;
  padding: 0 0.45rem;
}

.ops-output-review-empty,
.ops-output-review-error {
  margin: 0;
  padding: 0.7rem;
  font-size: 0.82rem;
  color: #6b7280;
}

.ops-output-review-error { color: #b42318; }

.ops-output-review-hint {
  color: #64748b;
  font-size: 0.66rem;
  white-space: nowrap;
}

.ops-output-review-hint kbd {
  padding: 0.05rem 0.3rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: #f3f4f6;
  font-size: 0.72rem;
}

@media (max-width: 1180px) {
  .ops-output-review-summary__metrics {
    grid-template-columns: repeat(4, minmax(130px, 1fr));
  }

  .ops-output-review-stage__body {
    grid-template-columns: minmax(280px, 0.85fr) minmax(280px, 1.15fr);
  }

  .ops-output-review-hint {
    display: none;
  }
}

@media (max-width: 960px) {
  .ops-output-review-layout,
  .ops-output-review-stage__body {
    grid-template-columns: 1fr;
  }

  .ops-output-review-queue-panel {
    position: static;
  }

  .ops-output-review-list {
    max-height: 260px;
  }

  .ops-output-review-player {
    min-height: 420px;
  }

  .ops-output-review-player video {
    height: min(58vh, 540px);
  }
}

@media (max-width: 700px) {
  .ops-output-review-summary__head {
    align-items: flex-start;
  }

  .ops-output-review-summary__intro {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.14rem;
  }

  .ops-output-review-summary__metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ops-output-review-command-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .ops-output-review-command-bar__navigation {
    justify-content: flex-end;
  }
}

@media (max-width: 520px) {
  .ops-output-review-summary__head {
    flex-direction: column;
    gap: 0.35rem;
  }

  .ops-output-review-summary__metrics {
    grid-template-columns: 1fr;
  }

  .ops-output-review-row {
    grid-template-columns: 1.35rem minmax(0, 1fr);
  }

  .ops-output-review-row .ops-output-review-badge {
    grid-column: 2;
    justify-self: start;
  }

  .ops-output-review-player {
    min-height: 360px;
  }
}

/* Output Review polish ? same workstation layout, clearer hierarchy and honest data visuals. */
.ops-output-review-page {
  --output-review-accent: #1d5f89;
  --output-review-border: #d7e2ec;
  gap: 0.9rem;
  padding-bottom: 1.4rem;
  padding-top: 0.95rem;
}

.ops-output-review-eyebrow {
  color: #667d91;
  font-size: 0.75rem;
  font-weight: 780;
}

.ops-output-review-summary {
  background:
    radial-gradient(circle at 92% 0%, rgba(57, 132, 174, 0.12), transparent 30%),
    linear-gradient(145deg, #fcfeff 0%, #f2f7fa 100%);
  border: 1px solid var(--output-review-border);
  border-radius: 18px;
  box-shadow: 0 14px 34px rgba(30, 64, 89, 0.07), inset 0 1px 0 #fff;
  gap: 0.65rem;
