}

.ops-output-review-summary__freshness strong {
  background: #fff7e8;
  border: 1px solid #ead9b5;
  border-radius: 999px;
  color: #866a34;
  font-size: 0.75rem;
  font-weight: 720;
  padding: 0.18rem 0.42rem;
}

.ops-output-review-summary-card {
  background: rgba(255, 255, 255, 0.9);
  border-color: #d9e3ec;
  border-radius: 13px;
  box-shadow: 0 5px 16px rgba(15, 35, 52, 0.045), inset 0 1px 0 #fff;
  min-height: 94px;
  padding: 0.72rem 0.82rem 0.68rem;
}

.ops-output-review-summary-card.tone-danger {
