}

.ops-output-review-summary-card.tone-warning {
  background: linear-gradient(145deg, #fff 10%, #fff8e9 100%);
}

.ops-output-review-summary-card.tone-positive {
  background: linear-gradient(145deg, #fff 10%, #eff9f4 100%);
}

.ops-output-review-summary-card dt {
  font-size: 0.74rem;
  font-weight: 690;
}

.ops-output-review-summary-card__icon {
