/* Output Review QA Pulse ? one decision surface instead of four equal KPI cards. */
.ops-output-review-pulse__body {
  background: #f4f8fa;
  border: 1px solid #d6e1e5;
  border-radius: 15px;
  box-shadow: 0 10px 24px rgba(25, 45, 60, 0.065), inset 0 1px 0 #fff;
  display: block;
  min-width: 0;
  overflow: hidden;
}

/* Output Review QA Command Deck ? compact signal + chart composition. */
.ops-output-review-pulse__deck {
  --deck-signal: #718695;
  --deck-signal-soft: rgba(113, 134, 149, 0.2);
  display: grid;
  gap: 0.5rem;
  grid-template-columns: minmax(240px, 0.32fr) minmax(0, 1.68fr);
  min-height: 178px;
  overflow: hidden;
  padding: 0.48rem;
}

.ops-output-review-pulse__deck.tone-danger {
  --deck-signal: #ee7180;
  --deck-signal-soft: rgba(238, 113, 128, 0.2);
}

.ops-output-review-pulse__deck.tone-warning {
  --deck-signal: #e0ae53;
  --deck-signal-soft: rgba(224, 174, 83, 0.2);
}

.ops-output-review-pulse__deck.tone-pending {
  --deck-signal: #89a9bd;
  --deck-signal-soft: rgba(137, 169, 189, 0.2);
}

.ops-output-review-pulse__deck.tone-clear {
  --deck-signal: #68b58f;
  --deck-signal-soft: rgba(104, 181, 143, 0.2);
}

.ops-output-review-pulse__deck-signal {
  background:
    radial-gradient(circle at 100% 0%, var(--deck-signal-soft), transparent 48%),
    linear-gradient(150deg, #254355 0%, #173347 100%);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  box-shadow: 0 8px 20px rgba(24, 54, 73, 0.16);
  color: #fff;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  padding: 0.86rem 0.95rem 0.78rem;
  position: relative;
}

.ops-output-review-pulse__deck-signal::after {
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 50%;
  content: "";
  height: 9rem;
  pointer-events: none;
  position: absolute;
  right: -4.7rem;
  top: -4.9rem;
  width: 9rem;
}

.ops-output-review-pulse__deck-signal > header {
  align-items: center;
  color: #b9c9d2;
  display: flex;
  font-size: 0.75rem;
  font-weight: 780;
  gap: 0.48rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.ops-output-review-pulse__deck-mark {
  align-items: center;
  background: var(--deck-signal-soft);
  border: 1px solid color-mix(in srgb, var(--deck-signal) 54%, transparent);
  border-radius: 9px;
