@media (max-width: 960px) {
  .ops-output-review-pulse__body {
    grid-template-areas:
      "attention map"
      "distribution distribution";
    grid-template-columns: minmax(210px, 0.9fr) minmax(180px, 0.78fr);
  }

  .ops-output-review-pulse__tile-summary {
    grid-template-columns: minmax(145px, 0.72fr) minmax(0, 1.28fr);
  }

  .ops-output-review-pulse__focus,
  .ops-output-review-pulse__tile-map {
    border-bottom: 1px solid #dde4e8;
  }

  .ops-output-review-pulse__tile-map {
    border-right: 0;
  }
}

@media (max-width: 760px) {
  .ops-output-review-pulse__body {
    grid-template-areas:
      "attention"
      "map"
      "distribution";
    grid-template-columns: 1fr;
  }

  .ops-output-review-pulse__focus {
    border-bottom: 1px solid #dde4e8;
    border-right: 0;
    min-height: 128px;
  }

  .ops-output-review-pulse__distribution {
    grid-column: auto;
  }

  .ops-output-review-pulse__tile-grid {
    margin-block: 0.58rem;
  }
}

@media (max-width: 560px) {
  .ops-output-review-pulse__tile-summary {
    grid-template-columns: 1fr;
  }

  .ops-output-review-pulse__tile-rate {
    border-bottom: 1px solid #e1e7ea;
    border-right: 0;
    padding: 0.62rem 0.1rem;
  }

  .ops-output-review-pulse__tile-legend {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: repeat(2, minmax(0, 1fr));
  }

  .ops-output-review-pulse__tile-legend > div + div {
    border-top: 0;
  }

  .ops-output-review-pulse__tile-legend > div:nth-child(2n) {
    border-left: 1px solid #e8edef;
  }

  .ops-output-review-pulse__tile-legend > div:nth-child(n + 3) {
    border-top: 1px solid #e8edef;
  }
}


