}

.ops-home-v4-pulse {
  --pulse-color: #16a34a;
  align-items: center;
  background:
    radial-gradient(circle at 12% 25%, color-mix(in srgb, var(--pulse-color) 15%, transparent), transparent 30%),
    linear-gradient(120deg, #0f1d27, #172b34 54%, #102a27);
  border: 1px solid color-mix(in srgb, var(--pulse-color) 25%, #334155);
  border-radius: 22px;
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.16);
  color: #f8fafc;
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(260px, 1fr) minmax(430px, 1.35fr) auto;
  min-height: 132px;
  overflow: hidden;
  padding: 20px 22px;
  position: relative;
}

.ops-home-v4-pulse.is-blocked { --pulse-color: #ef4444; }
.ops-home-v4-pulse.is-needs_attention { --pulse-color: #f59e0b; }
.ops-home-v4-pulse.is-quiet { --pulse-color: #94a3b8; }

.ops-home-v4-pulse::after {
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--pulse-color) 32%, transparent), transparent);
  content: "";
  height: 1px;
  left: -20%;
  position: absolute;
  top: 0;
  width: 45%;
  animation: ops-home-v4-scan 4.8s ease-in-out infinite;
}

