  color: color-mix(in srgb, var(--pulse-color) 76%, #fff);
  display: block;
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.11em;
  margin-bottom: 0.25rem;
  text-transform: uppercase;
}
