  font-size: clamp(1.05rem, 1.55vw, 1.42rem);
  letter-spacing: -0.025em;
  line-height: 1.15;
  margin: 0;
}

.ops-home-v4-pulse__orb {
  align-items: center;
  background: color-mix(in srgb, var(--pulse-color) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--pulse-color) 44%, transparent);
  border-radius: 999px;
  display: inline-flex;
  flex: 0 0 auto;
  height: 54px;
  justify-content: center;
  width: 54px;
}
