  background: var(--pulse-color);
  border-radius: 999px;
  box-shadow: 0 0 0 7px color-mix(in srgb, var(--pulse-color) 15%, transparent), 0 0 24px color-mix(in srgb, var(--pulse-color) 60%, transparent);
  height: 12px;
  width: 12px;
  animation: ops-home-v4-pulse 1.8s ease-in-out infinite;
}

.ops-home-v4-pulse__metrics {
  align-items: stretch;
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(4, minmax(90px, 1fr));
}
.ops-home-v4-pulse__metrics > a {
  align-items: center;
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 13px;
  color: inherit;
  display: flex;
  gap: 9px;
