.ops-home-v4-glyph {
  align-items: center;
  background: color-mix(in srgb, currentColor 9%, transparent);
  border-radius: 9px;
  color: #71909e;
  display: inline-flex;
  flex: 0 0 auto;
  height: 30px;
  justify-content: center;
  width: 30px;
}
.ops-home-v4-glyph svg { height: 18px; width: 18px; }

.ops-home-v4-topology {
  align-items: center;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #dde5ea;
  border-radius: 17px;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.045);
  display: flex;
  padding: 10px 12px;
}
.ops-home-v4-topology__unit { align-items: center; display: flex; flex: 1 1 0; min-width: 0; }
.ops-home-v4-node {
  align-items: center;
  border-radius: 12px;
  color: inherit;
  display: grid;
  gap: 9px;
  grid-template-columns: 30px minmax(0, 1fr) 8px;
  min-width: 0;
  padding: 8px 9px;
  position: relative;
  text-decoration: none;
  transition: background 140ms ease, transform 140ms ease;
  width: 100%;
}
.ops-home-v4-node:hover { background: #f4f7f8; transform: translateY(-1px); }
.ops-home-v4-node > span { display: grid; min-width: 0; }
.ops-home-v4-node strong { font-size: 0.72rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ops-home-v4-node small { color: #84929f; font-size: 0.58rem; }
.ops-home-v4-node > i { background: #94a3b8; border-radius: 999px; box-shadow: 0 0 0 4px rgba(148, 163, 184, 0.12); height: 7px; width: 7px; }
.ops-home-v4-node.is-ready > i,
.ops-home-v4-node.is-active > i { background: #22a06b; box-shadow: 0 0 0 4px rgba(34, 160, 107, 0.12); }
.ops-home-v4-node.is-warning > i { background: #e99b22; box-shadow: 0 0 0 4px rgba(233, 155, 34, 0.13); }
.ops-home-v4-node.is-critical > i { background: #df4b4b; box-shadow: 0 0 0 4px rgba(223, 75, 75, 0.13); }
.ops-home-v4-node.is-quiet > i { background: #94a3b8; }
.ops-home-v4-node.is-active > i { animation: ops-home-v4-node-pulse 1.7s ease-in-out infinite; }
.ops-home-v4-topology__flow { align-items: center; display: flex; flex: 0 0 24px; justify-content: center; }
.ops-home-v4-topology__flow::before { background: #d6e0e5; content: ""; height: 1px; width: 100%; }
.ops-home-v4-topology__flow b { background: #8ba3ad; border-radius: 999px; height: 4px; margin-left: -50%; position: relative; width: 4px; animation: ops-home-v4-flow 2.4s linear infinite; }

.ops-home-v4-primary-grid,
.ops-home-v4-outcome-grid,
.ops-home-v4-diagnostic-grid { display: grid; gap: 14px; }
.ops-home-v4-primary-grid { grid-template-columns: minmax(310px, 0.78fr) minmax(520px, 1.42fr); }
.ops-home-v4-outcome-grid { grid-template-columns: minmax(500px, 1.25fr) minmax(320px, 0.75fr); }
.ops-home-v4-diagnostic-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.ops-home-v4-panel {
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid #dde5ea;
  border-radius: 17px;
  box-shadow: 0 9px 24px rgba(15, 23, 42, 0.048);
  min-width: 0;
  overflow: hidden;
}
.ops-home-v4-panel__head {
  align-items: center;
  border-bottom: 1px solid #e8edf0;
  display: flex;
  justify-content: space-between;
  min-height: 48px;
  padding: 0 14px;
}
.ops-home-v4-panel__head h2 { font-size: 0.82rem; letter-spacing: -0.01em; margin: 0; }
.ops-home-v4-panel__link { color: #517080; font-size: 0.65rem; font-weight: 750; text-decoration: none; }
.ops-home-v4-panel__link:hover { color: var(--accent); }
.ops-home-v4-panel__body { min-height: 0; padding: 12px; }

.ops-home-v4-actions { display: grid; gap: 7px; }
.ops-home-v4-action {
  align-items: center;
  background: #f8fafb;
  border: 1px solid #e4eaee;
  border-left: 3px solid #94a3b8;
  border-radius: 12px;
  color: inherit;
  display: grid;
  gap: 9px;
  grid-template-columns: 30px minmax(0, 1fr) auto 16px;
  padding: 9px 10px;
  text-decoration: none;
  transition: background 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}
.ops-home-v4-action:hover { background: #fff; box-shadow: 0 8px 18px rgba(15, 23, 42, 0.07); transform: translateY(-1px); }
.ops-home-v4-action.is-critical { border-left-color: #df4b4b; }
.ops-home-v4-action.is-warning { border-left-color: #e99b22; }
.ops-home-v4-action.is-info { border-left-color: #3b82f6; }
.ops-home-v4-action > span { display: grid; min-width: 0; }
.ops-home-v4-action em { color: #8795a1; font-size: 0.56rem; font-style: normal; font-weight: 760; text-transform: uppercase; }
.ops-home-v4-action strong { font-size: 0.7rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ops-home-v4-action > b { font-size: 0.9rem; font-variant-numeric: tabular-nums; }
.ops-home-v4-actions__more { color: #8a98a4; font-size: 0.61rem; padding: 2px 4px 0; text-align: center; }

.ops-home-v4-clear { align-items: center; color: #73838f; display: flex; flex-direction: column; justify-content: center; min-height: 190px; text-align: center; }
.ops-home-v4-clear.is-compact { min-height: 130px; }
.ops-home-v4-clear > span { align-items: center; background: #dcfce7; border-radius: 999px; color: #168454; display: inline-flex; font-size: 1rem; height: 36px; justify-content: center; margin-bottom: 7px; width: 36px; }
.ops-home-v4-clear strong { color: #334155; font-size: 0.76rem; }
.ops-home-v4-clear small { font-size: 0.63rem; margin-top: 2px; }

.ops-home-v4-workload { display: grid; gap: 7px; }
.ops-home-v4-workload__legend { display: flex; flex-wrap: wrap; gap: 10px; justify-content: flex-end; margin-bottom: 2px; }
.ops-home-v4-workload__legend span { align-items: center; color: #7c8b97; display: inline-flex; font-size: 0.57rem; gap: 4px; }
.ops-home-v4-workload__legend span::before { background: #cbd5e1; border-radius: 999px; content: ""; height: 6px; width: 6px; }
.ops-home-v4-workload__legend .is-running::before { background: #38bdf8; }
.ops-home-v4-workload__legend .is-review::before { background: #a78bfa; }
.ops-home-v4-workload__legend .is-retryable::before { background: #fbbf24; }
.ops-home-v4-workload__legend .is-failed::before { background: #fb7185; }
.ops-home-v4-lane { align-items: center; border-radius: 10px; color: inherit; display: grid; gap: 10px; grid-template-columns: minmax(140px, 0.72fr) minmax(190px, 1.6fr) 28px; min-height: 38px; padding: 5px 7px; text-decoration: none; transition: background 140ms ease; }
.ops-home-v4-lane:hover { background: #f5f8f9; }
.ops-home-v4-lane__label { display: grid; min-width: 0; }
.ops-home-v4-lane__label strong { font-size: 0.67rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ops-home-v4-lane__label small { color: #8a98a4; font-size: 0.56rem; }
.ops-home-v4-lane__track { background: #eef2f4; border-radius: 999px; display: flex; height: 11px; min-width: 0; overflow: hidden; }
.ops-home-v4-lane__track > i { min-width: 3px; }
.ops-home-v4-lane__track .is-queued { background: #cbd5e1; }
.ops-home-v4-lane__track .is-running { background: #38bdf8; }
.ops-home-v4-lane__track .is-review { background: #a78bfa; }
.ops-home-v4-lane__track .is-retryable { background: #fbbf24; }
.ops-home-v4-lane__track .is-failed { background: #fb7185; }
.ops-home-v4-lane__track .is-completed { background: #bbf7d0; flex: 1; opacity: 0.55; }
.ops-home-v4-lane__attention { text-align: center; }
.ops-home-v4-lane__attention b { align-items: center; background: #fff1f2; border-radius: 999px; color: #be123c; display: inline-flex; font-size: 0.62rem; height: 22px; justify-content: center; min-width: 22px; }
.ops-home-v4-lane__attention i { color: #22a06b; font-size: 0.7rem; font-style: normal; }

.ops-home-v4-publish { align-items: center; display: grid; gap: 18px; grid-template-columns: 112px minmax(0, 1fr); min-height: 205px; }
.ops-home-v4-ring { align-items: center; border-radius: 999px; display: flex; height: 104px; justify-content: center; margin: auto; position: relative; width: 104px; }
.ops-home-v4-ring::before { background: #fff; border-radius: inherit; box-shadow: inset 0 0 0 1px #e5eaed; content: ""; inset: 10px; position: absolute; }
.ops-home-v4-ring > span { display: grid; position: relative; text-align: center; z-index: 1; }
.ops-home-v4-ring strong { font-size: 1.18rem; }
.ops-home-v4-ring small { color: #7b8994; font-size: 0.58rem; }
.ops-home-v4-publish__chart { display: grid; gap: 12px; min-width: 0; }
.ops-home-v4-publish__summary { display: flex; flex-wrap: wrap; gap: 12px; }
.ops-home-v4-publish__summary span { color: #7a8995; font-size: 0.61rem; }
.ops-home-v4-publish__summary b { color: #334155; font-size: 0.75rem; }
.ops-home-v4-publish__summary .is-good b { color: #168454; }
.ops-home-v4-publish__summary .is-danger b { color: #c24152; }
.ops-home-v4-bars { align-items: end; display: grid; gap: 9px; grid-template-columns: repeat(7, minmax(24px, 1fr)); height: 132px; }
.ops-home-v4-bar { align-items: center; display: flex; flex-direction: column; height: 100%; justify-content: flex-end; min-width: 0; }
.ops-home-v4-bar > i { border-radius: 6px 6px 2px 2px; display: flex; flex-direction: column; max-width: 28px; min-height: 5px; overflow: hidden; width: 68%; }
.ops-home-v4-bar b { min-height: 0; }
.ops-home-v4-bar .is-success { background: #4ade80; }
.ops-home-v4-bar .is-failed { background: #fb7185; }
.ops-home-v4-bar .is-other { background: #cbd5e1; }
.ops-home-v4-bar em { color: #84939f; font-size: 0.54rem; font-style: normal; margin-top: 5px; overflow: hidden; white-space: nowrap; }

.ops-home-v4-accounts { display: grid; gap: 10px; min-height: 205px; }
.ops-home-v4-accounts__healthy { align-items: center; background: #f0fdf4; border: 1px solid #d1fae5; border-radius: 11px; display: grid; gap: 7px; grid-template-columns: 25px auto 1fr; padding: 8px 10px; }
.ops-home-v4-accounts__healthy > span { align-items: center; background: #bbf7d0; border-radius: 999px; color: #15803d; display: inline-flex; height: 25px; justify-content: center; width: 25px; }
.ops-home-v4-accounts__healthy > strong { color: #15803d; font-size: 1rem; }
.ops-home-v4-accounts__healthy > small { color: #4f7d63; font-size: 0.63rem; }
.ops-home-v4-account-list { display: grid; gap: 6px; }
.ops-home-v4-account-list > a { align-items: center; border: 1px solid #e4eaee; border-radius: 11px; color: inherit; display: grid; gap: 8px; grid-template-columns: 30px minmax(0, 1fr) auto 16px; padding: 8px; text-decoration: none; }
.ops-home-v4-account-list > a:hover { background: #f8fafb; }
.ops-home-v4-account-list > a > span { display: grid; min-width: 0; }
.ops-home-v4-account-list strong { font-size: 0.68rem; }
.ops-home-v4-account-list small { color: #84929e; font-size: 0.56rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ops-home-v4-account-list em { background: #fff7ed; border-radius: 999px; color: #b45309; font-size: 0.55rem; font-style: normal; font-weight: 750; padding: 4px 6px; }

.ops-home-v4-pareto { display: grid; gap: 9px; min-height: 170px; }
.ops-home-v4-pareto > a { align-items: center; color: inherit; display: grid; gap: 10px; grid-template-columns: minmax(130px, 0.85fr) minmax(120px, 1.6fr) 28px; text-decoration: none; }
.ops-home-v4-pareto > a > span { display: grid; min-width: 0; }
.ops-home-v4-pareto em { color: #8b99a5; font-size: 0.53rem; font-style: normal; text-transform: uppercase; }
.ops-home-v4-pareto span strong { font-size: 0.65rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ops-home-v4-pareto > a > i { background: #eef2f4; border-radius: 999px; height: 9px; overflow: hidden; }
.ops-home-v4-pareto > a > i > b { background: linear-gradient(90deg, #fb7185, #f59e0b); border-radius: inherit; display: block; height: 100%; transition: width 240ms ease; }
.ops-home-v4-pareto > a > strong { font-size: 0.68rem; text-align: right; }

.ops-home-v4-fetch { align-items: center; display: grid; gap: 16px; grid-template-columns: 112px minmax(170px, 1fr); min-height: 170px; }
.ops-home-v4-fetch__accounts { display: grid; gap: 9px; }
.ops-home-v4-fetch__accounts > span { align-items: center; display: grid; gap: 8px; grid-template-columns: 72px minmax(70px, 1fr) 32px; }
.ops-home-v4-fetch__accounts em { color: #5e7180; font-family: var(--font-mono, monospace); font-size: 0.57rem; font-style: normal; overflow: hidden; text-overflow: ellipsis; }
.ops-home-v4-fetch__accounts i { background: #eef2f4; border-radius: 999px; height: 8px; overflow: hidden; }
.ops-home-v4-fetch__accounts i b { background: #f59e0b; border-radius: inherit; display: block; height: 100%; }
.ops-home-v4-fetch__accounts strong { font-size: 0.62rem; text-align: right; }
.ops-home-v4-fetch__reasons { display: flex; flex-wrap: wrap; gap: 5px; grid-column: 1 / -1; }
.ops-home-v4-fetch__reasons span { background: #fff7ed; border: 1px solid #fed7aa; border-radius: 999px; color: #9a6223; font-size: 0.55rem; padding: 4px 7px; }

@keyframes ops-home-v4-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.62; transform: scale(0.82); }
}
@keyframes ops-home-v4-node-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
@keyframes ops-home-v4-flow {
  from { transform: translateX(-9px); }
  to { transform: translateX(9px); }
}
@keyframes ops-home-v4-scan {
  0%, 16% { transform: translateX(0); opacity: 0; }
  30% { opacity: 1; }
  70% { opacity: 1; }
  84%, 100% { transform: translateX(280%); opacity: 0; }
}

@media (max-width: 1280px) {
  .ops-home-v4-pulse { grid-template-columns: minmax(240px, 0.8fr) minmax(420px, 1.4fr); }
  .ops-home-v4-pulse > time { grid-column: 1 / -1; justify-self: start; }
  .ops-home-v4-primary-grid,
  .ops-home-v4-outcome-grid { grid-template-columns: 1fr; }
}

@media (max-width: 920px) {
  .ops-home-v4-pulse { grid-template-columns: 1fr; }
  .ops-home-v4-pulse__metrics { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .ops-home-v4-topology { align-items: stretch; display: grid; gap: 6px; grid-template-columns: repeat(5, minmax(0, 1fr)); }
  .ops-home-v4-topology__unit { display: block; }
  .ops-home-v4-topology__flow { display: none; }
  .ops-home-v4-node { gap: 5px; grid-template-columns: 1fr; justify-items: center; text-align: center; }
  .ops-home-v4-node > i { position: absolute; transform: translate(16px, -9px); }
  .ops-home-v4-diagnostic-grid { grid-template-columns: 1fr; }
}

@media (max-width: 640px) {
  .ops-home-v4 { gap: 10px; padding: 10px var(--app-content-inset-x) 22px; }
  .ops-home-v4-pulse { border-radius: 17px; padding: 16px; }
  .ops-home-v4-pulse__metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ops-home-v4-topology { grid-template-columns: repeat(5, minmax(62px, 1fr)); overflow-x: auto; }
  .ops-home-v4-node strong { font-size: 0.62rem; }
  .ops-home-v4-panel { border-radius: 14px; }
  .ops-home-v4-lane { grid-template-columns: minmax(105px, 0.8fr) minmax(110px, 1.2fr) 25px; }
  .ops-home-v4-workload__legend { justify-content: flex-start; }
  .ops-home-v4-publish { grid-template-columns: 1fr; }
  .ops-home-v4-pareto > a { grid-template-columns: minmax(96px, 0.8fr) minmax(90px, 1.2fr) 24px; }
  .ops-home-v4-fetch { grid-template-columns: 1fr; }
  .ops-home-v4-fetch__reasons { grid-column: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .ops-home-v4-pulse::after,
  .ops-home-v4-pulse__orb i,
  .ops-home-v4-node.is-active > i,
  .ops-home-v4-topology__flow b { animation: none; }
  .ops-home-v4-action,
  .ops-home-v4-node,
  .ops-home-v4-pulse__metrics > a { transition: none; }
}

/* System Pulse polish: stronger hierarchy, richer signal deck, readable sync state. */
.ops-home-v4 .ops-home-v4-pulse {
  align-items: stretch;
  background:
    linear-gradient(110deg, rgba(239, 68, 68, 0.075), transparent 30%),
    radial-gradient(circle at 76% -35%, rgba(45, 212, 191, 0.12), transparent 46%),
    linear-gradient(120deg, #171d29 0%, #12242b 56%, #0c2b26 100%);
  gap: clamp(24px, 3vw, 54px);
  grid-template-columns: minmax(360px, 0.82fr) minmax(650px, 1.3fr);
  min-height: 154px;
  padding: 22px 24px;
}

.ops-home-v4-pulse__aura {
  background: var(--pulse-color);
  border-radius: 999px;
  filter: blur(54px);
  height: 110px;
  left: -52px;
  opacity: 0.09;
  pointer-events: none;
  position: absolute;
  top: 18px;
  width: 190px;
}

.ops-home-v4 .ops-home-v4-pulse__status {
  gap: 18px;
  position: relative;
  z-index: 1;
}

.ops-home-v4 .ops-home-v4-pulse__orb {
  background:
    radial-gradient(circle, color-mix(in srgb, var(--pulse-color) 28%, transparent), transparent 66%);
  border-color: color-mix(in srgb, var(--pulse-color) 52%, transparent);
  height: 64px;
  position: relative;
  width: 64px;
}

.ops-home-v4 .ops-home-v4-pulse__orb::before,
.ops-home-v4 .ops-home-v4-pulse__orb::after {
  border: 1px solid color-mix(in srgb, var(--pulse-color) 32%, transparent);
  border-radius: inherit;
  content: "";
  inset: 8px;
  position: absolute;
}
.ops-home-v4 .ops-home-v4-pulse__orb::after { inset: 16px; opacity: 0.7; }
.ops-home-v4 .ops-home-v4-pulse__orb > i { height: 10px; position: relative; width: 10px; z-index: 2; }
.ops-home-v4 .ops-home-v4-pulse__orb > b {
  border: 1px solid color-mix(in srgb, var(--pulse-color) 40%, transparent);
  border-radius: inherit;
  inset: 5px;
  position: absolute;
  animation: ops-home-v4-radar 2.3s ease-out infinite;
}

.ops-home-v4 .ops-home-v4-pulse__status .ops-home-v4-pulse__kicker {
  align-items: center;
  color: color-mix(in srgb, var(--pulse-color) 76%, #fff);
  display: inline-flex;
  font-size: 0.64rem;
  gap: 7px;
  letter-spacing: 0.13em;
  margin-bottom: 0.4rem;
}
.ops-home-v4-pulse__kicker > i {
  background: var(--pulse-color);
  border-radius: 999px;
  box-shadow: 0 0 12px color-mix(in srgb, var(--pulse-color) 72%, transparent);
  height: 6px;
  width: 6px;
}
.ops-home-v4 .ops-home-v4-pulse__status h2 {
  font-size: clamp(1.16rem, 1.55vw, 1.52rem);
  max-width: 560px;
}

.ops-home-v4-pulse__signal-deck {
  align-content: center;
  display: grid;
  gap: 9px;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.ops-home-v4-pulse__sync {
  align-items: center;
  display: flex;
  justify-content: space-between;
  padding: 0 3px;
}
.ops-home-v4-pulse__sync > span {
  align-items: center;
  color: #79919c;
  display: inline-flex;
  font-size: 0.6rem;
  font-weight: 720;
  gap: 6px;
  letter-spacing: 0.035em;
}
.ops-home-v4-pulse__sync > span i {
  background: #34d399;
  border-radius: 999px;
  box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.1);
  height: 5px;
  width: 5px;
}
.ops-home-v4-pulse__sync time {
  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 999px;
  color: #90a3ab;
  font-size: 0.57rem;
  padding: 5px 9px;
  white-space: nowrap;
}

.ops-home-v4 .ops-home-v4-pulse__metrics {
  gap: 9px;
  grid-template-columns: repeat(4, minmax(118px, 1fr));
}
.ops-home-v4 .ops-home-v4-pulse__metrics > a {
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.035));
  border-color: rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  min-height: 64px;
  overflow: hidden;
  padding: 10px 11px;
  position: relative;
}
.ops-home-v4 .ops-home-v4-pulse__metrics > a::before {
  background: var(--signal-color, #64748b);
  content: "";
  inset: 0 auto 0 0;
  opacity: 0.72;
  position: absolute;
  width: 2px;
}
.ops-home-v4 .ops-home-v4-pulse__metrics > a.is-critical { --signal-color: #ef4444; }
.ops-home-v4 .ops-home-v4-pulse__metrics > a.is-attention { --signal-color: #f59e0b; }
