/* Transcript Editor V2 ? polished production workspace. */
.transcript-editor {
  background:
    radial-gradient(circle at 84% 8%, rgba(30, 126, 100, 0.055), transparent 26rem),
    linear-gradient(180deg, #f8fafb 0%, #f4f7f9 100%);
  color: #182635;
  padding-bottom: 72px;
}

.transcript-loading__status {
  background: #f4f8f7;
  border-color: #d8e5e1;
  color: #3f6f5f;
}

.transcript-loading__focus {
  background: #fff;
  border-color: #dce5e9;
}

.transcript-header.transcript-header--command {
  backdrop-filter: blur(14px);
  background: rgba(255, 255, 255, 0.94);
  border-bottom-color: #dbe4e8;
  box-shadow: 0 8px 24px rgba(25, 49, 62, 0.055);
  padding-block: 10px;
}

.transcript-header__bar {
  gap: 10px 14px;
  min-height: 40px;
}

.transcript-header__lead {
  gap: 8px 12px;
}

.transcript-header--command .transcript-header__back {
  background: #f9fcfb;
  border-color: #bedbd1;
  box-shadow: 0 2px 7px rgba(20, 97, 75, 0.07);
  min-height: 36px;
  padding-inline: 11px 14px;
}

.editor-command__pipeline {
  background: #f4f8f7;
  border: 1px solid #d8e5e1;
  border-radius: 999px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  flex-wrap: nowrap;
  gap: 0;
  padding: 3px 4px;
}

.editor-command__pipeline-badge {
  background: transparent;
  border-color: transparent;
  box-shadow: none;
  min-height: 30px;
  padding: 3px 9px 3px 5px;
}

.editor-command__pipeline-step.is-done .editor-command__pipeline-badge {
  background: transparent;
  border-color: transparent;
}

.editor-command__pipeline-step.is-active .editor-command__pipeline-badge {
  background: #fff;
  border-color: #bcd9cf;
  box-shadow: 0 3px 9px rgba(23, 101, 79, 0.1);
}

.editor-command__pipeline-connector {
  width: 0.8rem;
}

.editor-command__pipeline-label {
  font-size: 0.75rem;
}

.editor-command__meta {
  border-top: 1px solid #e4ece9;
  color: #5b6f68;
  margin-top: 10px;
  padding-top: 8px;
}

.editor-command__meta-kicker {
  color: #3f6f5f;
}

.transcript-header--command .editor-command {
  background: #f7f9fa;
  border: 1px solid #dce5e9;
  border-radius: 12px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9);
  gap: 3px;
  padding: 3px;
}

.transcript-header--command .editor-command__save,
.transcript-header--command .editor-command__translate,
.transcript-header--command .editor-command__tts,
.transcript-header--command .editor-command__reasr,
.transcript-header--command a.editor-command__final,
.transcript-header--command .editor-command__discard {
  border-radius: 9px;
  min-height: 34px;
  padding: 7px 11px;
}

.transcript-header--command .editor-command__quiet,
.transcript-header--command a.editor-command__quiet {
  background: transparent !important;
  border-color: transparent !important;
}

.transcript-header--command .editor-command__quiet:hover:not(:disabled),
.transcript-header--command a.editor-command__quiet:hover {
  background: #fff !important;
  border-color: #d9e3e7 !important;
  box-shadow: 0 2px 7px rgba(35, 56, 68, 0.06) !important;
}

.transcript-header--command .editor-command__primary {
  border-radius: 9px !important;
  min-height: 36px;
  padding-inline: 14px;
}

.transcript-bench {
  align-items: start;
  gap: 16px;
  grid-template-columns: minmax(340px, 420px) minmax(0, 1fr);
  padding-bottom: 28px;
  padding-top: 16px;
}

.transcript-bench__side {
  background: rgba(255, 255, 255, 0.94);
  border-color: #d8e3e8;
  border-radius: 16px;
  box-shadow: 0 12px 30px rgba(29, 53, 66, 0.075), inset 0 1px 0 #fff;
  gap: 12px;
  padding: 13px;
}

.transcript-bench-media .media-box {
  background:
    radial-gradient(circle at 50% 20%, rgba(76, 122, 145, 0.08), transparent 54%),
    #edf3f6;
  border-color: #d4e0e6;
  border-radius: 12px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.86);
  min-height: 230px;
}

.transcript-bench-media__empty {
  align-content: center;
  color: #667b8c;
  display: grid;
  font-size: 0.8125rem;
  gap: 9px;
  justify-items: center;
  line-height: 1.45;
  max-width: 20rem;
  padding: 24px 30px;
}

.transcript-bench-media__empty-icon {
  align-items: center;
  background: rgba(255, 255, 255, 0.82);
  border: 1px solid #d3e0e6;
  border-radius: 12px;
  color: #5c7d8f;
  display: inline-flex;
  height: 2.8rem;
  justify-content: center;
  width: 2.8rem;
}

.transcript-bench-media__empty-icon svg {
  height: 1.5rem;
  width: 1.5rem;
}

.transcript-bench-media__tts {
  background: #f6f9f8;
  border: 1px solid #dde8e4;
  border-radius: 11px;
  gap: 7px;
  margin-top: 9px;
  padding: 9px 10px 10px;
}

.transcript-bench-media__tts strong,
.media-now strong,
.transcript-beat-rail__label {
  color: #667b88;
  font-size: 0.75rem;
  letter-spacing: 0.055em;
}

.transcript-bench-media__tts audio {
  accent-color: var(--accent-strong);
  height: 36px;
}

.media-now {
  align-items: center;
  background: #f8fafb;
  border: 1px solid #e0e7eb;
  border-radius: 10px;
  display: grid;
  gap: 5px 10px;
  grid-template-columns: minmax(0, 1fr) auto;
  margin-top: 9px;
  padding: 8px 9px;
}

.media-now strong {
  grid-column: 1 / -1;
  width: auto;
}

.media-now p {
  color: #526a79;
  font-size: 0.8125rem;
  font-weight: 620;
}

.media-now button {
  background: #fff;
  border: 1px solid #d7e2e6;
  border-radius: 8px;
  color: var(--accent-strong);
  font-size: 0.75rem;
  font-weight: 690;
  padding: 6px 9px;
}

.media-now button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent) 7%, #fff);
  border-color: color-mix(in srgb, var(--accent) 34%, #d7e2e6);
}

.transcript-beat-rail {
  border-top: 1px solid #e3eaed;
  gap: 7px;
  padding-top: 10px;
}

.transcript-beat-rail__label {
  margin-bottom: 0;
}

.transcript-beat-rail__list {
  gap: 5px;
}

.transcript-beat-rail__item {
  background: #f7f9fa;
  border-color: #e2e9ec;
  border-radius: 10px;
  min-height: 40px;
  padding: 8px 10px;
  transition: background 140ms ease, border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
}

.transcript-beat-rail__item:hover {
  background: #fff;
  border-color: #cddde2;
  transform: translateY(-1px);
}

.transcript-beat-rail__item.is-selected {
  background: linear-gradient(100deg, #edf8f4 0%, #f8fcfa 100%);
  border-color: #9bcbbd;
  box-shadow: inset 3px 0 0 var(--accent-strong), 0 4px 12px rgba(26, 106, 82, 0.07);
}

.transcript-beat-rail__title {
  color: #203541;
  font-size: 0.8125rem;
}

.transcript-focus-editor {
  background: rgba(255, 255, 255, 0.96);
  border-color: #d7e2e7;
  border-radius: 16px;
  box-shadow: 0 14px 34px rgba(28, 52, 66, 0.075), inset 0 1px 0 #fff;
  gap: 12px;
  padding: 17px 18px 16px;
}

.transcript-focus-chrome {
  gap: 9px;
}

.transcript-focus-chrome__title {
  color: #1d2f3c;
  font-size: 1.25rem;
  font-weight: 760;
}

.transcript-focus-chrome__toolbar {
  align-items: center;
  background: linear-gradient(180deg, #f8fafb 0%, #f4f8f9 100%);
  border-color: #dce6ea;
  border-radius: 11px;
  box-shadow: inset 0 1px 0 #fff;
  gap: 9px 14px;
  padding: 8px 9px;
}

.timing-editor__range--timecode {
  border-color: #b9d6cc;
  border-radius: 9px;
  box-shadow: inset 3px 0 0 var(--accent-strong), 0 2px 6px rgba(26, 105, 81, 0.055);
}

.transcript-focus-editor__actions {
  gap: 5px;
}

.transcript-focus-chrome__toolbar .segment-ops__btn--play {
  border-radius: 9px;
  box-shadow: 0 3px 8px color-mix(in srgb, var(--accent) 18%, transparent);
}

.segment-ops__group .segment-ops__btn {
  background: rgba(255, 255, 255, 0.9);
  border-color: #dbe4e8;
}

.transcript-dual-pane {
  gap: 12px;
  min-height: min(50vh, 430px);
}

.transcript-dual-pane__zh,
.transcript-dual-pane__vi {
  border-radius: 13px;
  gap: 0;
  overflow: hidden;
  padding: 0;
}

.transcript-dual-pane__zh {
  background: linear-gradient(160deg, #f8fafc 0%, #f4f7f9 100%);
  border-color: #dbe4e9;
}

.transcript-dual-pane__vi {
  background: linear-gradient(160deg, #fff 0%, #fbfefd 100%);
  border-color: #9bcbbd;
  box-shadow: 0 6px 18px rgba(27, 110, 84, 0.065), inset 0 1px 0 #fff;
}

.transcript-dual-pane__zh > .transcript-dual-pane__tab,
.transcript-dual-pane__tab-row {
  align-items: center;
  background: rgba(255, 255, 255, 0.62);
  border-bottom: 1px solid #e1e8eb;
  display: flex;
  min-height: 42px;
  padding: 0 13px;
}

.transcript-dual-pane__vi .transcript-dual-pane__tab-row {
  background: #f4fbf8;
  border-bottom-color: #d5e9e1;
}

.transcript-dual-pane__tab-row .transcript-dual-pane__tab {
  min-height: 0;
  padding: 0;
}

.transcript-dual-pane__tab {
  color: #607684;
  font-size: 0.8125rem;
  font-weight: 720;
}

.transcript-dual-pane__tab.is-active {
  color: #205f4c;
}

.transcript-dual-pane__badge {
  background: #def5ea;
  border-color: #addbc9;
  color: #177455;
  font-size: 0.6875rem;
  padding: 3px 8px;
}

.transcript-dual-pane .source-textarea-primary,
.transcript-dual-pane .translation-textarea {
  color: #263b48;
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  font-size: 0.875rem;
  line-height: 1.7;
  min-height: 320px;
  padding: 13px 14px 15px;
}

.transcript-dual-pane__zh .source-textarea-primary {
  color: #314757;
  font-size: 0.9375rem;
  letter-spacing: 0.015em;
  line-height: 1.72;
}

.transcript-dual-pane .source-textarea-primary:focus,
.transcript-dual-pane .translation-textarea:focus {
  background: rgba(255, 255, 255, 0.72);
}

.transcript-focus-editor__dirty-hint {
  padding: 0 14px 10px;
}

.transcript-focus-secondary {
  align-items: center;
  background: #f8fafb;
  border: 1px solid #e1e8eb;
  border-radius: 10px;
  flex-direction: row;
  flex-wrap: wrap;
  gap: 7px 16px;
  margin-top: 0;
  padding: 7px 9px;
}

.transcript-focus-chrome__run > summary,
.transcript-focus-secondary .compare-machine-details > summary {
  font-size: 0.75rem;
}

@media (max-width: 1100px) {
  .transcript-bench {
    grid-template-columns: 1fr;
  }

  .transcript-bench__side {
    position: static;
  }
