/* Intelligence Data Loading Skeleton - cold load only; soft refresh keeps prior payload. */
.pl-iq-data-skeleton {
  --pl-iq-mint: #f4f8f6;
  --pl-iq-label-quiet: #6b8278;
  --pl-iq-label-strong: #2a4d41;
}

@keyframes pl-iq-skeleton-pulse {
  0%,
  100% {
    opacity: 0.55;
  }
  50% {
    opacity: 1;
  }
}

.pl-iq-data-skeleton i {
  background: linear-gradient(90deg, #e7efe9 0%, #f4f8f6 50%, #e7efe9 100%);
  background-size: 200% 100%;
  border-radius: 6px;
  display: block;
  min-height: 0.65rem;
