.opportunity-ranking-toolbar input,
.opportunity-ranking-toolbar select { background: #fff; border: 1px solid #ccdad4; border-radius: 8px; color: #29483e; font-size: .68rem; min-height: 36px; min-width: 0; padding: 0 9px; width: 100%; }
.opportunity-ranking-table-wrap { background: #fff; border: 1px solid #dce7e2; border-radius: 13px; overflow-x: auto; }
.opportunity-ranking-table-wrap > header { align-items: center; border-bottom: 1px solid #e4ebe8; display: flex; gap: 12px; justify-content: space-between; padding: 13px 15px; }
.opportunity-ranking-table-wrap > header > div { display: grid; gap: 3px; }
.opportunity-ranking-table-wrap > header strong { color: #213c34; font-size: .84rem; }
.opportunity-ranking-table-wrap > header small { color: #71847e; font-size: .63rem; }
.opportunity-ranking-table-wrap > header > span { background: #fff8e8; border-radius: 999px; color: #976419; font-size: .57rem; font-weight: 750; padding: 5px 8px; }
.opportunity-ranking-table-wrap > header > .opportunity-ranking-info-note { align-items: center; background: #f1f7fc; border: 1px solid #d4e4f0; border-radius: 9px; color: #456b82; display: flex; gap: 7px; max-width: 360px; padding: 7px 9px; }
