.ops-accounts-safety-controls .ops-accounts-consent {
  align-items: center;
  background: #fff;
  border-color: #d6e3dd;
  cursor: pointer;
  display: grid;
  gap: 9px;
  grid-column: 1 / -1;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 54px;
  padding: 8px 10px;
