.ops-accounts-safety-controls .ops-accounts-consent input[type="checkbox"] {
  appearance: none;
  background: #dbe5e1;
  border: 1px solid #bdcec6;
  border-radius: 999px;
  cursor: pointer;
  height: 20px;
  margin: 0;
  position: relative;
  transition: background 150ms ease, border-color 150ms ease;
  width: 36px;
}

.ops-accounts-safety-controls .ops-accounts-consent input[type="checkbox"]::after {
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 3px rgba(21, 55, 43, 0.2);
  content: "";
  height: 14px;
  left: 2px;
  position: absolute;
  top: 2px;
  transition: transform 150ms ease;
  width: 14px;
