}

.ops-accounts-safety-controls > label.is-cooldown {
  grid-column: 2;
}

.ops-accounts-safety-controls input:not([type="checkbox"]) {
  background: #fff;
  border: 1px solid #c8d9d1;
  border-radius: 8px;
  color: #193d31;
  font-size: 0.75rem;
  min-height: 2.1rem;
}

.ops-accounts-safety-controls input:not([type="checkbox"]):focus {
  border-color: #4d9a7a;
  box-shadow: 0 0 0 3px rgba(55, 143, 109, 0.1);
  outline: 0;
}

.ops-accounts-safety-actions {
  align-items: center;
  background: #f3f8f5;
