  gap: 0.4rem;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  min-height: 1.85rem;
  padding: 0.26rem 0.42rem;
  text-align: left;
  transition: background 140ms ease, border-color 140ms ease, box-shadow 140ms ease;
  width: 100%;
}

.export-packages-page.is-v4 span.export-packages-mix__legend-item {
  cursor: default;
}

.export-packages-page.is-v4 .export-packages-mix__legend-item:is(button):hover {
  background: color-mix(in srgb, var(--pl-iq-mint) 55%, #fff);
}

.export-packages-page.is-v4 .export-packages-mix__legend-item > i {
  background: currentColor;
  border-radius: 999px;
  display: block;
  height: 0.55rem;
  width: 0.55rem;
}

.export-packages-page.is-v4 .export-packages-mix__legend-item > span {
  color: inherit;
  font-size: 0.64rem;
  font-weight: 650;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.export-packages-page.is-v4 .export-packages-mix__legend-item > em {
  color: var(--pl-iq-label-quiet);
  font-size: 0.58rem;
  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-weight: 650;
}

.export-packages-page.is-v4 .export-packages-mix__legend-item > b {
  color: var(--pl-iq-label-strong);
  font-size: 0.76rem;
  font-variant-numeric: tabular-nums;
  font-weight: 760;
  letter-spacing: -0.02em;
  min-width: 1.35rem;
  text-align: right;
}

.export-packages-page.is-v4 .export-packages-mix__legend-item.is-draft { color: color-mix(in srgb, var(--ep-stage-draft) 78%, #2a4d41); }
.export-packages-page.is-v4 .export-packages-mix__legend-item.is-ready { color: var(--ep-stage-ready); }
.export-packages-page.is-v4 .export-packages-mix__legend-item.is-handed { color: var(--ep-stage-handed); }
.export-packages-page.is-v4 .export-packages-mix__legend-item.is-attention { color: #a56a12; }
.export-packages-page.is-v4 .export-packages-mix__legend-item.is-empty { opacity: 0.58; }
.export-packages-page.is-v4 .export-packages-mix__legend-item.is-warning > b { color: #91600c; }

.export-packages-page.is-v4 .export-packages-mix__legend-item.is-current {
  border-color: color-mix(in srgb, #2f8f6f 42%, #e2ece7);
  box-shadow: 0 0 0 1px color-mix(in srgb, #2f8f6f 14%, transparent);
}

.export-packages-page.is-v4 .export-packages-mix__legend-item.is-attention.is-current {
  border-color: color-mix(in srgb, #c4841a 45%, #e2ece7);
  box-shadow: 0 0 0 1px color-mix(in srgb, #c4841a 14%, transparent);
}

.export-packages-page.is-v4 .export-packages-dock {
  display: grid;
  gap: 0.55rem;
  min-width: 0;
  padding: 0.85rem 0.9rem 0.95rem;
}

.export-packages-page.is-v4 .export-packages-attention {
  align-items: center;
  background: color-mix(in srgb, #fff0c7 52%, #fff);
  border: 1px dashed color-mix(in srgb, #edd7a8 70%, #e2ece7);
  border-radius: 10px;
  display: grid;
  gap: 0.2rem 0.75rem;
  grid-template-columns: auto auto 1fr auto;
  padding: 0.5rem 0.65rem;
}

.export-packages-page.is-v4 .export-packages-attention strong {
  color: #91600c;
  font-size: 0.7rem;
  font-weight: 720;
}

.export-packages-page.is-v4 .export-packages-attention > span {
  color: #91600c;
  font-size: 0.7rem;
  font-variant-numeric: tabular-nums;
  font-weight: 760;
}

.export-packages-page.is-v4 .export-packages-attention p {
  color: #91600c;
  font-size: 0.6rem;
  margin: 0;
  opacity: 0.85;
}

.export-packages-page.is-v4 .export-packages-attention__jump {
  background: #fff;
  border: 1px solid color-mix(in srgb, #c4841a 35%, #e2ece7);
  border-radius: 7px;
  color: #91600c;
  cursor: pointer;
  font: inherit;
  font-size: 0.6rem;
  font-weight: 700;
  min-height: 1.5rem;
  padding: 0.18rem 0.48rem;
}

.export-packages-page.is-v4 .export-packages-manifest {
  display: grid;
  gap: 0.35rem;
  list-style: none;
  margin: 0;
  min-width: 0;
  padding: 0;
}

.export-packages-page.is-v4 .export-packages-manifest__slip {
  --ep-slip-edge: var(--ep-stage-draft);
  align-items: center;
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--ep-slip-edge) 10%, #fff) 0%, #fff 42%);
  border: 1px dashed color-mix(in srgb, var(--ep-slip-edge) 28%, #d5e0da);
  border-radius: 10px;
  color: inherit;
  display: grid;
  gap: 0.55rem 0.75rem;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  min-width: 0;
  padding: 0.42rem 0.5rem 0.42rem 0.55rem;
  text-decoration: none;
  transition: background 140ms ease, border-color 140ms ease;
}

.export-packages-page.is-v4 .export-packages-manifest__slip:hover {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--ep-slip-edge) 14%, #fff) 0%, color-mix(in srgb, var(--pl-iq-mint) 40%, #fff) 100%);
  border-color: color-mix(in srgb, var(--ep-slip-edge) 35%, #d5e0da);
}

.export-packages-page.is-v4 .export-packages-manifest__slip.is-draft { --ep-slip-edge: var(--ep-stage-draft); }
.export-packages-page.is-v4 .export-packages-manifest__slip.is-ready { --ep-slip-edge: var(--ep-stage-ready); }
.export-packages-page.is-v4 .export-packages-manifest__slip.is-handed { --ep-slip-edge: var(--ep-stage-handed); }
.export-packages-page.is-v4 .export-packages-manifest__slip.is-attention {
  --ep-slip-edge: var(--ep-stage-attention);
  background: color-mix(in srgb, #fff0c7 42%, #fff);
  border-color: color-mix(in srgb, #edd7a8 55%, #d5e0da);
}
.export-packages-page.is-v4 .export-packages-manifest__slip.is-cancelled {
  --ep-slip-edge: #9aaba3;
  opacity: 0.88;
}

.export-packages-page.is-v4 .export-packages-manifest__stamp {
  background:
    repeating-linear-gradient(
      -28deg,
      color-mix(in srgb, var(--ep-slip-edge) 28%, transparent),
      color-mix(in srgb, var(--ep-slip-edge) 28%, transparent) 1px,
      transparent 1px,
      transparent 4px
    );
  border: 1px solid color-mix(in srgb, var(--ep-slip-edge) 40%, #d5e0da);
  border-radius: 4px;
  flex: 0 0 auto;
  height: 1.55rem;
  width: 1.15rem;
}

.export-packages-page.is-v4 .export-packages-manifest__identity {
  display: grid;
  gap: 0.12rem;
  min-width: 0;
}

.export-packages-page.is-v4 .export-packages-manifest__title {
  color: var(--pl-iq-label-strong);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.export-packages-page.is-v4 .export-packages-manifest__meta {
  color: var(--pl-iq-label-quiet);
  display: flex;
  flex-wrap: wrap;
  font-size: 0.6rem;
  gap: 0.28rem;
  margin: 0;
}

.export-packages-page.is-v4 .export-packages-manifest__seals {
  align-items: center;
  display: inline-flex;
  gap: 0.18rem;
}

.export-packages-page.is-v4 .export-packages-manifest__seals > i {
  background: color-mix(in srgb, var(--ep-slip-edge) 55%, #fff);
  border: 1px solid color-mix(in srgb, var(--ep-slip-edge) 35%, #d5e0da);
  border-radius: 999px;
  display: block;
  height: 0.42rem;
  width: 0.42rem;
}

.export-packages-page.is-v4 .export-packages-manifest__seals > em {
  color: var(--pl-iq-label-quiet);
  font-size: 0.56rem;
  font-style: normal;
  font-weight: 650;
}

.export-packages-page.is-v4 .export-packages-manifest__signal {
  align-items: center;
  display: inline-flex;
  flex-wrap: wrap;
  gap: 0.28rem;
  justify-content: flex-end;
}

.export-packages-page.is-v4 .export-packages-manifest__open {
  align-items: center;
  color: var(--pl-iq-label-quiet);
  display: inline-flex;
  opacity: 0.7;
}

.export-packages-page.is-v4 .export-packages-manifest__slip:hover .export-packages-manifest__open {
  color: var(--pl-iq-label-strong);
  opacity: 1;
}

.export-packages-page.is-v4 .export-packages-manifest__open-icon {
  display: block;
  height: 0.9rem;
  width: 0.9rem;
}

.export-packages-page.is-v4 .export-packages-chip {
  align-items: center;
  border-radius: 999px;
  display: inline-flex;
  font-size: 0.62rem;
  font-weight: 400;
  justify-content: center;
  max-width: 100%;
  overflow: hidden;
  padding: 0.18rem 0.45rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.export-packages-page.is-v4 .export-packages-chip.tone-good {
  background: #daf4e5;
  color: #14734f;
}

.export-packages-page.is-v4 .export-packages-chip.tone-warn {
  background: #fff0c7;
  color: #91600c;
}

.export-packages-page.is-v4 .export-packages-chip.tone-bad,
.export-packages-page.is-v4 .export-packages-chip.tone-danger {
  background: #fde5e2;
  color: #ac4337;
}

.export-packages-page.is-v4 .export-packages-chip.tone-muted,
.export-packages-page.is-v4 .export-packages-chip.tone-neutral {
  background: #edf0ef;
  color: #60746b;
}

.export-packages-page.is-v4 .export-packages-chip.is-draft {
  background: color-mix(in srgb, var(--ep-stage-draft) 16%, #fff);
  color: color-mix(in srgb, var(--ep-stage-draft) 72%, #2a4d41);
}

.export-packages-page.is-v4 .export-packages-chip.is-ready {
  background: color-mix(in srgb, var(--ep-stage-ready) 16%, #fff);
  color: var(--ep-stage-ready);
}

.export-packages-page.is-v4 .export-packages-chip.is-handed {
  background: color-mix(in srgb, var(--ep-stage-handed) 16%, #fff);
  color: var(--ep-stage-handed);
}

.export-packages-page.is-v4 .export-packages-chip.is-attention {
  background: color-mix(in srgb, var(--ep-stage-attention) 18%, #fff);
  color: #91600c;
}

.export-packages-page.is-v4 .export-packages-chip.is-cancelled {
  background: #edf0ef;
  color: #60746b;
}

.export-packages-page.is-v4 .export-packages-empty {
  background: color-mix(in srgb, var(--pl-iq-mint) 45%, #fff);
  border: 1px dashed #d5e0da;
  border-radius: 10px;
  color: var(--pl-iq-label-quiet);
  padding: 1rem 0.85rem;
}

.export-packages-page.is-v4 .export-packages-empty > strong {
  color: var(--pl-iq-label-strong);
  font-size: 0.78rem;
  font-weight: 700;
}

.export-packages-page.is-v4 .export-packages-footnote {
  color: #8a9a93;
  font-size: 0.6rem;
  line-height: 1.4;
  margin: 0.1rem 0 0;
}

.export-packages-page.is-v4 .export-packages-dock .ops-state {
  margin: 0.35rem 0;
}

@media (max-width: 720px) {
  .export-packages-page.is-v4 .export-packages-mix__board {
    grid-template-columns: minmax(0, 1fr);
  }

  .export-packages-page.is-v4 .export-packages-mix__stage {
    grid-template-columns: minmax(0, 1fr);
    justify-items: start;
    max-width: none;
  }

  .export-packages-page.is-v4 .export-packages-manifest__slip {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .export-packages-page.is-v4 .export-packages-manifest__seals {
    display: none;
  }

  .export-packages-page.is-v4 .export-packages-manifest__signal {
    grid-column: 2 / -1;
    justify-content: flex-start;
  }

  .export-packages-page.is-v4 .export-packages-attention {
    grid-template-columns: auto auto 1fr;
  }

  .export-packages-page.is-v4 .export-packages-attention__jump {
    grid-column: 1 / -1;
    justify-self: start;
  }
}
